INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('dd4b9d21-1dd1-5721-aeaf-87ab79ecdc96', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 5, 5, 'እኔ፦ በእስራኤል ላይ የሚገዛ ሰውን ከአንተ አላጠፋም ብዬ ለአባትህ ለዳዊት እንደ ተናገርሁ፥ የመንግሥትህን ዙፋን በእስራኤል ላይ ለዘለዓለም አጸናለሁ።'),
  ('e3570d73-4bd4-51eb-a497-e3740a895164', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 6, 6, 'ነገር ግን እናንተና ልጆቻችሁ እኔን ትታችሁ ወደ ኋላ ብትመለሱ ለሙሴ በፊታችሁ የሰጠሁትን ትእዛዜንና ሥርዐቴን ባትጠብቁ፥ ሄዳችሁም ሌሎችን አማልክት ብታመልኩ፥ ብትሰግዱላቸውም፥'),
  ('8504ca16-07ab-58da-a3b6-f89fa8bfffe5', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 7, 7, 'እስራኤልን ከሰጠኋቸው ምድር አጠፋቸዋለሁ፤ ለስሜም የቀደስሁትን ይህን ቤት ከፊቴ እጥለዋለሁ፤ እስራኤልም በአሕዛብ ሁሉ መካከል ለጥፋትና ለተረት ይሆናሉ።'),
  ('dbb7765b-a9a7-58bc-a255-f62c8213e19a', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 8, 8, 'ከፍ ከፍ ብሎ የነበረውም ይህ ቤት ባድማ ይሆናል፤ በዚያም የሚያልፍ ሁሉ እያፍዋጨ፦ እግዚአብሔር በዚህ ሀገርና በዚህ ቤት ስለ ምን እንዲህ አደረገ? ብሎ ይደነቃል።'),
  ('1b6d8d15-b839-5c5b-a674-b458127ee477', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 9, 9, 'መልሰውም፦ ከግብፅ ምድር ከባርነት ቤት አባቶቻቸውን ያወጣውን አምላካቸውን እግዚአብሔርን ትተው ሌሎችን አማልክት ስለ ተከተሉ፥ ስለ ሰገዱላቸውም፥ ስለ አመለኩአቸውም፥ ስለዚህ እግዚአብሔር ይህን ክፉ ነገር ሁሉ አመጣባቸው ይላሉ።” ያንጊዜም ሰሎሞን የፈርዖንን ልጅ ከዳዊት ከተማ አውጥቶ በዚያ ወራት ለራሱ በሠራው ቤት አስገባት።'),
  ('d349f4b5-2265-5581-a4ae-493793692889', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 10, 10, 'ሰሎሞንም የእግዚአብሔርን ቤትና የንጉሡን ቤት ሁለቱን ቤቶች በሠራበት በሃያ ዓመት ውስጥ፥'),
  ('64924e00-ccd3-5cca-a912-31df5c66ec1a', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 11, 11, 'የጢሮስ ንጉሥ ኪራም በዝግባና በጥድ እንጨት፥ በወርቅና በሚሻውም ሁሉ ሰሎሞንን ረድቶት ነበር። ያንጊዜም ንጉሡ ሰሎሞን በገሊላ ምድር ያሉትን ሃያ ከተሞች ለኪራም ሰጠው።'),
  ('7695a8be-5d52-5317-a74a-9651efdf1da9', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 12, 12, 'ኪራምም ሰሎሞን የሰጠውን ከተሞች ያይ ዘንድ ከጢሮስ ወጣ፤ ወደ ገሊላም ሄደ፤ ደስም አላሰኙትም።'),
  ('867fdc39-dbb7-5b3e-af1d-2d476886ba0c', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 13, 13, 'እርሱም አለው፥ “ወንድሜ ሆይ! የሰጠኸኝ እነዚህ ከተሞች ምንድን ናቸው?” እስከ ዛሬም ድረስ ወሰን ብሎ ጠራቸው።'),
  ('99543e59-bd7b-536d-ad1a-a4f9536a4335', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 14, 14, 'ኪራምም መቶ ሃያ መክሊት ወርቅ ለሰሎሞን አመጣ።'),
  ('1b8c984b-f0ef-51c8-afe5-9438af77e3d9', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 15, 15, 'ንጉሡም ሰሎሞን የእግዚአብሔርን ቤትና ቤተ መንግሥቱን፥ ሜሎንንም፥ የኢየሩሳሌምንም ቅጥር፥ አሶርንም፥ መጊዶንም፥ ጋዜርንም ይሠራ ዘንድ ሠራተኞችን መልምሎ ነበር።'),
  ('659945d9-d0fd-53fc-a0b3-784518be37cb', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 16, 16, 'የግብፅም ንጉሥ ፈርዖን ወጥቶ ጋዜርን ያዘ፤ በእሳትም አቃጠላት፤ በሜርጎብ ይኖሩ የነበሩትን ከነዓናውያንንም ገደላቸው፤ ለልጁም ለሰሎሞን ሚስት እነዚያን አገሮች ትሎት አድርጎ ሰጥቶአት ነበር።'),
  ('401f2808-ded4-5aa9-abf6-3be46b2f3eda', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 17, 17, 'ሰሎሞንም ጋዜርንና የታችኛውን ቤቶሮንን፥ ባዕላትንም ሠራ፤'),
  ('ecabad6d-696d-5e41-ab63-0fbeda6c75eb', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 18, 18, 'በምድረ በዳ ሀገር ያለችውን ኤያቴርሞትን ሠራ፤'),
  ('f22bb867-e531-5f1c-aa18-4ff59b5fd560', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 19, 19, 'ለሰሎሞንም የነበሩትን የዕቃ ቤት ከተሞች ሁሉ፤ የሰረገላውንም ከተሞች፥ የፈረሰኞችንም ከተሞች፥ በኢየሩሳሌምም፥ በሊባኖስም፥ በመንግሥቱም ምድር ሁሉ ሰሎሞን ይሠራ ዘንድ የወደደውን ሁሉ ሠራ።'),
  ('7d69806a-9652-56e7-ad1a-a537f465fad7', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 20, 20, 'ከእስራኤልም ልጆች ዘንድ ያልነበሩትን ከአሞሬዎናውያንና ከኬጤዎናውያን፥ ከከናኔዎን፥ ከፌርዜዎናውያን፥ ከኤዌዎናውያን፥ ከኢያቡሴዎናውያንና ከጌርጌሴዎናውያን፥ የቀሩትን አሕዛብ ሁሉ፥ ከእነርሱም በኋላ በምድሪቱ የቀሩትን፥'),
  ('10cfd69c-a79f-584e-a880-69bcc23ad615', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 21, 21, 'የእስራኤልም ልጆች ያጠፉአቸው ዘንድ ያልቻሉትን፥ ልጆቻቸውን ሰሎሞን እሰከ ዛሬ ድረስ ገባሮች አድርጎ መለመላቸው።'),
  ('f6591b5f-218c-5dc8-ae22-d7ad212bb011', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 22, 22, 'ሰሎሞንም ከእስራኤል ልጆች ማንንም ገባር አላደረገም፤ እነርሱ ግን ተዋጊዎች፥ ሎሌዎችም፥ መሳፍንትም፥ አለቆችም፥ የሰረገሎችና የፈረሶች ባልደራሶች ነበሩ።'),
  ('236ff376-520d-523d-a8e4-bc21bf3b8322', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 23, 23, 'ሰሎሞንም በሚሠራው ሥራ ላይ ሠራተኛውን ሕዝብ የሚያዝዙ አለቆች አምስት መቶ አምሳ ነበሩ።'),
  ('3e29264c-c6f5-57fd-a5c0-4773aa9b73df', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 24, 24, 'የፈርዖንንም ልጅ ከዳዊት ከተማ ሰሎሞን ወደ ሠራላት ወደ ቤቷ አመጣት፤ በዚያ ጊዜም ሚሎንን ሠራት።'),
  ('677f23b9-5b66-5739-af50-fcd6ac93c328', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 25, 25, 'ሰሎሞንም በየዓመቱ ሦስት ጊዜ የሚቃጠለውንና የሰላሙን መሥዋዕት ለእግዚአብሔር በሠራው መሠዊያ ላይ ያሳርግ ነበር፤ በእግዚአብሔርም ፊት ባለው መሠዊያ ላይ ዕጣን ያሳርግ ነበር፤ ቤቱንም ጨረሰ።'),
  ('3fb8d4d3-6f35-5646-a4cf-b553edde35e2', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 26, 26, 'ንጉሡም ሰሎሞን በኤዶምያስ ምድር በኤርትራ ባሕር ዳር በኤላት አጠገብ ባለችው በጋሴዎንጋቤር መርከቦችን ሠራ።'),
  ('d5e5b25c-1eb4-5749-ad0f-aa956b6000b2', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 27, 27, 'ኪራምም በእነዚያ መርከቦች ከሰሎሞን አገልጋዮች ጋር ባሕሩን መቅዘፍ የሚያውቁ መርከበኞች አገልጋዮቹን ላከ።'),
  ('17a6eddc-af2a-5c72-a90a-6e13e33ecf35', '81d18790-1a6f-527c-a15d-a5ebf6ee8938', '2ac535d0-9b68-5822-a7f4-9473c3a5d734', 28, 28, 'ወደ አፌርም ደረሱ፤ ከዚያም አራት መቶ ሃያ መክሊት ወርቅ ወሰዱ፤ ወደ ንጉሡ ወደ ሰሎሞንም ይዘው አገቡ።'),
  ('3312bef9-a7e7-5692-a4ee-e853ee18e7ef', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 1, 1, 'የሳባም ንግሥት የሰሎሞንን ስም፥ የእግዚአብሔርንም ስም በሰማች ጊዜ ሰሎሞንን በእንቆቅልሽ ትፈትነው ዘንድ መጣች።'),
  ('76977103-04c5-5ddf-ad70-ce6377c6fa61', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 2, 2, 'በግመሎችም ላይ ሽቱና እጅግ ብዙ ወርቅ የከበረም ዕንቍ አስጭና ከታላቅ ጓዝ ጋር ወደ ኢየሩሳሌም ገባች፤ ወደ ሰሎሞንም በመጣች ጊዜ በልብዋ ያለውን ሁሉ ነገረችው።'),
  ('764ad9df-7137-5ba6-a18f-7dd0b3c791ca', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 3, 3, 'ሰሎሞንም የጠየቀችውን ሁሉ ፈታላት፤ ያልተረጐመላትና ከንጉሡ የተሰወረ ነገር አልነበረም።'),
  ('26740894-6af5-5b21-a0ee-fe280a836963', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 4, 4, 'የሳባም ንግሥት የሰሎሞንን ጥበብ ሁሉ፥ ሠርቶትም የነበረውን ቤት፥'),
  ('d99f8a22-73e4-5851-ae24-abd185cab4ca', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 5, 5, 'የሰሎሞንንም የማዕዱን መብል፥ የብላቴኖቹንም አቀማመጥ፥ የሎሌዎቹንም ሥርዐት፥ አለባበሳቸውንም፥ ጠጅ አሳላፊዎቹንም፥ በእግዚአብሔርም ቤት የሚያቀርበውን መሥዋዕት ባየች ጊዜ ተደነቀች።'),
  ('d147c048-42e6-5b9c-ab67-4e536954d64e', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 6, 6, 'ንጉሡን ሰሎሞንንም አለችው፥ “ስለ ነገርህና ስለ ጥበብህ በሀገሬ ሳለሁ የሰማሁት ዝና እውነት ነው።'),
  ('b69e5f55-db33-54b2-a6be-ee2b04570043', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 7, 7, 'እኔም መጥቼ በዐይኔ እስካይ ድረስ የነገሩኝን አላመንሁም ነበር ፤ እነሆም፥ እኩሌታውን አልነገሩኝም ነበር፤ በሀገሬ ሳለሁ ከነገሩኝ ይልቅ የበለጠ መልካም ተጨማሪ አየሁ።'),
  ('9cb19875-3085-5fe3-ab13-aa1e76c2cb02', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 8, 8, 'ሚስቶችህ የተመሰገኑ ናቸው፤ በፊትህ ሁልጊዜ የሚቆሙ፥ ጥበብህን የሚሰሙ እነዚህ አገልጋዮችህም ምስጉኖች ናቸው።'),
  ('2db0e6f0-812c-50b3-abb1-288e9cd7a1c0', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 9, 9, 'አንተን በእስራኤል ዙፋን ያስቀምጥህ ዘንድ የወደደ አምላክህ እግዚአብሔር የተመሰገነ ይሁን፤ እግዚአብሔር እስራኤልን ለዘለዓለም ያጸናው ዘንድ ወድዶታልና ስለዚህ በየነገራቸው ጽድቅና ፍርድ ታደርግ ዘንድ በላያቸው አነገሠህ።”'),
  ('c7c587e1-feee-5bd3-a938-62e5241495db', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 10, 10, 'ለንጉሡም መቶ ሃያ መክሊት ወርቅ እጅግም ብዙ ሽቶ፥ የከበረም ዕንቍ ሰጠችው፤ የሳባ ንግሥት ለንጉሡ ለሰሎሞን እንደ ሰጠችው ያለ የሽቶ ብዛት ከዚያ ወዲያ አልመጣም ነበር።'),
  ('b343bc2b-a937-57fb-af0e-dd7d36382315', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 11, 11, 'ከኦፌርም ወርቅ ያመጣች የኪራም መርከብ እጅግ ብዙ የተጠረበ እንጨትና የከበረ ዕንቍ አመጣች።'),
  ('c8590517-5527-5e8a-abe7-7e8c0c528643', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 12, 12, 'ንጉሡም ከተጠረበው እንጨት ለእግዚአብሔር ቤትና ለንጉሡ ቤት መከታ፥ ለመዘምራኑም መሰንቆና በገና አደረገ፤ እስከ ዛሬም ድረስ በምድር ላይ እንደዚያ ያለ የተጠረበ እንጨት ከቶ አልመጣም፤ በየትም ቦታ አልታየም።'),
  ('dc22395f-40ad-5ff6-a8f1-8eeb231c94be', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 13, 13, 'ንጉሡም ሰሎሞን በእጁ ከሰጣት ሌላ፥ የወደደችውን ሁሉ፥ ከእርሱም የጠየቀችውን ሁሉ ለሳባ ንግሥት ሰጣት፤ የከለከላትም የለም፤ እርስዋም ተመልሳ ከአገልጋዮችዋ ጋር ወደ ሀገርዋ ሄደች።'),
  ('632c6bb6-b1fd-5eac-a8d9-22230bc43d9c', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 14, 14, 'በየዓመቱ ለሰሎሞን የሚመጣለት የወርቅ ሚዛን ስድስት መቶ ስድሳ ስድስት መክሊት ወርቅ ነበረ።'),
  ('9c55795b-cdaf-5ab6-a854-fe8d141eab2b', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 15, 15, 'ይኽንም፥ ግብር የሚያስገብሩ ሰዎች፥ ነጋዴዎችም፥ በዙሪያው ያሉ ነገሥታትም ሁሉ፥ የምድርም ሹሞች ከሚያወጡት ሌላ ነው።'),
  ('8c9bf989-dca8-5a09-a7f2-d5043d4726f4', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 16, 16, 'ንጉሡ ሰሎሞንም ከጥፍጥፍ ወርቅ ሁለት መቶ አላባሽ አግሬ ጋሻ አሠራ፤ በአንዱም አላባሽ አግሬ ጋሻ ውስጥ የገባው ወርቅ ሦስት መቶ ሰቅል ነበረ።'),
  ('7ce66c8b-51ef-5282-a16e-54fcb102fe5d', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 17, 17, 'ከጥፍጥፍም ወርቅ ሦስት መቶ ጋሻ አሠራ፤ በአንዱም ጋሻ የገባው ወርቅ ሦስት ምናን ነው፤ ንጉሡም የሊባኖስ ዱር በተባለው ቤት ውስጥ አኖራቸው።'),
  ('fbfc1af4-a1f3-5671-a475-4210f765d21b', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 18, 18, 'ንጉሡም ደግሞ ከዝሆን ጥርስ ታላቅ ዙፋን አሠራ፤ በጥሩም ወርቅ ለበጠው።'),
  ('bc7aa0e1-864d-5f61-ad2e-e628df7aaa0e', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 19, 19, 'ወደ ዙፋንም የሚያስኬዱ ስድስት እርከኖች ነበሩ፤ በስተኋላውም ያለው የዙፋኑ ራስ ክብ ነበረ፤ በላም ምስል የተቀረጸ በወዲህና በወዲያም መደገፊያ ነበረው፤ በመደገፊያዎቹም አጠገብ ሁለት አንበሶች ቆመው ነበር፤'),
  ('f69532a8-f555-5ccd-a861-6b3a61597c32', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 20, 20, 'በስድስቱም እርከኖች ላይ በዚህና በዚያ ዐሥራ ሁለት አንበሶች ቆመው ነበር፤ በመንግሥታት ሁሉ እንዲህ ያለ ሥራ አልተሠራም።'),
  ('0756e345-4277-5fe3-a11d-944a579ac82d', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 21, 21, 'ንጉሡም ሰሎሞን ያሠራው የመጠጫ ዕቃ ሁሉ ወርቅ ነበረ፤ ኵስኵስቱም የወርቅ ነበረ፤ የሊባኖስ ዱር የተባለውን የዚያን ቤት ዕቃ ሁሉ በወርቅ አስለበጠው። የብርም ዕቃ አልነበረም፤ በሰሎሞን ዘመን የብር ዋጋ ዝቅተኛ ነበርና።'),
  ('0e7d72d7-1ef1-58dd-ae3f-eefa03c6a88c', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 22, 22, 'ለንጉሡም ከኪራም መርከቦች ጋር በባሕር ውስጥ የተርሴስ መርከቦች ነበሩት፤ በየሦስት ዓመትም አንድ መርከብ ከተርሴስ ወርቅና ብር፥ የተቀረጸና የተደረደረ ዕንቍ ይዞ ይመጣ ነበር።'),
  ('33d5b126-a440-5df2-adf8-13e626811347', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 23, 23, 'ንጉሡም ሰሎሞን በብልጥግናና በጥበብ ከምድር ነገሥታት ሁሉ እጅግ በልጦ ነበር።'),
  ('18e0cce5-dbc5-5ee8-a638-7ee8539576ec', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 24, 24, 'የምድርም ነገሥት ሁሉ እግዚአብሔር በልቡ ያኖረለትን ጥበቡን ይሰሙ ዘንድ የሰሎሞንን ፊት ለማየት ይሹ ነበር።'),
  ('73d409cc-692b-5d0c-a8fd-53db35b25db0', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 25, 25, 'እነርሱም ሁሉ በዓመት በዓመቱ ገጸ በረከቱን፥ የብርና የወርቅ ዕቃ፥ ልብስና የጦር መሣሪያ፥ ሽቱም፥ ፈረሶችና በቅሎዎች እየያዙ ይመጡ ነበር።'),
  ('10a293ef-01cf-5677-a348-54b2f82cfb73', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 26, 26, 'ሰሎሞንም ለሰረገሎቹ ዐራት ሺህ እንስት ፈረሶች ነበሩት፤ ዐሥራ ሁለት ሺህ ፈረሰኞችም ነበሩት፤ በሰረገሎችም ከተሞች ከንጉሡ ጋር በኢየሩሳሌም አኖራቸው። ሰሎሞንም ከወንዙ ጀምሮ እስከ ፍልስጥኤም ምድርና እስከ ግብፅ ድንበር ድረስ በነገሥታቱ ሁሉ ላይ ንጉሥ ነበር።'),
  ('fada1ebc-12c3-5674-a5ac-bd28a77f502f', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 27, 27, 'ንጉሡም ብሩንና ወርቁን በኢየሩሳሌም እንደ ድንጋይ እንዲበዛ አደረገው፤ የዝግባም እንጨት ብዛት በቆላ እንደሚበቅል ሾላ ሆነ።'),
  ('63f354a9-9d2a-5930-afad-98bcf53a1c65', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 28, 28, 'ሰሎሞንም ፈረሶችን ከግብፅና ከቴቁሄ ሀገር አስመጣ፤ የንጉሡም ነጋዴዎች በገንዘብ እየገዙ ከቴቁሄ ያመጡአቸው ነበር።'),
  ('d9a07a37-59ec-58ab-ad10-63aadb631266', 'ceccee83-24c9-5b5a-a293-8a296e7fcccc', 'f7f3f025-345a-59c7-a944-fea047fd9693', 29, 29, 'አንዱም ሰረገላ በስድስት መቶ፥ አንዱም ፈረስ በመቶ ኀምሳ ብር ከግብፅ ይወጣ ነበር። እንዲሁም ለኬጤዎናውያን ነገሥታትና ለሶርያ ነገሥታት ሁሉ በባሕሩ በኩል ያወጡላቸው ነበር።'),
  ('f94667d7-d5f2-5f20-aa53-052a6c31660d', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 1, 1, 'ንጉሡም ሰሎሞን ሴቶችን ይወድ ነበር፥ ከባዕዳን ሕዝብም የፈርዖንን ልጅ፥ ሞዓባውያትንና አሞናውያትን፥ ሶርያውያትንና ሲዶናውያትን፥ ኤዶማውያትንና አሞሬዎናውያትንም፥ ኬጤዎናውያትንም፦ ሚስቶችን አገባ።'),
  ('f769829b-88ac-5b14-a4ee-92f777865105', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 2, 2, 'እግዚአብሔር የእስራኤልን ልጆች፥ “አምላኮቻቸውን ትከተሉ ዘንድ ልባችሁን እንዳይመልሱ ወደ እነርሱ አትግቡ፥ እነርሱም ወደ እናንተ አይግቡ” ካላቸው ከአሕዝብ አገባ፤ ሰሎሞን ግን እነርሱን ተከተለ፤ ወደዳቸውም።'),
  ('fffff012-af6d-50ab-a895-225b151c106d', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 3, 3, 'ለእርሱም ሰባት መቶ ሚስቶችና ሦስት መቶ ቁባቶች ነበሩት።'),
  ('3cf5b2cb-2c4c-55ce-a9b3-6b6ce530ac79', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 4, 4, 'ከዚህ በኋላ ሰሎሞን በሸመገለ ጊዜ ልቡ እንደ አባቱ እንደ ዳዊት ልብ ከአምላኩ ከእግዚአብሔር ጋር አልነበረም። ከባዕድ ያገባቸው ሚስቶቹም ሌሎችን አማልክት ይከተል ዘንድ ልቡን መለሱት።'),
  ('53c1e356-bd25-55f7-a0b1-273af4f8d833', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 5, 5, 'ሰሎሞንም የሲዶናውያንን አምላክ አስጠራጢስን የአሞናውያንንም ርኵሰት ኮሞስን ተከተለ።'),
  ('c6a8007a-f706-5ec3-a6d2-dd988e72f7df', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 6, 6, 'ሰሎሞንም በእግዚአብሔር ፊት ክፉ ነገርን አደረገ፤ እንደ አባቱም እንደ ዳዊት እግዚአብሔርን አልተከተለውም።'),
  ('5267b935-537b-5565-a76b-db258077d02b', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 7, 7, 'ያንጊዜም ሰሎሞን ለሞአብ ርኵሰት ለኮሞስ፥ ለአሞን ልጆች ርኵሰት ለሞሎክ በኢየሩሳሌም አንጻር በአለው ተራራ ላይ መስገጃን ሠራ።'),
  ('49d93f20-a305-5070-aa1e-40b3e8ee0dd5', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 8, 8, 'ሰሎሞንም ልዩ ከሆኑ ከአሕዝብ ለአገባቸው ሚስቶቹ ሁሉ እንዲህ አደረገ፤ ለጣዖቶቻቸውም መሥዋዕትን ሠዋ፤ ዕጣንም አጠነ።'),
  ('ad88ff5b-49bc-59dd-a57f-c60014a7bb67', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 9, 9, 'ሁለት ጊዜም ከተገለጠለት ከእስራኤል አምላክ ከእግዚአብሔር ልቡናውን መልሶአልና እግዚአብሔር በሰሎሞን ላይ ቍጣን ተቈጣ።'),
  ('eaa8e4be-487b-58d3-a034-f065d5b3357c', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 10, 10, 'ስለዚህም ነገር ወደ ባዕድ አምልኮት እንዳይሄድ፥ እግዚአብሔርም ያዘዘውን ሁሉ ይጠብቅና ያደርግ ዘንድ አዘዘው፤ ልቡናው ግን እንደ አባቱ እንደ ዳዊት ልብ ከእግዚአብሔር ጋር ፍጹም አልሆነም።'),
  ('2bf57928-9d4c-578a-ad49-dde8933fd122', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 11, 11, 'እግዚአብሔርም ሰሎሞንን አለው፥ “ይህን ሠርተሃልና፥ ያዘዝሁህንም ትእዛዜንና ሕጌን አልጠብቅህምና መንግሥትህን ከአንተ ከፍዬ ለባሪያህ እሰጠዋለሁ።'),
  ('3fee0622-0fc5-5a09-abbf-17d264da445c', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 12, 12, 'ነገር ግን ከልጅህ እጅ እከፍለዋለሁ እንጂ ስለ አባትህ ስለ ዳዊት ይህን በዘመንህ አላደርግም።'),
  ('2f0b1c13-da75-5c58-aa3e-0a5d1a4c3fef', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 13, 13, 'ነገር ግን ስለ ባሪያዬ ስለ ዳዊትና ስለ መረጥኋት ሀገሬ ስለ ኢየሩሳሌም ለልጅህ አንድ ነገድ እሰጣለሁ እንጂ መንግሥቱን ሁሉ አልከፍልም።”'),
  ('c88c6584-d9d0-5adc-a8ae-44e7645b9ac8', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '28aca221-b4a4-5562-a3c0-8d312f3074ac', 14, 14, 'እግዚአብሔርም ኤዶማዊው አዴርን ከረምማቴር ወገን የኤልያዳሔ ልጅ ኤስሮምን የሲባ ንጉሥ ጌታውን አድረዓዛርን ጠላት አድርጎ በሰሎሞን ላይ አስነሣ። ሰዎችም ወደ እርሱ ተሰበሰቡ። የዓመፁም አበጋዝ እርሱ ነበር። ደማስቆንም እጅ አደረጋት። በሰሎሞንም ዘመን ሁሉ በእስራኤል ላይ ጠላት ሆነ። ኤዶማዊው አዴርም ከኤዶምያስ ነገሥታት ዘር ነበር።'),
  ('225c1add-271a-5d9e-a64b-932af34e2097', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 1, 15, 'ዳዊትም ኤዶምያስን ባጠፋ ጊዜ፥ የሠራዊቱም አለቃ ኢዮአብ ተወግተው የሞቱትን ሊቀብር በወጣ ጊዜ፥ የኤዶምያስንም ወንድ ሁሉ በገደለ ጊዜ፥'),
  ('771cfcef-dc89-5bc8-a5e0-941d97a60dbe', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 2, 16, 'ኢዮአብና እስራኤልም ሁሉ የኤዶምያስን ወንድ ሁሉ እስኪገድሉ ድረስ ስድስት ወር በዚያ ተቀምጠው ነበር።'),
  ('4bf15e42-6665-5121-ae19-3c1ce631a26b', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 3, 17, 'አዴር፥ ከእርሱም ጋር ከኤዶምያስ ሰዎች የሆኑ የአባቱ አገልጋዮች ሁሉ ኰበለሉ፤ ወደ ግብፅም ገቡ። አዴር ግን ገና ሕፃን ነበር።'),
  ('03de5069-20c3-598e-ab39-3fe7c1e42c1d', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 4, 18, 'ከምድያምም ተነሥተው ወደ ፋራን ሄዱ፤ ከእነርሱም ጋር ከፋራን ሰዎችን ወሰዱ፤ ወደ ግብፅም መጡ፤ ወደ ግብፅም ንጉሥ ወደ ፈርዖን ሄዱ፤ አዴርም ወደ ፈርዖን ገባ። እርሱም ቤት ሰጥቶ ቀለብ ዳረገው።'),
  ('86dc93fa-232f-55a9-a3bb-cace85604870', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 5, 19, 'አዴርም በፈርዖን ፊት እጅግ ባለምዋል ሆነ። የሚስቱንም የቴቄምናስን ታላቅ እኅት ሚስት አጋባው።'),
  ('3e15d944-37cc-5d2b-aaf9-4af0a9b1382e', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 6, 20, 'የቴቄምናስ እኅት ወንድ ልጅ ጌንባትን ለአዴር ወለደችለት፤ ቴቄምናስም በፈርዖን ልጆች መካከል አሳደገችው፤ ጌንባትም በፈርዖን ልጆች መካከል ነበረ።'),
  ('6cb34762-5b97-5716-af6c-6a294d3ea90e', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 7, 21, 'አዴርም በግብፅ ሳለ ዳዊት እንደ አባቶቹ እንዳንቀላፋ፥ የሠራዊቱም አለቃ ኢዮአብ እንደ ሞተ በሰማ ጊዜ አዴር ፈርዖንን፥ “ወደ ሀገሬ እሄድ ዘንድ አሰናብተኝ” አለው።'),
  ('c51c1c9e-837a-5e09-aa3c-6a0cae58a2ad', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 8, 22, 'ፈርዖንም፥ “እነሆ፥ ከእኔ ዘንድ ወደ ሀገርህ መሄድ የፈለግህ ምን አጥተህ ነው?” አለው። አዴርም፥ “አንዳች አላጣሁም፤ ነገር ግን ልሂድ” ብሎ መለሰ። አዴርም ወደ ሀገሩ ተመለሰ።'),
  ('d11c4efe-1c3f-541e-ab48-c5e4f08cd65e', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 9, 23, 'እግዚአብሔርም ደግሞ ከጌታው ከሱባ ንጉሥ ከአድርአዛር የኰበለለውን የኤልያዳን ልጅ ሬዞንን ጠላት አድርጎ አስነሣበት።'),
  ('430a62a3-d709-5fe9-aa18-8cba28b90bed', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 10, 24, 'ዳዊትም የሲባን ሰዎች በገደለ ጊዜ ሬዞን ሰዎችን ሰብስቦ የጭፍራ አለቃ ሆነ፤ ወደ ደማስቆም ሄዱ፥ በዚያም ተቀመጡ፤ በደማስቆም ላይ አነገሡት።'),
  ('eeb384fc-07ef-5398-a9df-2a0681a0dd93', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '92e4fff3-e57c-5c37-a666-77f8671bb79a', 11, 25, 'በሰሎሞንም ዘመን ሁሉ የእስራኤል ጠላት ነበረ። አዴርም ያደረጋት ክፋት ይህች ናት፤ እስራኤልን አስጨነቀ በኤዶምያስም ነገሠ።'),
  ('60dec0ad-8812-5207-a322-dbe7fb9c5cf2', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 1, 26, 'ከሳሪራ ሀገር የሆነ የኤፍሬማዊው የናባጥና ሳሩሃ የተባለች የመበለት ልጅ ኢዮርብዓም የሰሎሞን አገልጋይ ነበረ።'),
  ('eabc230d-d068-5718-ade3-94dda91ba8fc', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 2, 27, 'እርሱም ያደረገው ይህ ነው በንጉሡ በሰሎሞን ላይ እጁን አነሣ፤ ሰሎሞንም በዳርቻ ያለ ቅጥርንና የአባቱን የዳዊትን ከተማ ቅጥር ሠርቶ ጨረሰ።'),
  ('5a5293b3-f8bf-5cff-a97f-e1cea41bae7e', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 3, 28, 'ኢዮርብዓምም ጽኑዕ ኀያል ሰው ነበረ፤ ሰሎሞንም ጐልማሳው ኢዮርብዓም በሥራ የጸና መሆኑን ባየ ጊዜ በዮሴፍ ነገድ ሥራ ሁሉ ላይ ሾመው።'),
  ('cea4fe44-2df5-5db4-a1da-b7dfb55f6f0e', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 4, 29, 'ከዚህ በኋላም ኢዮርብዓም ከኢየሩሳሌም በወጣ ጊዜ ሴሎናዊው ነቢዩ አኪያ በመንገድ ላይ ተገናኘው፤ ከመንገድም ገለል አደረገው፤ አኪያም አዲስ ልብስ ለብሶ ነበር። ሁለቱም በሜዳ ነበሩ።'),
  ('f765299c-6404-595e-a503-0ec8a2f3d9b0', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 5, 30, 'አኪያም የለበሰውን አዲስ ልብስ ይዞ ከዐሥራ ሁለት ቀደደው።'),
  ('582d4f0f-1935-5367-ae9d-9bbfce9c4a93', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 6, 31, 'ኢዮርብዓምንም አለው፥ “ዐሥር ቅዳጅ ውሰድ፤ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላልና፦ እነሆ፥ ከሰሎሞን እጅ መንግሥቱን እለያታለሁ፤ ዐሥሩንም ነገዶች እሰጥሃለሁ።'),
  ('03278804-e606-5576-a97d-979169b00a7c', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 7, 32, 'ስለ ባሪያዬ ስለ ዳዊት ከእስራኤልም ሀገሮች ሁሉ ስለ መረጥኋት ከተማ ስለ ኢየሩሳሌም ግን ሁለት ነገድ ይቀሩለታል፤'),
  ('b531ae15-7d4b-5149-a3a5-eaf985c592dd', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 8, 33, 'ትቶኛልና፥ ለሲዶናውያንም ርኵሰት ለአስጠራጢስ፥ ለሞአብም አምላክ ለኮሞስ፥ ለአሞንም ልጆች አምላክ ለሞሎክ ሰግዶአልና፥ አባቱም ዳዊት እንዳደረገ በፊቴ ቅን ነገርን ያደርግ ዘንድ በመንገዶቼ አልሄደምና።'),
  ('43f15513-f3dd-5cf7-a03e-bc37fb3aa9b0', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 9, 34, 'መንግሥቱንም ሁሉ ከእጁ አልወስድም፤ ትእዛዜንና ሥርዐቴን ስለ ጠበቀው ስለ መረጥሁት ስለ ባሪያዬ ስለ ዳዊት ግን በዕድሜው ሁሉ አለቃ አደርገዋለሁ።'),
  ('1de3f0ac-e8e1-5b28-aff1-b4623bbbd8f0', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 10, 35, 'መንግሥቱንም ከልጁ እጅ እወስዳለሁ፤ ለአንተም ዐሥሩን ነገድ እሰጥሃለሁ።'),
  ('bcf35b90-6ebb-58d6-a3bf-f014b750a74a', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 11, 36, 'ስሜንም ባኖርሁባት በዚያች በመረጥኋት ከተማ በኢየሩሳሌም ለባሪያዬ ለዳዊት በፊቴ ሁልጊዜ መብራት ይሆንለት ዘንድ ለልጁ ሁለት ነገድን እሰጠዋለሁ።'),
  ('397b8534-6654-58d0-a5cb-2810e4ff24ad', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 12, 37, 'አንተንም እወስድሃለሁ፤ ነፍስህም በወደደችው ሁሉ ላይ አነግሥሃለሁ፤ በእስራኤልም ላይ ንጉሥ ትሆናለህ።'),
  ('bf7b8e06-3cc6-58f8-a77c-ca167cdf4f51', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 13, 38, 'ባሪያዬም ዳዊት እንዳደረገ፥ ያዘዝሁህን ሁሉ ብትሰማ፥ በመንገዴም ብትሄድ፥ በፊቴም የቀናውን ብታደርግ፥ ትእዛዜንና ሥርዐቴን ብትጠብቅ፥ ከአንተ ጋር እኖራለሁ፤ ለዳዊትም እንደ ሠራሁለት የታመነ ቤትን እሠራልሃለሁ፤ እስራኤልንም ለአንተ እሰጥሃለሁ።'),
  ('2f6d9b67-30dd-56cf-adf6-205a5ea1e7d2', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 14, 39, 'ስለዚህም የዳዊትን ዘር አስጨንቃለሁ፤ ነገር ግን በዘመን ሁሉ አይደለም።”'),
  ('69af9366-a783-5314-ad87-27a1a62bdb84', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '03056c0c-b361-5d08-aca0-40bd93348a59', 15, 40, 'ሰሎሞንም ኢዮርብዓምን ሊገድለው ወደደ፤ ኢዮርብዓምም ተነሥቶ ወደ ግብፅ ሀገር፥ ወደ ግብፅ ንጉሥ ወደ ሱስቀም ኰብልሎ ሄደ፥ ሰሎሞንም እስኪሞት ድረስ በግብፅ ተቀመጠ።'),
  ('8b07a0b8-1301-5f7e-aace-947bfcb2e372', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '7ffac21d-2442-5a0c-a36f-22c471be61d4', 1, 41, 'የቀረውም የሰሎሞን ነገር፥ ያደረገውም ሁሉ ጥበቡም ሁሉ፥ እነሆ፥ በሰሎሞን የታሪክ መጽሐፍ ተጽፎአል።'),
  ('293fd050-3c37-558c-affc-ab636e11449a', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '7ffac21d-2442-5a0c-a36f-22c471be61d4', 2, 42, 'ሰሎሞንም በኢየሩሳሌም በእስራኤል ሁሉ ላይ የነገሠበት ዘመን አርባ ዓመት ነበረ።'),
  ('7fb1ce96-c2a5-5fc4-a141-c9f69a87e319', 'b614da31-4a4a-53b2-af84-ef8676b9aa45', '7ffac21d-2442-5a0c-a36f-22c471be61d4', 3, 43, 'ሰሎሞንም እንደ አባቶቹ አንቀላፋ፥ በአባቱም በዳዊት ከተማ ተቀበረ፤ ልጁም ሮብዓም በፋንታው ነገሠ።'),
  ('67a75124-2817-5903-a9c6-45c948037397', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 1, 1, 'እስራኤልም ሁሉ ያነግሡት ዘንድ ወደ ሰቂማ መጥተው ነበርና ሮብዓም ወደ ሰቂማ ሄደ።'),
  ('1808c422-10a9-5a4d-a5a1-8858d19a8fd4', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 2, 2, 'እንዲህም ሆነ፥ የናባጥ ልጅ ኢዮርብዓም ገና በግብፅ ሳለ ይህን በሰማ ጊዜ፥ ኢዮርብዓም ከንጉሡ ከሰሎሞን ፊት ኰብልሎ በግብፅ ተቀምጦ ነበረ፤'),
  ('e6d447fd-dc63-5b9d-ab08-c5edf958f0ac', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 3, 3, 'በግብፅም ሳለ ልከው ጠሩት፤ ኢዮርብዓምና የእስራኤል ጉባኤ ሁሉ መጥተው ሮብዓምን እንዲህ ብለው አነጋገሩት፦'),
  ('a2ae788e-3046-5304-aa46-541b7ae9d120', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 4, 4, '“አባትህ ቀንበር አክብዶብን ነበር፤ አሁንም አንተ ጽኑውን የአባትህን አገዛዝ፥ በላያችንም የጫነውን የከበደውን ቀንበር አቃልልልን፤ እኛም እንገዛልሃለን።”'),
  ('a3743f24-5b38-5faf-aa8b-64ab3222fb6e', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 5, 5, 'እርሱም፥ “ሂዱ፥ በሦስተኛውም ቀን ወደ እኔ ተመለሱ” አላቸው። ሕዝቡም ሄዱ።'),
  ('80305849-d804-59da-a54d-2824de460a71', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 6, 6, 'ንጉሡም ሮብዓም፥ “ለዚህ ሕዝብ እመልስለት ዘንድ የምትመክሩኝ ምንድን ነው?” ብሎ አባቱ ሰሎሞን በሕይወቱ ሳለ በፊቱ ይቆሙ ከነበሩት ሽማግሌዎች ጋር ተማከረ።'),
  ('77f1c2a2-c25b-5754-a90d-83dff860fe8a', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 7, 7, 'እነርሱም፥ “ለዚህ ሕዝብ አሁን አገልጋይ ብትሆን፥ ብትገዛላቸውም፥ መልሰህም በገርነት ብትነግራቸው፥ በዘመኑ ሁሉ አገልጋዮችህ ይሆኑልሃል” ብለው ተናገሩት።'),
  ('2e067680-7d16-5d51-a565-08deb41f4d07', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 8, 8, 'እርሱ ግን ሽማግሌዎች የመከሩትን ምክር ትቶ ከእርሱ ጋር ካደጉትና በፊቱ ይቆሙ ከነበሩት ብላቴኖች ጋር ተማከረ።'),
  ('abfec955-4152-5027-a797-77a410b2642f', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 9, 9, 'እርሱም፥ “አባትህ የጫነብንን ቀንበር አቃልልልን ለሚሉኝ ሕዝብ እመልስላቸው ዘንድ የምትመክሩኝ ምንድን ነው?” አላቸው።'),
  ('3703abd7-7e5a-5824-a65d-ebdb68e33cf0', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 10, 10, 'ከእርሱም ጋር ያደጉት፥ በፊቱ የሚቆሙት ብላቴኖች እንዲህ አሉት፥ “አባትህ ቀንበር አክብዶብናል፥ አንተ ግን ዛሬ አቃልልልን ለሚሉህ ሕዝብ፦ ታናሺቱ ጣቴ ከአባቴ ወገብ ትወፍራለች።'),
  ('ecbdbfbf-fe11-56d6-af86-d48ca126d7ca', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 11, 11, 'አሁንም አባቴ ከባድ ቀንበር ጭኖባችኋል፥ እኔ ግን በቀንበራችሁ ላይ እጨምራለሁ፤ አባቴ በአለንጋ ገርፎአችኋል፥ እኔ ግን በጊንጥ እገርፋችኋለሁ በላቸው።” ይህም ቃል ሮብዓምን ደስ አሰኘው።'),
  ('b2b1884d-6fab-594c-ac7e-a2b7acba5abf', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 12, 12, 'ንጉሡም፥ “በሦስተኛው ቀን ወደ እኔ ተመለሱ” ብሎ እንደ ተናገረ ኢዮርብዓምና ሕዝቡ ሁሉ በሦስተኛው ቀን ወደ ሮብዓም መጡ።'),
  ('c1a074f7-4218-5fb1-a12a-51d6f71cff9e', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 13, 13, 'ንጉሡም ሽማግሌዎች የመከሩትን ምክር ትቶ ለሕዝቡ ጽኑ ምላሽ መለሰላቸው።'),
  ('f1ca4282-bbd2-5c5e-a608-48aec5ca2cba', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 14, 14, 'እንደ ብላቴኖችም ምክር፥ “አባቴ ቀንበር አክብዶባችሁ ነበር፥ እኔ ግን በቀንበራችሁ ላይ እጨምራለሁ፤ አባቴ በአለንጋ ገርፎአችሁ ነበር፥ እኔ ግን በጊንጥ እገርፋችኋለሁ” ብሎ ተናገራቸው።'),
  ('82d5298e-c08d-5a8a-acaf-a3d0eea4afbc', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 15, 15, 'እግዚአብሔርም በሴሎናዊው በአኪያ አፍ ለናባጥ ልጅ ለኢዮርብዓም የተናገረውን ነገር እንዲያጸና ለውጡ ከእግዚአብሔር ዘንድ ነበርና ንጉሡ ሕዝቡን አልሰማም።'),
  ('29687e3c-8ad8-516b-af0c-b9a7735e2e2d', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 16, 16, 'እስራኤልም ሁሉ ንጉሡ እንዳልሰማቸው ባዩ ጊዜ ሕዝቡ ለንጉሡ፥ “በዳዊት ዘንድ ምን ክፍል አለን? በእሴይም ልጅ ዘንድ ርስት የለንም። እስራኤል ሆይ፥ ወደ ድንኳኖቻችሁ ተመለሱ፤ ዳዊት ሆይ፥ አሁን የራስህን ቤት ተመልከት” ብለው መለሱለት። እስራኤልም ወደየቤታቸው ተመለሱ።'),
  ('b3c74b42-9f89-5814-a41c-131f764603ec', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 17, 17, 'በይሁዳ ከተሞች በተቀመጡት በእስራኤል ልጆች ላይ ግን ሮብዓም ነገሠ።'),
  ('ce275c02-a07c-5d97-a55c-484bd46b9776', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 18, 18, 'ንጉሡም ሮብዓም አስገባሪውን አዶኒራምን ላከ፤ እስራኤልም ሁሉ በድንጋይ ደበደቡት፥ ሞተም። ንጉሡም ሮብዓም ፈጥኖ ወደ ሰረገላው ወጣ፤ ወደ ኢየሩሳሌምም ሸሸ።'),
  ('3ddcab35-8ff7-51c3-acdf-d7c907c40635', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 19, 19, 'እስራኤልም እስከ ዛሬ ድረስ የዳዊትን ቤት ከዱት።'),
  ('82a838ec-4d39-528b-a1bc-af42272cfcd8', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 20, 20, 'ከዚህም በኋላ እስራኤል በሙሉ ኢዮርብዓም ከግብፅ እንደ ተመለሰ በሰሙ ጊዜ ልከው ወደ ሸንጎአቸው ጠሩት፤ በእስራኤልም ሁሉ ላይ አነገሡት። ከብቻው ከይሁዳና ከብንያም ነገድ በቀር የዳዊትን ቤት የተከተለ ማንም አልነበረም።'),
  ('2fffeaef-6594-535e-abb5-43cad768ba41', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 21, 21, 'ሮብዓም ግን ወደ ኢየሩሳሌም መጣ፤ የእስራኤልንም ቤት ወግተው መንግሥቱን ወደ ሰሎሞን ልጅ ወደ ሮብዓም ይመልሱ ዘንድ ከይሁዳ ቤት ሁሉና ከብንያም ነገድ የተመረጡትን አንድ መቶ ሃያ ሺህ ተዋጊዎች ሰዎችን ሰበሰበ።'),
  ('1b984c36-f610-59d0-a278-8ede7ddbdefd', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 22, 22, 'የእግዚአብሔርም ቃል ወደ እግዚአብሔር ሰው ወደ ሳማያ እንዲህ ሲል መጣ።'),
  ('afae7738-fe85-5247-a64e-2fe8fe47742c', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 23, 23, 'ለይሁዳ ንጉሥ ለሰሎሞን ልጅ ለሮብዓምና ለይሁዳ፥ ለብንያምም ቤት ሁሉ፥ ለቀረውም ሕዝብ ሁሉ፦ እንዲህ ብለህ ንገራቸው።'),
  ('c59a0053-10e8-5359-a50c-fc62e2012320', '678de62f-be06-5626-adb4-fad7abd717f2', '8aea423a-65b5-5c76-a031-942a5d4c0c79', 24, 24, '“እግዚአብሔር እንዲህ ይላል፦ ይህ ነገር ከእኔ ዘንድ ነውና አትውጡ፤ የእስራኤልንም ልጆች ወንድሞቻችሁን አትውጉ፤ እያንዳንዱም ወደ ቤቱ ይመለስ።” እነርሱም የእግዚአብሔርን ቃል ሰሙ፤ እንደ እግዚአብሔርም ቃል ተመልሰው ሄዱ።'),
  ('9e355995-ea41-5d93-a9e2-391e9269e577', '678de62f-be06-5626-adb4-fad7abd717f2', 'b3083e57-676f-57bc-aa10-ff34a8fcb24b', 1, 25, 'ኢዮርብዓምም በተራራማው በኤፍሬም ሀገር ሰቂማን ሠርቶ በዚያ ተቀመጠ፤ ደግሞም ከዚያ ወጥቶ ፋኑኤልን ሠራ።'),
  ('bac68fa8-17f6-58dd-a818-9c9ff43afc4c', '678de62f-be06-5626-adb4-fad7abd717f2', 'b3083e57-676f-57bc-aa10-ff34a8fcb24b', 2, 26, 'ኢዮርብዓምም በልቡ አለ፥ “እነሆ፥ ዛሬ መንግሥት ወደ ዳዊት ቤት ይመለሳል።'),
  ('0700b637-130a-5ace-ac08-48ae4cbdaec8', '678de62f-be06-5626-adb4-fad7abd717f2', 'b3083e57-676f-57bc-aa10-ff34a8fcb24b', 3, 27, 'ይህ ሕዝብ በኢየሩሳሌም በእግዚአብሔር ቤት መሥዋዕትን ያቀርብ ዘንድ ቢወጣ፥ የዚህ ሕዝብ ልብ ወደ ጌታቸው ወደ ይሁዳ ንጉሥ ወደ ሮብዓም ይመለሳል፥ እኔንም ይወጉኛል።”'),
  ('465fddf7-1355-5c56-abc1-216efacb4a66', '678de62f-be06-5626-adb4-fad7abd717f2', 'b3083e57-676f-57bc-aa10-ff34a8fcb24b', 4, 28, 'ንጉሡም ተማከረ፤ ሁለትም የወርቅ ጥጆች ሠርቶ፥ “እስራኤል ሆይ፥ ወደ ኢየሩሳሌም መውጣት ይበቃችኋል፤ ከግብፅ ምድር ያወጡአችሁ አማልክቶቻችሁ እነሆ” አላቸው።'),
  ('a3071cb3-f2d2-54d5-a1ed-738f006f1dac', '678de62f-be06-5626-adb4-fad7abd717f2', 'b3083e57-676f-57bc-aa10-ff34a8fcb24b', 5, 29, 'አንዱን በቤቴል ሁለተኛውንም በዳን አኖረ።'),
  ('b7bce187-5521-5cd7-a0cc-62e352543dcf', '678de62f-be06-5626-adb4-fad7abd717f2', 'b3083e57-676f-57bc-aa10-ff34a8fcb24b', 6, 30, 'ይህም ኀጢአት ሆነ፥ ሕዝቡ በዳን ወዳለች ወደ አንዲቱ ጣዖት ይሄዱ ነበርና።'),
  ('2777ad85-d451-5856-a4c7-843cf64da079', '678de62f-be06-5626-adb4-fad7abd717f2', 'b3083e57-676f-57bc-aa10-ff34a8fcb24b', 7, 31, 'በኮረብቶቹም ላይ መስገጃዎችን ሠራ፤ ከሌዊ ልጆች ካይደሉ ከማንኛውም ሕዝብ ሁሉ የጣዖት ካህናትን ሾመ።'),
  ('a0d50300-e37a-56f7-aa17-0ad2682b4a1a', '678de62f-be06-5626-adb4-fad7abd717f2', 'b3083e57-676f-57bc-aa10-ff34a8fcb24b', 8, 32, 'ኢዮርብዓምም በስምንተኛው ወር ከወሩም በዐሥራ አምስተኛው ቀን በይሁዳ እንደሚደረግ በዓል ያለ በዓል አደረገ፤ ለሠራቸውም ጥጆች ይሠዋ ዘንድ በቤቴል ወደ ሠራው መሠዊያ ወጣ፤ ለኮረብታ መስገጃዎችም የመረጣቸውን እነዚያን ካህናት በቤቴል አኖራቸው።'),
  ('51fa9a40-def6-50c9-ad53-d2470001d7aa', '678de62f-be06-5626-adb4-fad7abd717f2', 'b3083e57-676f-57bc-aa10-ff34a8fcb24b', 9, 33, 'በስምንተኛውም ወር በዐሥራ አምስተኛው ቀን በልቡ ባሰበው ቀን ወደ ሠራው መሠዊያ ወጣ፤ ለእስራኤልም ልጆች በዓል አደረገላቸው፤ ወደ መሠዊያውም ሊሠዋ ወጣ።'),
  ('c6462b08-df5b-578d-a795-d351f8a773ee', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '38d93c06-2bde-5a37-ab50-ce33243b1c34', 1, 1, 'እነሆም፥ አንድ የእግዚአብሔር ሰው በእግዚአብሔር ቃል ከይሁዳ ወደ ቤቴል መጣ፤ ኢዮርብዓምም መሥዋዕት ይሠዋ ዘንድ በመሠዊያው አጠገብ ቆሞ ነበር።'),
  ('50aa6b54-943f-5de1-aa87-ea68d6f1558d', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '38d93c06-2bde-5a37-ab50-ce33243b1c34', 2, 2, 'የእግዚአብሔርም ሰው በመሠዊያው ላይ፥ “መሠዊያ ሆይ፥ መሠዊያ ሆይ፥ እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ ስሙ ኢዮስያስ የሚባል ልጅ ለዳዊት ቤት ይወለዳል፤ ዕጣንም የሚያጥኑብህን የኮረብታ መስገጃዎቹን ካህናት ይሠዋብሃል፤ የሰዎቹንም አጥንት ያቃጥልብሃል” ብሎ በእግዚአብሔር ቃል ጠራ።'),
  ('27c14474-a343-551f-ac10-0e83ba5f3d68', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '38d93c06-2bde-5a37-ab50-ce33243b1c34', 3, 3, 'በዚያም ቀን፦ እግዚአብሔር የተናገረው ቃል ይህ ነው፤ “እነሆ፥ መሠዊያው ይሰነጠቃል፤ በውስጡም ያለው ስብ ይፈስሳል” ብሎ ምልክት ሰጠ።'),
  ('e4bfbc68-1eca-5d05-afc8-6aed91c65148', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '38d93c06-2bde-5a37-ab50-ce33243b1c34', 4, 4, 'ከዚህም በኋላ ንጉሡ ኢዮርብዓም የእግዚአብሔር ሰው በቤቴል ባለው መሠዊያ ላይ የተናገረውን ነገር በሰማ ጊዜ፥ ንጉሡ፥ “ያዙት” ብሎ እጁን ከመሠዊያው ላይ አነሣ። ከዚህም በኋላ በእርሱ ላይ የዘረጋት እጁ ደረቀች፤ ወደ እርሱም ይመልሳት ዘንድ አልተቻለውም።'),
  ('a0b9919e-926a-52df-a461-348bf90ebe64', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '38d93c06-2bde-5a37-ab50-ce33243b1c34', 5, 5, 'የእግዚአብሔርም ሰው በእግዚአብሔር ቃል እንደ ሰጠው ምልክት መሠዊያው ተሰነጠቀ፤ በውስጡም ያለው ስብ ፈሰሰ።'),
  ('049f5b8e-c992-588f-a72e-31021c291467', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '38d93c06-2bde-5a37-ab50-ce33243b1c34', 6, 6, 'ንጉሡም ኢዮርብዓም የእግዚአብሔርን ሰው፥ “አሁን የአምላክህን የእግዚአብሔርን ፊት ለምን፤ እጄም ወደ እኔ ትመለስ ዘንድ ስለ እኔ ጸልይ” አለው፥ የእግዚአብሔርም ሰው እግዚአብሔርን ለመነ፤ የንጉሡም እጅ ወደ እርሱ ተመለሰች። እንደ ቀድሞም ሆነች።'),
  ('a2787321-db1e-533c-a514-79522879ebbc', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '38d93c06-2bde-5a37-ab50-ce33243b1c34', 7, 7, 'ንጉሡም የእግዚአብሔርን ሰው፥ “ከእኔ ጋር ወደ ቤቴ ና፥ ምሳም ብላ፥ ስጦታም እሰጥሃለሁ” አለው።'),
  ('619cbfd5-b007-5cda-ac23-99d05f27efae', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '38d93c06-2bde-5a37-ab50-ce33243b1c34', 8, 8, 'የእግዚአብሔርም ሰው ንጉሡን፥ “የቤትህን እኩሌታ እንኳን ብትሰጠኝ ከአንተ ጋር አልገባም፤ በዚህም ስፍራ እንጀራን አልበላም፤ ውኃም አልጠጣም፤'),
  ('4e170be1-c97d-509e-ae76-740d9da8b120', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '38d93c06-2bde-5a37-ab50-ce33243b1c34', 9, 9, 'እንጀራም አትብላ፤ ውኃም አትጠጣ፤ በመጣህበት መንገድም አትመለስ ሲል እግዚአብሔር በቃሉ አዝዞኛልና” አለው።'),
  ('7ce52ae9-e466-59c5-a426-dfda30d684b9', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '38d93c06-2bde-5a37-ab50-ce33243b1c34', 10, 10, 'በሌላም መንገድ ሄደ፤ ወደ ቤቴልም በመጣበት መንገድ አልተመለሰም።'),
  ('71f84882-6db7-5397-a169-63ba39c5e584', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 1, 11, 'በቤቴልም አንድ ሽማግሌ ነቢይ ይኖር ነበር፤ ልጆቹም ወደ እርሱ መጥተው በዚያች ቀን የእግዚአብሔር ሰው በቤቴል ያደረገውን ሥራ ሁሉ ነገሩት፤ ደግሞም ለንጉሡ የተናገረውን ቃል ሁሉ ለአባታቸው ነገሩት፤ አባታቸውም ተቈጣቸው።'),
  ('e0014304-f6a5-549e-a751-a3396263db47', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 2, 12, 'አባታቸውም፥ “በየትኛው መንገድ ሄደ?” አላቸው። ልጆቹም ከይሁዳ የመጣው የእግዚአብሔር ሰው የሄደበትን መንገድ አመለከቱት።'),
  ('47f217f2-fa7b-5668-a027-792d7e0a513d', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 3, 13, 'ልጆቹንም፥ “አህያዬን ጫኑልኝ” አላቸው፥ አህያውንም ጫኑለት ተቀመጠበትም።'),
  ('9ded13d6-b2c8-572e-a3e3-bdbd91f259c0', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 4, 14, 'የእግዚአብሔርንም ሰው ተከትሎት ሄደ፤ ከዛፍ በታችም ተቀምጦ አገኘውና፥ “ከይሁዳ የመጣህ የእግዚአብሔር ሰው አንተ ነህን?” አለው። እርሱም፥ “አዎ፥ እኔ ነኝ” አለ።'),
  ('6fb23d51-19b9-55e5-a286-d6fa5fdf69e0', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 5, 15, 'እርሱም፥ “ከእኔ ጋር ወደ ቤቴ ና፥ እንጀራም ብላ” አለው።'),
  ('c6f4bf4e-2d5d-5bab-ac97-3cc34bb374cb', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 6, 16, 'እርሱም፥ “ከአንተ ጋር እመለስና እገባ ዘንድ አይቻለኝም፤ በዚህም ስፍራ ከአንተ ጋር እንጀራ አልበላም፤ ውኃም አልጠጣም፤'),
  ('9b5a4c26-434d-5c80-a203-4b932f045656', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 7, 17, 'በዚያ እንጀራ አትብላ፥ ውኃም አትጠጣ፤ በመጣህበት መንገድም አትመለስ ብሎ እግዚአብሔር በቃሉ አዝዞኛልና” አለው።'),
  ('19e98c44-5608-515c-a67e-a46a935fe3a8', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 8, 18, 'እርሱም፥ “እኔ ደግሞ እንዳንተ ነቢይ ነኝ፤ መልአክም፦ እንጀራ ይበላ ዘንድ ውኃም ይጠጣ ዘንድ ከአንተ ጋር ወደ ቤትህ መልሰው ብሎ በእግዚአብሔር ቃል ተናገረኝ” አለው። ዋሽቶም ተናገረው።'),
  ('328f8671-fb94-5c62-a144-47e5dc22d035', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 9, 19, 'መለሰውም፥ በቤቱም እንጀራ በላ፤ ውኃም ጠጣ።'),
  ('eb1ca5c2-e304-5e9a-a82f-a5b734cf46b0', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 10, 20, 'በማዕድም ተቀምጠው ሳሉ የእግዚአብሔር ቃል ወደ መለሰው ነቢይ መጣ፤'),
  ('82b87458-79ed-52a1-a6fb-6741d30a8bff', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 11, 21, 'ከይሁዳም የመጣውን የእግዚአብሔርን ሰው እንዲህ አለው፥ “እግዚአብሔር እንዲህ ይላል፦ በእግዚአብሔር ቃል ላይ አምፀሃልና፥ አምላክህ እግዚአብሔርም ያዘዘህን ትእዛዝ አልጠበቅህምና፥'),
  ('1b8b5c14-e2bc-5dc2-a5e1-81927269b8dd', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 12, 22, 'ተመልሰህም፦ እንጀራ አትብላ፥ ውኃም አትጠጣ ባለህ ስፍራ እንጀራ በልተሃልና፥ ውኃም ጠጥተሃልና ሬሳህ ወደ አባቶችህ መቃብር አይገባም።”'),
  ('d25c53b4-3145-51c8-a447-5d36bbdf5b72', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 13, 23, 'እንጀራም ከበላ፥ ውኃም ከጠጣ በኋላ ለተመለሰው ነቢይ አህያውን ጫኑለት።'),
  ('be6c21f1-8a3a-5b72-ab49-d567147f8601', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 14, 24, 'ተነሥቶም ሄደ፤ በመንገዱም ላይ አንበሳ አግኝቶ ገደለው፤ ሬሳውም በመንገድ ላይ ተጋድሞ ነበር፤ አህያውም በእርሱ አጠገብ ቆሞ ነበር፤ አንበሳውም ደግሞ በሬሳው አጠገብ ቆሞ ነበር።'),
  ('73a5e853-9dc4-532d-a787-98f97df794a1', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 15, 25, 'እነሆም፥ መንገድ አላፊ ሰዎች ሬሳውን በመንገዱ ወድቆ፥ አንበሳውም በሬሳው አጠገብ ቆሞ አዩ፤ ገብተውም ሽማግሌው ነቢይ ይኖርበት በነበረው ከተማ አወሩ።'),
  ('52653c1b-9713-58f5-a63f-4665252d41f9', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 16, 26, 'ያም ከመንገድ የመለሰው ነቢይ ያን ሰምቶ፥ “በእግዚአብሔር ቃል ላይ ያመፀ ያ የእግዚአብሔር ሰው ነው” አለ።'),
  ('c00e7115-249e-51e2-a542-be64fddedd3d', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 17, 27, 'ልጆቹንም፥ “አህያዬን ጫኑልኝ” አላቸው፤ እነርሱም ጫኑለት።'),
  ('b49b6782-e81c-5827-aa84-853b77211473', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 18, 28, 'ሄዶም፥ ሬሳው በመንገድ ወድቆ፥ በሬሳውም አጠገብ አህያውና አንበሳው ቆመው፥ አንበሳውም ሬሳውን ሳይበላው፥ አህያውንም ሳይሰብረው አገኘ።'),
  ('834399ff-c90c-5e0b-a6fb-cd739353962d', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 19, 29, 'ነቢዩም የእግዚአብሔርን ሰው ሬሳ አነሣ፤ በአህያውም ላይ ጫነው፤ ነቢዩም በራሱ መቃብር ይቀብረው ዘንድ ወደ ገዛ ከተማው አመጣው፤'),
  ('6c3c7427-82ab-5a79-abe7-d6b4db3fb40c', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 20, 30, 'ዋይ ዋይ፥ ወንድሜ ሆይ፥ እያሉም አለቀሱለት።'),
  ('ff213c6b-475c-5034-a35d-4faaf117063d', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 21, 31, 'ከቀበሩትም በኋላ ልጆቹን እንዲህ ብሎ ተናገራቸው፥ “በሞትሁ ጊዜ የእግዚአብሔር ሰው በተቀበረበት መቃብር ቅበሩኝ፤ አጥንቶቼ ከአጥንቶቹ ጋር ይድኑ ዘንድ አጥንቶቼን በአጥንቶቹ አጠገብ አኑሩ፤'),
  ('668481ad-f033-5975-ab1f-0cbfb990532d', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 22, 32, 'በቤቴል ባለው መሠዊያ ላይ፥ በሰማርያም ከተሞች ውስጥ ባሉት በኮረብታዎቹ መስገጃዎች ላይ በእግዚአብሔር ቃል የተናገረው ነገር በእውነት ይደርሳልና።”'),
  ('6e8ba775-53d7-5578-a727-72838f6af2c8', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 23, 33, 'ከዚህም በኋላ ኢዮርብዓም ከክፋቱ አልተመለሰም፤ ነገር ግን ለኮረብታዎቹ መስገጃዎች አብልጦ ከሕዝብ ሁሉ የጣዖት ካህናትን ሾመ፤ የሚወድደውንም ሁሉ ይቀድስ ነበር፤ እርሱም ለኮረብቶቹ መስገጃዎች ካህን ይሆን ነበር።'),
  ('f814478c-1551-5691-a96c-2d13e823adee', '5c4658ef-bcaf-55d6-a7b0-456d11729472', '8f4fe3bf-d53c-5ce6-a7ef-c6a53eb0dd87', 24, 34, 'ይህም ነገር ከገጸ ምድር ለመፍረስና ለመጥፋት በኢዮርብዓም ቤት ላይ ኀጢአት ሆነ።'),
  ('1c89a399-41fa-583c-a2b9-87d260ad0567', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 1, 1, 'በዚያም ወራት የኢዮርብዓም ልጅ አብያ እጅግ ታመመ።'),
  ('cc6d9d6b-60e0-5419-a3db-c03225771ced', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 2, 2, 'ኢዮርብዓምም ሚስቱ ሐኖንን፥ “ተነሺ፥ ራስሽን ለውጪ የኢዮርብዓምም ሚስት እንደ ሆንሽ ማንም አይወቅ፤ ወደ ሴሎም ሂጂ፤ ስለዚህም ሕፃን ከደዌው ይድን እንደሆነ ጠይቂ፤ እነሆ፥ በዚህ ሕዝብ ላይ እንደምነግሥ የነገረኝ ነቢዩ አኪያ በዚያ አለ።'),
  ('de227ae0-5f5c-550e-a686-4c349c10dfe7', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 3, 3, 'በእጅሽም ለእግዚአብሔር ሰው ዐሥር እንጀራና የወይን እሸት አንድም ማሠሮ ማር ይዘሽ ወደ እርሱ ሂጂ፤ በልጁም የሚሆነውን ይነግርሻል” አላት።'),
  ('856ec9e7-281f-5be3-a596-6bf9f0f7b2f8', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 4, 4, 'የኢዮርብዓምም ሚስት እንዲሁ አደረገች፤ ተነሥታም እንጀራ፥ የወይን ዘለላና አንድ ማሠሮ ማር በመያዝ ወደ ሴሎ ሄደች፤ ወደ አኪያም ቤት ገባች። አኪያ ግን ስለ መሸምገሉ ዐይኖቹ ፈዝዘው ነበርና ማየት አልቻለም።'),
  ('378330c7-69fe-52a1-a502-04a1a4a2a3fc', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 5, 5, 'እግዚአብሔርም አኪያን፥ “እነሆ፥ ስለ ታመመው ልጅዋ ትጠይቅህ ዘንድ የኢዮርብዓም ሚስት ትመጣለች፤ ራስዋንም ለውጣ ወደ አንተ በገባች ጊዜ እንዲህና እንዲህ በላት” አለው።'),
  ('50a2b877-6708-5abc-ab52-260bcc0efdde', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 6, 6, 'እርስዋም በደጅ ስትገባ አኪያ የእግርዋን ኮቴ ሰማ፤ እንዲህም አላት፥ “የኢዮርብዓም ሚስት ሆይ፥ ግቢ! ስለምንስ ራስሽን ለወጥሽ? እኔም የሚያስጨንቅ ወሬ ይዤ ወደ አንቺ ተልኬአለሁ።'),
  ('45dff2af-2a22-56d1-a416-d0e03347e484', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 7, 7, 'ሂጂ ለኢዮርብዓም እንዲህ በዪው፦ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ከሕዝብ መካከል ለይቼ ከፍ አድርጌህ ነበር፤ በሕዝቤ በእስራኤል ላይም ንጉሥ አድርጌህ ነበር።'),
  ('f0a078ed-09a8-5e16-af2b-a2ea19bea83a', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 8, 8, 'ከዳዊትም ቤት፤ መንግሥቱን ከፍዬ ሰጥቼህ ነበር፤ ነገር ግን በፍጹም ልቡ እንደ ተከተለኝ፥ በፊቴም ቅን ነገር ብቻ እንዳደረገ፥ ትእዛዜንም እንደ ጠበቀ እንደ ባሪያዬ እንደ ዳዊት አልሆንህም።'),
  ('4a479c2e-9bfb-50d7-a1d2-d3a1b12c7d23', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 9, 9, 'ከአንተም አስቀድመው ከነበሩት ሁሉ ይልቅ ክፉ ሠራህ፤ ታስቈጣኝም ዘንድ ሄደህ ሌሎችን አማልክትና ቀልጠው የተሠሩትን ምስሎች አደረግህ፤ ወደ ኋላህም ተውኸኝ።'),
  ('e813ca18-1b77-5604-a66f-66f0317ef783', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 10, 10, 'ስለዚህ እነሆ፥ በኢዮርብዓም ቤት ላይ መከራን አመጣለሁ፤ ኢዮርብዓምንም አጠፋዋለሁ፤ አጥር ተጠግቶ እስከሚሸን ወንድ ድረስ አላስቀርለትም፤ በእስራኤልም ላይ ይነግሥ ዘንድ አልተወውም፤ ሰው ገለባ እስኪያልቅ ድረስ እንደሚያነድድ በኢዮርብዓም ቤት ላይ እሳትን አነዳለሁ።'),
  ('295ad02b-4117-5758-aa63-a1307c03a291', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 11, 11, 'እግዚአብሔር እንደ ተናገረ ከኢዮርብዓም ወገን በከተማዪቱ ውስጥ የሞተውን ውሾች ይበሉታል፤ በሜዳውም የሞተውን የሰማይ ወፎች ይበሉታል።'),
  ('a05915cb-583a-57ba-aedb-a409623fd2da', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 12, 12, 'እንግዲህ ተነሥተሽ ወደ ቤትሽ ሂጂ፤ እግርሽም ወደ ከተማ በገባ ጊዜ ልጅሽ ይሞታል።'),
  ('5daf6082-9152-5678-abec-c69597c11d65', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 13, 13, 'ደንገጡሮችሽም ሊቀበሉሽ ይወጣሉ፤ ልጅሽም ሞተ ይሉሻል፥ እስራኤልም ሁሉ ያለቅሱለታል፤ ይቀብሩትማል፤ በእስራኤል አምላክ በእግዚአብሔር ዘንድ በኢዮርብዓም ቤት በዚህ ልጅ መልካም ነገር ተገኝቶበታልና ከኢዮርብዓም እርሱ ብቻ ይቀበራል።'),
  ('877d1a6f-1c33-51bf-ad85-2b903d91950c', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 14, 14, 'እግዚአብሔር ደግሞ የኢዮርብዓምን ቤት የሚያጠፋ ንጉሥ በእስራኤል ላይ ያነግሣል፤ እርሱም ዛሬ ይደረጋል፤ እንግዲህ ወዲህ ምን እናገራለሁ?'),
  ('7d387d2c-8a61-5feb-a23b-e27b92ded61a', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 15, 15, 'በዚያ ጊዜም ሸምበቆ በውኃ ውስጥ እንደሚንቀሳቀስ እግዚአብሔር እንዲሁ እስራኤልን ይመታል፤ እግዚአብሔርንም ያስቈጡ ዘንድ የማምለኪያ አፀድ ተክለዋልና ለአባቶቻቸው ከሰጣቸው ከዚች ከመልካሚቱ ምድር እስራኤልን ይነቅላል፤ በወንዙም ማዶ ይበትናቸዋል።'),
  ('f732c21b-985b-5592-a634-1bd64465c656', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 16, 16, 'ስለ በደለውና እስራኤልንም ስላሳተበት ስለ ኢዮርብዓም ኀጢአት እስራኤልን ይጥላል።”'),
  ('bf4e798f-56d7-5997-a904-265bd0dac235', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 17, 17, 'የኢዮርብዓምም ሚስት ተነሥታ ሄደች፤ ወደ ቴርሳም መጣች፤ ወደ ቤቱም መድረክ በገባች ጊዜ ልጁ ሞተ።'),
  ('bb964410-de94-5b9d-aa7e-1e0a9aea45ee', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 18, 18, 'በባሪያውም በነቢዩ በአኪያ እንደ ተነገረው እንደ እግዚአብሔር ቃል እስራኤል ሁሉ ቀበሩት፥ አለቀሱለትም።'),
  ('f48d8691-8d16-5011-a549-bbc28d277f0b', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 19, 19, 'የቀረውም የኢዮርብዓም ነገር፥ እንዴት እንደ ተዋጋ፥ እንዴትም እንደ ነገሠ፥ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ ተጽፎአል።'),
  ('41915c17-9038-59c4-a7dd-8188f06e3ffa', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '70e10e05-63c8-5f34-a494-58e4f8ac9d03', 20, 20, 'ኢዮርብዓምም የነገሠበት ዘመን ሃያ አራት ዓመት ነበረ፥ ከአባቶቹም ጋር አንቀላፋ፥ ልጁም ናባጥ በፋንታው ነገሠ።'),
  ('e9d9eef8-6ae8-58e3-a336-639575e9c0b3', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 1, 21, 'የሰሎሞንም ልጅ ሮብዓም በይሁዳ ነገሠ፤ ሮብዓምም ንጉሥ በሆነ ጊዜ የአርባ አንድ ዓመት ጐልማሳ ነበረ፤ እግዚአብሔርም ስሙን ያኖርባት ዘንድ ከእስራኤል ነገድ ሁሉ በመረጣት ከተማ በኢየሩሳሌም ዐሥራ ሰባት ዓመት ነገሠ፤ የእናቱም ስም ናዕማ ነበረ፥ እርስዋም አሞናዊት ነበረች።'),
  ('a9df69a7-18ef-5323-a681-e613e51e2396', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 2, 22, 'ሮብዓምም በእግዚአብሔር ፊት ክፉ ሠራ፤ አባቶቹ በሠሩት ኀጢአትና በደል ሁሉ እንደ አስቀኑት በሠራው ኀጢአት አስቀናው።'),
  ('4998d63b-d171-5619-a8ba-569dc8e3e37b', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 3, 23, 'እነርሱም ደግሞ ከፍ ባለው ኮረብታ ሁሉ ላይ፥ ቅጠሉም ከለመለመ ዛፍ ሁሉ በታች መስገጃዎችን ሠሩ፤ ሐውልቶችንና የማምለኪያ አፀዶችንም ለራሳቸው አቆሙ።'),
  ('0329b6bf-ccd2-5ac1-a5f4-57784050a380', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 4, 24, 'በምድርም ሁሉ ዐመፅ ነበረ፥ ከእስራኤልም ልጆች ፊት እግዚአብሔር ያሳደዳቸው የአሕዛብን ርኵሰት ሁሉ ያደርጉ ነበር።'),
  ('f96e7218-489f-57e4-aa7e-9f689ce15c7e', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 5, 25, 'ሮብዓምም በነገሠ በአምስተኛው ዓመት የግብፅ ንጉሥ ሱስቀም በኢየሩሳሌም ላይ ዘመተ።'),
  ('2775fafa-44aa-5f4a-a200-7133950ead68', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 6, 26, 'የእግዚአብሔርን ቤተ መዛግብትና የንጉሡን ቤተ መዛግብት ሁሉ ወሰደ፤ ዳዊትም ከሱባ ንጉሥ ከአድርዓዛር ልጆች እጅ ወስዶ ወደ ኢየሩሳሌም ያመጣቸውን የወርቅ ጦሮችና ሰሎሞን የሠራቸውን የወርቁን ጋሻና ጦር ሁሉ ወደ ግብፅ ወሰደ።'),
  ('c30644e4-f2db-5afd-a083-c53afd08f79b', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 7, 27, 'ንጉሡም ሮብዓም በፋንታው የናስ ጋሾችን ሠራ፤ በፊቱም ለሚሮጡና የንጉሥን ቤት ደጅ ለሚጠብቁ የዘበኞች አለቆች ሰጣቸው።'),
  ('65cfd071-dd2c-5911-a260-95d4d65c1fca', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 8, 28, 'ከዚህ በኋላ ንጉሡ ዘወትር ወደ እግዚአብሔር ቤት ሲገባ ዘበኞች ይሸከሙአቸው ነበር፤ መልሰውም በዘበኞች ቤት ውስጥ ያኖሩአቸው ነበር።'),
  ('ea72f190-4bc1-53d4-a8d3-7204f5a67df9', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 9, 29, 'የቀረውም የሮብዓም ነገር፥ ያደረገውም ሁሉ፥ በይሁዳ ነገሥታት ታሪክ መጽሐፍ እነሆ፥ ተጽፎአል።'),
  ('f39c3ed8-fe9c-5d3f-aae3-e4d20cf42fb9', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 10, 30, 'በዘመኑም ሁሉ በሮብዓምና በኢዮርብዓም መካከል ጦርነት ነበረ።'),
  ('f599c321-e812-56b4-a25e-48a011253140', '8e6cb8fe-abce-52df-adc6-91fc3211a149', '8120006c-ad5a-5178-aea1-009e4f35e7ff', 11, 31, 'ሮብዓምም ከአባቶቹ ጋር አንቀላፋ፥ በዳዊትም ከተማ ከአባቶቹ ጋር ተቀበረ። ልጁም አብያ በፋንታው ነገሠ።'),
  ('29d1428c-7118-5d97-aeb2-e53a0b09abf7', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 1, 1, 'የናባጥ ልጅ ኢዮርብዓም በነገሠ በዐሥራ ስምንተኛው ዓመት የሮብዓም ልጅ አብያ በይሁዳ ላይ ንጉሥ ሆነ።'),
  ('30e64fb9-39fc-5d01-a70b-d56bcc41aa1e', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 2, 2, 'በኢየሩሳሌምም ሦስት ዓመት ነገሠ፤ እናቱም መዓካ የተባለች የአቤሴሎም ልጅ ነበረች።'),
  ('75f76f95-a400-56b6-ac21-80f7741eb6a5', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 3, 3, 'ከእርሱም አስቀድሞ ባደረገው በአባቱ ኀጢአት ሁሉ ሄደ፤ ልቡም እንደ አባቱ እንደ ዳዊት ልብ ከአምላኩ ከእግዚአብሔር ጋር ፍጹም አልነበረም።'),
  ('7055539a-7d86-56fa-ab06-d0791f1897c1', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 4, 4, 'ነገር ግን ልጁን ከእርሱ በኋላ ያስነሣ ዘንድ፥ ኢየሩሳሌምንም ያጸና ዘንድ አምላኩ እግዚአብሔር ስለ ዳዊት በኢየሩሳሌም መብራትን አደረገለት፤'),
  ('c61ec150-0591-5753-a028-6867614af1fa', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 5, 5, 'ከኬጥያዊው ከኦርዮ ነገር በቀር ዳዊት በዘመኑ ሁሉ በእግዚአብሔር ፊት ቅን ነገርን አድርጎ ነበርና፥ ካዘዘውም ነገር ሁሉ ፈቀቅ አላለም ነበርና።'),
  ('09e94ccf-012c-55e7-a860-22755b52160c', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 6, 6, 'በኢዮርብዓምና በሮብዓም መካከል በዘመናቸው ሁሉ ጠብ ነበረ።'),
  ('26858108-1512-5ded-adc9-52f5ae632d8d', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 7, 7, 'የቀረውም የአብያ ነገር፥ ያደረገውም ሁሉ፥ በይሁዳ ነገሥታት ታሪክ መጽሐፍ እነሆ፥ የተጻፈ አይደለምን? በአብያና በኢዮርብአም መካከል ሰልፍ ነበረ።'),
  ('c78fa241-5393-50a3-abe4-7d1a969ef369', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 8, 8, 'ኢዮርብዓም በነገሠ በሃያ አራተኛ ዓመቱ አብያ ከአባቶቹ ጋር አንቀላፋ፤ በዳዊትም ከተማ ቀበሩት። ልጁም አሳ በፋንታው ነገሠ።'),
  ('d7c2e841-c18c-56a9-a838-1ef5fc882760', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 9, 9, 'በእስራኤልም ንጉሥ በኢዮርብዓም በሃያ አራተኛው ዓመት አሳ በይሁዳ ላይ ነገሠ።'),
  ('b4e7ec22-c962-5532-a6d5-9777f2670ab3', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 10, 10, 'በኢየሩሳሌምም አርባ አንድ ዓመት ነገሠ፤ እናቱም ሐና የተባለች የአቤሴሎም ልጅ ነበረች።'),
  ('5079e102-fb48-522e-ac3b-1eba64d765b2', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 11, 11, 'አሳም እንደ አባቱ እንደ ዳዊት በእግዚአብሔር ፊት ቅን ነገርን አደረገ።'),
  ('7afaba9f-fa56-51f1-aa17-1fccc80ce21b', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 12, 12, 'ከሀገሩም የጣዖታትን ምስል ሁሉ አስወገደ፥ አባቶቹም የሠሩአቸውን ጣዖታትን ሁሉ አጠፋ።'),
  ('50c1a4a1-af2d-5af4-aabb-b6ee6e9ebae8', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 13, 13, 'የማምለኪያ ዐፀድ ጣዖታትን ስለ ሠራች እናቱን ሐናን እቴጌ እንዳትሆን ሻራት፤ አሳም የማምለኪያ ዐፀዱን አስቈረጠው፥ በቄድሮንም ፈፋ አጠገብ በእሳት አቃጠለው።'),
  ('6effb9ef-39fa-519d-a864-57c09dbd78a5', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 14, 14, 'ነገር ግን በኮረብቶች ላይ ያሉትን መስገጃዎች አላራቀም፤ የአሳ ልብ ግን በዘመኑ ሁሉ ከእግዚአብሔር ጋር ፍጹም ነበረ።'),
  ('ea6be10d-a727-59b3-a3e5-b8d890015088', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 15, 15, 'አባቱ የቀደሰውንና እርሱም የቀደሰውን ወርቅና ብር፥ ዕቃውንም ወደ እግዚአብሔር ቤት አገባው።'),
  ('eab1f2d4-2c5e-5965-aff9-71c16c130e68', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 16, 16, 'አሳና የእስራኤል ንጉሥ ባኦስ በዘመናቸው ሁሉ ሲዋጉ ኖሩ።'),
  ('1a25a181-2ee3-5ea0-a109-84f219645501', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 17, 17, 'የእስራኤልም ንጉሥ ባኦስ በይሁዳ ላይ ወጣ፤ ከይሁዳ ንጉሥ ከአሳ ዘንድ ማንም እንዳይወጣ ወደ እርሱም ማንም እንዳይገባ አድርጎ ራማን ሠራት።'),
  ('d2211539-4e5c-5f51-ad03-02ac8ef95b68', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 18, 18, 'አሳም በእግዚአብሔር ቤትና በንጉሥ ቤተ መዛግብት የተገኘውን ብርና ወርቅ ሁሉ ወስዶ ለአገልጋዮቹ ሰጣቸው፤ ንጉሡም አሳ በደማስቆ ለተቀመጠው ለአዚን ልጅ ለጤቤርማን ልጅ ለሶርያ ንጉሥ ለወልደ አዴር፥'),
  ('a689350d-0a03-520b-a909-51e129941109', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 19, 19, '“በእኔና በአንተ መካከል በአባቴና በአባትህ መካከል ቃል ኪዳን ጸንቶአል፤ እነሆ፥ ብርና ወርቅ ገጸ በረከት ልኬልሃለሁ፤ እርሱ ከእኔ ዘንድ እንዲርቅ ሄደህ ከእስራኤል ንጉሥ ከባኦስ ጋር ያለህን ቃል ኪዳን አፍርስ” ብሎ ላከ።'),
  ('e667feb2-d8fe-545b-a537-0fbe9d5dfe24', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 20, 20, 'ወልደ አዴርም ለንጉሡ ለአሳ እሺ አለው፤ የሠራዊቱንም አለቆች በእስራኤል ከተሞች ላይ ሰድዶ ኢናንንና ዳንን፥ አቤልቤትመዓካንና ኬኔሬትን ሁሉ የንፍታሌምንም ሀገር ሁሉ መታ።'),
  ('a3edad52-9b9f-5761-a3da-734e610c6680', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 21, 21, 'ባኦስም ያን በሰማ ጊዜ ራማን መሥራት ትቶ ወደ ቴርሳ ተመለሰ።'),
  ('2278545c-4117-5543-a091-826a1f3c90d4', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 22, 22, 'ንጉሡም አሳ በይሁዳ ሁሉ ላይ አዋጅ ነገረ፤ ማንም ነጻ አልነበረም፥ ንጉሡ ባኦስም የሠራበትን የራማን ድንጋይና እንጨት ወሰደ፤ የይሁዳም ንጉሥ አሳ የብንያምንና የመሴፋን ኮረብታ ሠራበት።'),
  ('4869933c-d6e7-5b3d-a393-4586d8724c68', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 23, 23, 'የቀረውም የአሳ ነገር ሁሉ ብርቱ ሥራዎቹም ሁሉ፥ ያደረገውም ሁሉ፥ በይሁዳ ነገሥት ታሪክ የተጻፈ አይደለምን? ነገር ግን በሸመገለ ጊዜ እግሮቹ ታመሙ።'),
  ('974a516d-8a1e-5610-ae1a-7df25b6a3a48', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 24, 24, 'አሳም እንደ አባቶቹ አንቀላፋ፤ በአባቱም በዳዊት ከተማ ከአባቶቹ ጋር ተቀበረ። ልጁም ኢዮሣፍጥ በፋንታው ነገሠ።'),
  ('53138b78-b52e-5afa-a6b2-42146f307db7', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 25, 25, 'በይሁዳም ንጉሥ በአሳ በሁለተኛው ዓመት የኢዮርብዓም ልጅ ናባጥ በእስራኤል ላይ ነገሠ፤ በእስራኤልም ላይ ሁለት ዓመት ነገሠ።'),
  ('dac556f4-b520-5e0c-aadf-ab1c2df161d5', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 26, 26, 'በእግዚአብሔርም ፊት ክፉ አደረገ፤ በአባቱም መንገድ እስራኤልንም ባሳተበት ኀጢአት ሄደ።'),
  ('d702a7a3-95d1-5bbb-aadf-ecd9f17b4723', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 27, 27, 'ከበለዓን ቤት የሆነ የአኪያ ልጅ ባኦስ ዐመፀበት፤ ናባጥና እስራኤልም ሁሉ ገባቶንን ከብበው ነበርና ባኦስ በፍልስጥኤልም ሀገር ባለው በገባቶን ገደለው።'),
  ('bfb653bd-436b-5acb-a968-c0efa2403398', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 28, 28, 'በይሁዳ ንጉሥ በአሳ በሦስተኛው ዓመተ መንግሥት ባኦስ ናባጥን ገደለው፥ በፋንታውም ነገሠ።'),
  ('3d4320bc-54a6-5851-af9c-44f707e6d877', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 29, 29, 'ከነገሠም በኋላ የኢዮርብዓምን ወገን ሁሉ አጠፋ፥ በባሪያው በሴሎናዊው በአኪያ እጅ እንደ ተናገረው እንደ እግዚአብሔር ቃል፥ እስኪያጠፋው ድረስ ከኢዮርብዓም ወገን ሕይወት ያለውን አላስቀረም።'),
  ('524df63f-b31b-5d28-af34-f088430f140c', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 30, 30, 'ይኸውም ኢዮርብዓም ስለ ሠራው ኀጢአት፥ እስራኤልንም ስላሳተበት፥ የእስራኤልንም አምላክ እግዚአብሔርን ስላስቈጣበት ማስቈጣት ነው።'),
  ('dc27f9bc-5f31-5a74-a52e-95b1a58072f8', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 31, 31, 'የቀረውም የናባጥ ነገርና ያደረገውም ሁሉ፥ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('27125890-60a1-5f46-a27d-c10b5472e6e7', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 32, 32, 'በአሳና በእስራኤል ንጉሥ በባኦስ መካከል በዘመናቸው ሁሉ ጦርነት ነበረ።'),
  ('2d054496-e192-5496-a03f-74e168f2bdc8', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 33, 33, 'በይሁዳም ንጉሥ በአሳ በሦስተኛው ዓመት የአኪያ ልጅ ባኦስ በእስራኤል ሁሉ ላይ በቴርሣ ንጉሥ ሆኖ ሃያ አራት ዓመት ነገሠ።'),
  ('496d1285-7f6b-5526-afe3-380ccce7c85a', '9b30ec96-45c2-5c01-a416-3eaa74df8989', '4d842328-1a5e-52f8-aefa-3f9cb00029b3', 34, 34, 'በእግዚአብሔርም ፊት ክፉ አደረገ፥ በናባጥም ልጅ በኢዮርብዓም መንገድ እስራኤልንም ባሳተበት ኀጢአት ሄደ።'),
  ('c0536540-d55d-5686-ab31-af8c8aa8d37b', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 1, 1, 'የእግዚአብሔርም ቃል ስለ ባኦስ እንዲህ ብሎ ወደ አናኒ ልጅ ወደ ኢዩ መጣ።'),
  ('6daab53f-01f6-5748-a694-4c564d5c4010', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 2, 2, '“እኔ ከመሬት አንሥቼ በሕዝቤ በእስራኤል ላይ አለቃ አድርጌሃለሁ፤ አንተ ግን በከንቱ ጣዖታቸው ያስቈጡኝ ዘንድ ሕዝቤን እስራኤልን በአሳታቸው በኢዮርብዓም መንገድ ሄድህ፤'),
  ('342641cd-5d73-56d4-a07c-1cfc9395b08e', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 3, 3, 'ስለዚህም፥ እነሆ፥ ባኦስንና ቤቱን ፈጽሜ አጠፋለሁ፤ ቤትህንም እንደ ናባጥ ልጅ እንደ ኢዮርብዓም ቤት አደርጋለሁ።'),
  ('15cd415f-036c-5a74-a62a-3beaf6691c20', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 4, 4, 'ከባኦስም ወገን በከተማዪቱ ውስጥ የሚሞተውን ውሾች ይበሉታል፤ በሜዳውም የሚሞተውን የሰማይ ወፎች ይበሉታል።”'),
  ('22823e5a-685e-5215-a7a0-c7e11889e923', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 5, 5, 'የቀረውም የባኦስ ነገር፥ የሠራውም ሁሉ፥ ኀይሉም ሁሉ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ ነው።'),
  ('c106c208-dfb4-54bb-a64e-206abfbf07c1', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 6, 6, 'ባኦስም ከአባቶቹ ጋር አንቀላፋ፥ በቴርሳም ተቀበረ፤ ልጁም ኤላ በአሳ በሃያ ስድስተኛው ዓመተ መንግሥት በፋንታው ነገሠ።'),
  ('8dfc43ab-ad43-52a6-ab94-50bcf6ce9ce1', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 7, 7, 'በእጁም ሥራ ያስቈጣው ዘንድ፥ እንደ ኢዮርብዓም ቤት በእግዚአብሔር ፊት ስላደረገው ክፋት ሁሉ እርሱንም ስለ ገደለው፥ የእግዚአብሔር ቃል በባኦስና በቤቱ ላይ ወደ አናኒ ልጅ ወደ ነቢዩ ኢዩ መጣ።'),
  ('4e12ac87-8275-5072-adef-6e06980611d3', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 8, 8, 'የባኦስም ልጅ ኤላ በእስራኤል ላይ በቴርሳ ሁለት ዓመት ነገሠ።'),
  ('32f8dde6-b47b-56b9-a1da-4219d9d64b30', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 9, 9, 'የእኩሌቶቹ ፈረሶች አለቃ ዘምሪም አሽከሮቹን ሁሉ ሰብስቦ ዐመፀ፤ ኤላም በቴርሳ ነበረ፤ በቴርሳም በነበረው በመጋቢው በአሳ ቤት ይሰክር ነበር።'),
  ('758b745a-cad3-58df-a38e-05b03b5c3876', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 10, 10, 'በይሁዳም ንጉሥ በአሳ በሃያ ሰባተኛው ዓመት ዘምሪ ገብቶ ወጋና ገደለው፤ በፋንታውም ነገሠ።'),
  ('5f19dfe8-cc1a-5b72-a661-6bf9fe83a273', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 11, 11, 'ከነገሠና በዙፋኑም ከተቀመጠ በኋላ፥ የባኦስን ቤት ሁሉ አጠፋ፤ አንድ ወንድ እንኳ አላስቀረለትም።'),
  ('d3f53bfd-8474-56c6-a1ed-361f6d646ce4', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 12, 12, 'በነቢዩ በኢዩ አፍ በባኦስ ቤት ላይ እንደ ተናገረው እንደ እግዚአብሔር ቃል፥'),
  ('4fbc7b39-d393-51e1-a649-6d597480cef4', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 13, 13, 'ባኦስና ልጁ ኤላ ስለ ሠሩት ኀጢአት ሁሉ፥ በርኵሰታቸው የእስራኤልን አምላክ እግዚአብሔርን ያስቈጡት ዘንድ እስራኤልን ስለ አሳቱበት ኀጢአት፥ ዘምሪ የባኦስን ቤት ሁሉ እንዲሁ አጠፋ።'),
  ('f0915b29-7d33-59d2-a307-e94ab7320b33', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 14, 14, 'የቀረውም የኤላ ነገር፥ ያደረገውም ሁሉ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ ነው።'),
  ('a9b8380f-9095-5fbc-a295-314b8b9f515c', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 15, 15, 'በይሁዳም ንጉሥ በአሳ በሃያ ዘጠነኛው ዓመት ዘምሪ በቴርሳ ሰባት ቀን ነገሠ። የእስራኤል ሠራዊት ግን በፍልስጥኤም ሀገር በገባቶን ሰፍረው ነበር።'),
  ('ba3b625e-4cdf-53cf-a39c-e3c2abcb977b', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 16, 16, 'በሰፈር ያሉ ሕዝቡም “ዘምሪ ከድቶ ኤላን ገደለው፥ በፋንታውም ነገሠ” ሲሉ ሰሙ። እስራኤልም ሁሉ በዚያ ቀን በሰፈሩ ውስጥ የሠራዊቱን አለቃ ዘንበሪን አነገሡ።'),
  ('5ad8fa0d-6181-5b45-a26d-83e44dd35945', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 17, 17, 'ዘንበሪም ከእርሱም ጋር እስራኤል ሁሉ ከገባቶን ወጥተው ቴርሳን ከበቡ። በእርስዋም ተቀመጡ።'),
  ('1ae7832f-f737-516b-a3dd-e9bda0147453', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 18, 18, 'ዘምሪም ከተማዪቱ እንደ ተያዘች ባየ ጊዜ ወደ ንጉሡ ቤት ግንብ ውስጥ ገባ፤ የንጉሡንም ቤት በራሱ ላይ በእሳት አቃጠለ፤ ሞተም።'),
  ('fa2cebeb-5c79-54e8-aad2-2b0cc92218a6', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 19, 19, 'ስላደረገውም ኀጢአት፥ እስራኤልንም ስላሳተበት ኀጢአት፥ በእግዚአብሔር ፊት ክፉ አድርጎአልና፥ በናባጥ ልጅ በኢዮርብዓምም መንገድ ሄዶአልና ሞተ።'),
  ('7a5b2115-b4c2-5352-a8fb-62702d93be3a', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 20, 20, 'የቀረውም የዘምሪ ነገር፥ ያደረገውም ዐመፅ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ ነው።'),
  ('978903ad-4c00-54e2-a29a-543dcfaf695c', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 21, 21, 'በዚያም ጊዜ የእስራኤል ሕዝብ በሁለት ተከፈለ፤ የሕዝቡም እኩሌታ የጎናትን ልጅ ታምኒን ያነግሡት ዘንድ ተከተሉት፤ እኩሌቶችም ዘንበሪን ተከተሉ።'),
  ('679f6276-c850-5153-aea5-ed8d167b06fb', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 22, 22, 'ዘንበሪንም የተከተሉ ሕዝብ የጎናት ልጅ ታምኒን የተከተሉትን ሕዝብ ድል አደረጉአቸው፤ ታምኒም ሞተ፤ ወንድሙም ኢዮራም በዚያው ዘመን ሞተ፤ ከታምኒ በኋላ ዘንበሪ ነገሠ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('ef1e7d5f-e36f-567b-a800-5c0d8a0de584', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 23, 23, 'በይሁዳ ንጉሥ በአሳ በሠላሳ አንደኛው ዓመተ መንግሥት ዘንበሪ በእስራኤል ላይ ዐሥራ ሁለት ዓመት ነገሠ። በቴርሳም ስድስት ዓመት ነገሠ።'),
  ('a09bbfa1-cd35-5cbb-ad33-49988e7e9621', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 24, 24, 'ዘንበሪም ከዚያች ተራራ ባለቤት ከሴሜር በሁለት መክሊት ብር የሳምሮንን ተራራ ገዛ፤ በተራራውም ላይ ከተማ ሠራ፤ የሠራትንም ከተማ በተራራው ባለቤት በሳምር ስም ሰማርያ ብሎ ጠራት።'),
  ('60f2fce4-902d-550d-a1f9-dfcc8d532013', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 25, 25, 'ዘንበሪም በእግዚአብሔር ፊት ክፉ አደረገ፤ ከእርሱም አስቀድሞ ከነበሩት ይልቅ እጅግ ከፋ።'),
  ('6545cd90-a623-5800-a8af-ed58f361633d', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 26, 26, 'በናባጥም ልጅ በኢዮርብዓም መንገድ ሁሉ በርኩስነታቸው የእስራኤልን አምላክ እግዚአብሔርን ያስቈጡት ዘንድ እስራኤልን ባሳተበት ኀጢአት ሄደ።'),
  ('d8057e4a-223a-5e4f-a34c-8ad22c1c94fe', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 27, 27, 'የቀረውም ዘንበሪ ያደረገው ነገር፥ የሠራውም ጭከና፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ ነው።'),
  ('2a3a9239-5bde-5ed3-a559-3d2ba872921a', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'c84d2dc5-04c2-5d89-a9c0-7a3e269a7fef', 28, 28, 'ዘንበሪም ከአባቶቹ ጋር አንቀላፋ፥ በሰማርያም ቀበሩት፤ ልጁም አክአብ በፋንታው ነገሠ።'),
  ('2684b05a-1ddb-5e9b-a7c5-a431890ca753', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'fcf673bc-c61d-56ab-a285-2f56a85a26ba', 1, 29, 'በይሁዳም ንጉሥ በኢዮሳፍጥ በሁለተኛው ዓመት የዘንበሪ ልጅ አክዓብ በእስራኤል ላይ በሰማርያ ሃያ ሁለት ዓመት ነገሠ።'),
  ('f09bb44b-4f08-5221-a652-35e90fb65b68', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'fcf673bc-c61d-56ab-a285-2f56a85a26ba', 2, 30, 'አክዓብም ከእርሱ በፊት ከነበሩት ሁሉ ይልቅ በእግዚአብሔር ፊት ክፉ አደረገ።'),
  ('56d998a4-a7f8-5112-a385-3ddfab3fc44d', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'fcf673bc-c61d-56ab-a285-2f56a85a26ba', 3, 31, 'በናባጥም ልጅ በኢዮርብዓም ኀጢአት መሄድ አልበቃውም፤ የሲዶናውያንንም ንጉሥ የኤያትባሔልን ልጅ ኤልዛቤልን አገባ፤ ሄዶም በዓልን አመለከ ሰገደለትም።'),
  ('3deb9a96-3562-50b6-aa9a-d145088229f8', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'fcf673bc-c61d-56ab-a285-2f56a85a26ba', 4, 32, 'በሰማርያም በሠራው በበዓል ቤት ውስጥ ለበዓል መሠዊያን ሠራ።'),
  ('7c17e7df-8f0f-5395-acff-4323d867d1cf', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'fcf673bc-c61d-56ab-a285-2f56a85a26ba', 5, 33, 'አክዓብም የማምለኪያ ዐፀድን አሠራ፤ አክዓብም ሰውነቱ እንድትጠፋ ከእርሱ በፊት ከነበሩት ከእስራኤል ነገሥታት ሁሉ ይልቅ የእስራኤልን አምላክ እግዚአብሔርን የሚያስቈጣውን ነገር አበዛ።'),
  ('8ceed791-c15a-5c36-ac53-65044efa5511', '23cc01f8-c9ba-5a0b-a222-6cc2b300ebef', 'fcf673bc-c61d-56ab-a285-2f56a85a26ba', 6, 34, 'በእርሱም ዘመን የቤቴል ሰው አኪያል ኢያሪኮን ሠራ፤ በነዌም ልጅ በኢያሱ ቃል እንደ ተነገረው እንደ እግዚአብሔር ቃል፥ በበኵር ልጁ በአቢሮን መሠረቷን አደረገ፥ በታናሹ ልጁም በዜጉብ በሮችዋን አቆመ።'),
  ('4ceff13b-ce60-505f-a70b-253379313844', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', 'fff57ed0-af80-5502-ad4a-63a18dc9a27f', 1, 1, 'በገለዓድ ቴስባን የነበረው ቴስብያዊው ነቢዩ ኤልያስ አክዓብን፥ “በፊቱ የቆምሁት የኀያላን አምላክ የእስራኤል አምላክ ሕያው እግዚአብሔርን! ከአፌ ቃል በቀር በእነዚህ ዓመታት ዝናብም ጠልም አይወርድም” አለው።'),
  ('2b9044fb-5765-573b-a9af-6636bad45283', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', 'fff57ed0-af80-5502-ad4a-63a18dc9a27f', 2, 2, 'የእግዚአብሔርም ቃል ወደ ኤልያስ እንዲህ ሲል መጣ፦'),
  ('92b42049-0527-54ac-a681-cd4c9daf36a9', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', 'fff57ed0-af80-5502-ad4a-63a18dc9a27f', 3, 3, '“ከዚህ ተነሥተህ ወደ ምሥራቅ ሂድ፤ በዮርዳኖስም ትይዩ ባለው በኮራት ፈፋ ውስጥ ተሸሸግ።'),
  ('3da786a1-fac5-581d-a619-ed5090707372', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', 'fff57ed0-af80-5502-ad4a-63a18dc9a27f', 4, 4, 'ከፈፋው ትጠጣለህ፤ ቁራዎችም በዚያ ይመግቡህ ዘንድ አዝዣለሁ።” ሄደም፥ እግዚአብሔርም እንዳዘዘው አደረገ።'),
  ('d2a2b482-0450-545f-aa72-2131dde00e04', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', 'fff57ed0-af80-5502-ad4a-63a18dc9a27f', 5, 5, 'ሄዶም በዮርዳኖስ ትይዩ ባለው በኮራት ፈፋ ተቀመጠ።'),
  ('9e2cd5ba-365c-592d-ab8b-190f3886c563', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', 'fff57ed0-af80-5502-ad4a-63a18dc9a27f', 6, 6, 'ቁራዎችም በየጥዋቱና በየማታው እንጀራና ሥጋ ያመጡለት ነበር፤ ከፈፋውም ይጠጣ ነበር።'),
  ('14d49bff-9066-571b-a66e-c56a5a4d8566', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', 'fff57ed0-af80-5502-ad4a-63a18dc9a27f', 7, 7, 'ከብዙ ቀንም በኋላ በምድር ላይ ዝናብ አልነበረምና ፈፋው ደረቀ።'),
  ('a8b6e819-2ced-569c-a125-c9984960eb07', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 1, 8, 'የእግዚአብሔርም ቃል ወደ ኤልያስ መጣ እንዲህም አለው፦'),
  ('5a2eb0e2-9f24-52b6-a334-8631f8cbacfd', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 2, 9, '“ተነሥተህ በሲዶና አጠገብ ወዳለችው ወደ ሰራፕታ ሂድ፤ በዚያም ተቀመጥ፤ እነሆም፥ ትመግብህ ዘንድ አንዲት መበለት አዝዣለሁ።”'),
  ('22d8fd51-879a-5794-a840-6cb8751e8daf', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 3, 10, 'ተነሥቶም ወደ ሰራፕታ ሄደ፤ ወደ ከተማዪቱም በር በደረሰ ጊዜ አንዲት መበለት በዚያ እንጨት ትለቅም ነበር፤ ኤልያስም ጠርቶ፥ “የምጠጣው ጥቂት ውኃ በጽዋ ታመጭልኝ ዘንድ እለምንሻለሁ” አላት።'),
  ('7dd3eef8-4e53-5290-af2a-9c3839d6ed3f', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 4, 11, 'ውኃም ልታመጣለት በሄደች ጊዜ ወደ እርስዋ ጠርቶ፥ “እግረ መንገድሽን ቍራሽ እንጀራ በእጅሽ አምጭልኝ” አላት።'),
  ('26fb9c19-05af-5738-a4c8-a11226023050', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 5, 12, 'ሴትየዋም፥ “አምላክህ ሕያው እግዚአብሔርን! በማድጋ ካለው ከእፍኝ ዱቄት በማሰሮም ካለው ከጥቂት ዘይት በቀር እንጀራ የለኝም፤ እነሆም፥ ጥቂት እንጨት እሰበስባለሁ፤ ሄጄም ለእኔና ለልጄ እጋግረዋለሁ፤ በልተነውም እንሞታለን” አለችው።'),
  ('90b0a852-6877-5769-abe8-833fc13a602f', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 6, 13, 'ኤልያስም አላት፥ “በእግዚአብሔር እመኚ፤ አትፍሪ፤ ሄደሽም እንዳልሽው አድርጊ፤ አስቀድመሽ ግን ከዱቄቱ ለእኔ ታናሽ እንጎቻ አድርገሽ አምጭልኝ፥ ከዚያም በኋላ ለአንቺና ለልጅሽ አድርጊ፤'),
  ('8665a4b5-b5fb-5c87-ac00-e7300a65567e', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 7, 14, 'የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላልና፦ በምድር ላይ እግዚአብሔር ዝናብ እስከሚሰጥበት ቀን ድረስ፥ ዱቄቱ ከማድጋው አይጨረስም፥ ዘይቱም ከማሰሮው አይጐድልም።”'),
  ('25255ab8-2b5e-55ae-adb0-2817e265de91', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 8, 15, 'እርስዋም ሄዳ እንዲሁ አደረገች፤ እርስዋና እርሱ ልጆችዋም በሉ።'),
  ('7d0817b1-9749-56c0-ad35-eab9f072d7b3', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 9, 16, 'በአገልጋዩ በኤልያስም ቃል እንደ ተናገረው እንደ እግዚአብሔር ቃል ዱቄቱ ከማድጋው አልተጨረሰም፤ ዘይቱም ከማሰሮው አልጐደለም።'),
  ('a068823e-f6bf-56bf-a035-6512bd8cf5f7', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 10, 17, 'ከዚያም በኋላ የባለቤቲቱ የዚያች ሴት ልጅ ታመመ፤ ትንፋሹም እስኪታጣ ድረስ ደዌው እጅግ ከባድ ነበረ።'),
  ('0b2e1dbc-f291-55ea-aa97-ec247c5549c5', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 11, 18, 'እርስዋም ኤልያስን፥ “የእግዚአብሔር ሰው ሆይ፥ እኔ ከአንተ ጋር ምን አለኝ? አንተስ ከእኔ ጋር ምን አለህ? ኀጢአቴንስ ታሳስብ ዘንድ፥ ልጄንስ ትገድል ዘንድ ወደ እኔ መጥተሃልን?” አለችው።'),
  ('e6a14cc1-6437-54b5-a40a-520b2aaddbc9', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 12, 19, 'ኤልያስም፥ “ልጅሽን ስጪኝ” አላት፥ ከብብቷም ወስዶ ተቀምጦበት ወደ ነበረው ሰገነት አወጣው፤ በአልጋውም ላይ አስተኛው።'),
  ('32e7d7e5-1666-5382-a446-e655ae58a25b', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 13, 20, 'ኤልያስም፥ “እኔ በቤቷ ያደርሁ የዚች መበለት ምስክርዋ ጌታዬ ሆይ፥ ልጅዋን በመግደልህ ክፉ አድርገህባታልና ወዮልኝ!” ብሎ ጮኸ።'),
  ('1182c7f3-5031-5bee-a0fe-1fa2d1c1be6e', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 14, 21, 'በብላቴናውም ላይ ሦስት ጊዜ እፍ አለበት፤ ወደ እግዚአብሔርም፥ “አቤቱ አምላኬ ሆይ፥ የዚህ ብላቴና ነፍስ ወደ እርሱ ትመለስ ዘንድ እለምንሃለሁ” ብሎ እግዚአብሔርን ጠራው።'),
  ('3b7cbbeb-4195-5c95-a62a-966f6026139b', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 15, 22, 'እግዚአብሔርም የኤልያስን ቃል ሰማ፤ የሕፃኑም ነፍስ ተመለሰች፥ ዳነም፤'),
  ('e7bbdc35-51c3-5353-a4f2-6215b9607bbf', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 16, 23, 'ኤልያስም ብላቴናውን ይዞ ከሰገነቱ ወደ ቤት አወረደው፥ ለእናቱም ሰጣት፥ “እነሆ፥ ተመልከች ልጅሽ ድኖአል” አለ።'),
  ('0ed81c0e-c1fe-5d38-a7b6-4cc0f0cf6f06', 'a58e5f47-bbc0-59dd-a59b-87fac5d8570d', '1c25180f-ded2-5ef0-a9b9-0c1bba075dd1', 17, 24, 'ሴቲቱም ኤልያስን፥ “የእግዚአብሔር ሰው እንደ ሆንህ፥ የእግዚአብሔርም ቃል በአፍህ እውነት እንደ ሆነ አሁን ዐወቅሁ” አለችው።'),
  ('a9bfe71a-eff9-5fab-ac39-4e00a53a53e6', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 1, 1, 'ከብዙ ቀንም በኋላ በሦስተኛው ዓመት፥ “ሂድ ለአክዓብ ተገለጥ፤ በምድር ላይም ዝናም እሰጣለሁ” የሚል የእግዚአብሔር ቃል ወደ ኤልያስ መጣ።'),
  ('eb28b1f0-77e3-5ff3-abbc-d8dfe945e8a8', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 2, 2, 'ኤልያስም ለአክዓብ ይገለጥ ዘንድ ሄደ፤ በሰማርያም ራብ ጸንቶ ነበር።'),
  ('b94bf311-c7ac-52cc-acd1-36af35cd6bb2', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 3, 3, 'አክዓብም የቤቱን አዛዢ አብድዩን ጠራ፤ አብድዩም እግዚአብሔርን እጅግ ይፈራ ነበር።'),
  ('dd124bd7-7916-5111-aeff-1ee7d9810295', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 4, 4, 'ኤልዛቤልም የእግዚአብሔርን ነቢያት ባስገደለች ጊዜ አብድዩ መቶውን ነቢያት ወስዶ አምሳ አምሳውን በዋሻ ውስጥ ሸሽጎ እንጀራና ውኃ ይመግባቸው ነበር።'),
  ('e738516e-57b4-59b1-a1a8-d3a893c47796', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 5, 5, 'አክዓብም አብድዩን፥ “በሀገሩ መካከል ወደ ውኃ ምንጭ ሁሉና ወደ ፈፋ ሁሉ ና እንሂድ፤ እንስሶችም ሁሉ እንዳይጠፉ ፈረሶችንና በቅሎችን የምናድንበት ሣር ምናልባት እናገኝ እንደ ሆነ” አለው።'),
  ('c44dfb48-75db-5b9d-ab50-fbbf46ab839f', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 6, 6, 'በመንገድም ተለያይተው ሄዱ፤ አክዓብም ለብቻው በአንድ መንገድ፥ አብድዩም ለብቻው በሌላ መንገድ ሄዱ።'),
  ('3bb1bb8d-410b-5013-aafc-8f3399609468', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 7, 7, 'አብድዩም በመንገድ ብቻውን ሳለ እነሆ፥ ኤልያስ ሊገናኘው ብቻውን መጣ፤ አብድዩም ሮጠና፥ በግንባሩ ወድቆ ሰገደለት፥ “ጌታዬ ሆይ፥ ኤልያስ አንተ ነህን?” አለው።'),
  ('194dab1b-e6dd-57e1-ac38-89db1e30a805', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 8, 8, 'ኤልያስም፥ “አዎ እኔ ነኝ ሄደህ ለጌታህ፦ እነሆ፥ ኤልያስ በዚህ አለ በል” አለው።'),
  ('2d43b4f9-4f06-5503-a4ea-fb9a16cd547f', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 9, 9, 'አብድዩም አለ፥ “እኔን አገልጋይህን እንዲገድለኝ በአክዓብ እጅ አሳልፈህ ትሰጠኝ ዘንድ ምን በደልሁ?'),
  ('bd2f6af4-1aa4-51ff-a344-c9d482abe365', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 10, 10, 'አምላክህ ሕያው እግዚአብሔርን! ጌታዬ፥ ይፈልግህ ዘንድ ያልላከበት ሕዝብ ወይም መንግሥት የለም፤ ሁሉም፦ በዚህ የለም ባሉ ጊዜ አንተን እንዳላገኙ መንግሥቱንና ሕዝቡን አምሎአቸው ነበር።'),
  ('3739d827-4c2a-5fec-a7d3-777ca26ac9d5', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 11, 11, 'አሁንም፥ እነሆ፦ ሂድ፥ ኤልያስ አለ ብለህ ለጌታህ ንገር ትለኛለህ።'),
  ('48d4746a-aa7b-5f35-a27b-d62181d39315', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 12, 12, 'እኔም ከአንተ ጥቂት ራቅ ስል የእግዚአብሔር መንፈስ አንሥቶ ወደማላውቀው ስፍራ ይወስድሃል፤ እኔም ገብቼ ለአክዓብ ስናገር፥ ባያገኝህ ይገድለኛል፤ እኔም ባሪያህ ከትንሽነቴ ጀምሬ እግዚአብሔርን እፈራ ነበር።'),
  ('0dca16c6-ab4e-53b0-a158-1b4ec1671c70', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 13, 13, 'ኤልዛቤል የእግዚአብሔርን ነቢያት ባስገደለች ጊዜ፥ መቶውን የእግዚአብሔር ነቢያት ወስጄ፥ አምሳ አምሳውን በዋሻ ውስጥ ሸሽጌ፥ እንጀራና ውኃ የመገብኋቸውን፥ ይህን ያደረግሁትን ነገር በውኑ አንተ ጌታዬ አልሰማህምን?'),
  ('93a274f2-5509-5d8a-ad5f-3926642e47fe', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 14, 14, 'አሁንም፦ ሄደህ ኤልያስ አለ ብለህ ለጌታህ ንገር ትላለህ፤ እርሱም ይገድለኛል።”'),
  ('86da738f-372a-53fc-a113-1dac2857df35', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 15, 15, 'ኤልያስም፥ “በፊቱ የቆምሁት የሠራዊት ጌታ ሕያው እግዚአብሔርን! እኔ ዛሬ ለእርሱ እገለጣለሁ” አለው።'),
  ('38c348a4-34cd-5f15-ae20-b2c4e7089519', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 16, 16, 'አብድዩም ሄዶ አክዓብን ተገናኘው፤ ነገረውም፤ አክዓብም ሮጦ ሄዶ ኤልያስን ተገናኘው።'),
  ('c1882306-0700-5a4a-ac0b-8cc78b40d48e', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 17, 17, 'አክዓብም ኤልያስን ባየው ጊዜ፥ አክዓብ ኤልያስን፥ “እስራኤልን የምትገለባብጥ አንተ ነህን?” አለው።'),
  ('fa2e33e7-a10a-58b1-ad71-1ba8b0489afa', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 18, 18, 'ኤልያስም፥ “እግዚአብሔርን ትታችሁ በዓሊምን የተከተላችሁ፥ አንተና የአባትህ ቤት ናችሁ እንጂ እኔስ እስራኤልን አልገለባብጥም።'),
  ('14c3d6cd-02cd-5644-a58b-cb4e7fee7009', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 19, 19, 'አሁንም ወደ እስራኤል ሁሉ ልከህ፥ አራት መቶ ሃምሳ ነቢያተ ሐሰትን፥ አራት መቶ የማምለኪያ ዐፀድ ነቢያትን ወደ እኔ ወደ ቀርሜሎስ ተራራ ሰብስብ” አለው።'),
  ('70ce059c-16d4-5429-ac85-0a8dd3758ca7', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 20, 20, 'አክዓብም ወደ እስራኤል ልጆች ሁሉ ልኮ ነቢያቱን ሁሉ ወደ ቀርሜሎስ ተራራ ሰበሰባቸው።'),
  ('8f17091a-08f5-574f-a3ad-c44e9c5fda09', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 21, 21, 'ኤልያስም ወደ ሕዝቡ ሁሉ ቀርቦ፥ “እስከ መቼ በሁለት አሳብ ታነክሳላችሁ? እግዚአብሔር አምላክ ቢሆን እርሱን ተከተሉ፤ በዓልም አምላክ ቢሆን እርሱን ተከተሉ” አለ። ሕዝቡም አንዲት ቃል አልመለሱለትም።'),
  ('9d146495-4b54-58bb-a4e7-9114615d3af6', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 22, 22, 'ኤልያስም ሕዝቡን አለ፥ “ከእግዚአብሔር ነቢያት አንድ እኔ ብቻ ቀርቻለሁ፤ የበዓል ነቢያት ግን አራት መቶ ሃምሳ ሰዎች ናቸው። የማምለኪያ ዐፀድ ነቢያትም አራት መቶ ናቸው።'),
  ('5d9f216e-f1d8-564e-a131-745abb5d04b8', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 23, 23, 'ሁለት ወይፈኖች ይሰጡን፤ እነርሱም አንድ ወይፈን ይምረጡ፤ እየብልቱም ይቍረጡት፤ በእንጨትም ላይ ያኑሩት፤ በበታቹም እሳት አይጨምሩ፤ እኔም ሁለተኛውን ወይፈን አዘጋጃለሁ፤ በእንጨቱም ላይ አኖረዋለሁ፤ በበታቹም እሳት አልጨምርም።'),
  ('9a3a556a-f433-5077-a40a-91f6707628e8', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 24, 24, 'እናንተም የአምላካችሁን ስም ጥሩ፤ እኔም የፈጣሪዬን የእግዚአብሔርን ስም እጠራለሁ፤ ሰምቶም በእሳት የሚመልስ አምላክ፥ እርሱ አምላክ ይሁን።” ሕዝቡም ሁሉ፥ “ይህ ነገር መልካም ነው” ብለው መለሱ።'),
  ('4fbec3a3-1148-559d-a799-16bef0c4504f', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 25, 25, 'ኤልያስም የበዓልን ነቢያት፥ “እናንተ ብዙዎች ናችሁና አስቀድማችሁ አንድ ወይፈን ምረጡና አዘጋጁ፤ የአምላካችሁንም ስም ጥሩ፤ በበታቹም እሳት አትጨምሩ” አላቸው።'),
  ('f302cd88-7de5-5611-a817-5949e76dce85', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 26, 26, 'የተሰጣቸውን ወይፈንም ወስደው አዘጋጁ፤ ከጥዋትም እስከ ቀትር ድረስ፥ “በዓል ሆይ፥ ስማን፥” እያሉ የበዓልን ስም ጠሩ። ድምፅም አልነበረም፤ የሚመልስም አልነበረም፤ የሠሩትንም መሠዊያ እያነከሱ ይዞሩ ነበር።'),
  ('9c593054-e272-54e7-ab7c-ded35b867f54', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 27, 27, 'በቀትርም ጊዜ ቴስብያዊው ኤልያስ፥ “አምላክ ነውና በታላቅ ቃል ጩኹ፤ ምናልባት ይጫወት ይሆናል፥ ወይም አሳብ ይዞት ይሆናል፥ ወይም ተኝቶ እንደ ሆነ መቀስቀስ ያስፈልገዋል” እያለ ይዘባበትባቸው ጀመር።'),
  ('4fafee0f-5c49-5cf7-a8e5-ce55ffc7dd29', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 28, 28, 'በታላቅም ቃል ይጮኹ ጀመር፤ እንደ ልማዳቸውም ደማቸው እስኪፈስስ ድረስ ገላቸውን በጦርና በሰይፍ ይብዋጭሩ ነበር።'),
  ('c9eda7c3-274a-5431-ae6f-f52e446098e6', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'ddaf49e8-426e-52b4-a421-1c36128de10a', 29, 29, 'እስከ ሠርክም ድረስ ትንቢት ይናገሩ ነበር፤ ድምፅም አልነበረም፤ የሚመልስና የሚያደምጥም አልነበረም። ከዚህም በኋላ መሥዋዕት በሚያርግበት ጊዜ ኤልያስ ነቢያተ ሐሰትን፥ “እንግዲህስ ወዲያ በቃችሁ፤ ወግዱ፤ ሂዱም፥ እኔም መሥዋዕቴን እሠዋለሁ” አላቸው።'),
  ('56767b3f-ac69-5f09-ae58-7748efbc71fd', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 1, 30, 'ኤልያስም ሕዝቡን ሁሉ፥ “ወደ እኔ ቅረቡ” አላቸው። ሕዝቡም ሁሉ ወደ እርሱ ቀረቡ።'),
  ('6119ee03-1eed-51d5-aaac-687f55e36667', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 2, 31, 'ኤልያስም፦ ስምህ እስራኤል ይሆናል የሚል የእግዚአብሔር ቃል እንደ ደረሰለት እንደ እስራኤል ልጆች ነገድ ቍጥር ዐሥራ ሁለት ድንጋዮችን ወሰደ።'),
  ('ed0adcb6-20e4-5215-a8d7-41866c187d6a', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 3, 32, 'ድንጋዮችንም በእግዚአብሔር ስም መሠዊያ አድርጎ ሠራቸው፤ የፈረሰውንም መሠዊያ አደሰ፤ በመሠዊያውም ዙሪያ ሁለት መስፈሪያ እህል የሚይዝ ጕድጓድ ቈፈረ።'),
  ('0e2e965f-b96f-5965-a40a-72b2f36ce82a', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 4, 33, 'በሠራውም መሠዊያ ላይ እንጨቱን ደረደረ፤ ወይፈኑንም በብልት በብልቱ ቈረጠ፤ በእንጨቱም ላይ አኖረ፤'),
  ('ea2663db-6c6f-56a2-a5f4-167866bf61dc', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 5, 34, '“አራት ጋን ውኃ አምጡልኝ፤ በሚቃጠለው መሥዋዕትና በእንጨቱ ላይም አፍስሱ” አለ፤ እነርሱም እንዲሁ አደረጉ። ደግሞም፥ “ድገሙ” አለ፤ እነርሱም ደገሙ። እርሱም፥ “ሦስተኛ አድርጉ” አለ፤ ሦስተኛም አደረጉ።'),
  ('c56c4149-cfa9-5923-a3ee-4592c141d804', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 6, 35, 'ውኃውም በመሠዊያው ዙሪያ ፈሰሰ። ደግሞም ጕድጓዱን በውኃ ሞላው።'),
  ('ae2badb7-9136-56e6-af5c-de8121a8537a', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 7, 36, 'ነቢዩ ኤልያስም ወደ ሰማይ አቅንቶ ጮኸ፤ እንዲህም አለ፥ “አቤቱ፥ የአብርሃምና የይስሐቅ የእስራኤልም አምላክ ሆይ፥ ስማኝ፤ ጌታዬ ሆይ፥ ዛሬ በእሳት ስማኝ፤ አንተ በእስራኤል ላይ አምላክ እንደ ሆንህ፥ እኔም ባሪያህ እንደ ሆንሁ፤ ይህንም ሥራ ስለ አንተ እንዳደረግሁ እነዚህ ሕዝቦች ይወቁ።'),
  ('28beecde-7d50-5d3a-a947-5fd2a28bcf23', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 8, 37, 'አንተ፥ አቤቱ፥ አምላክ እንደ ሆንህ፥ ልባቸውንም ደግሞ እንደ መለስህ፤ ይህ ሕዝብ ያውቅ ዘንድ ስማኝ፤ አቤቱ፥ ስማኝ” አለ።'),
  ('f1fc1505-0539-500a-a8c9-d0208f88c635', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 9, 38, 'እሳትም ከሰማይ ከእግዚአብሔር ዘንድ ወረደች፤ የሚቃጠለውን መሥዋዕት፥ እንጨቱንም፥ ድንጋዮቹንም በላች፤ በጕድጓዱም ውስጥ ያለውን ውኃ፥ አፈሩንም ላሰች።'),
  ('ea87ceb6-5a7f-5ca1-a855-06f2e4adad9d', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 10, 39, 'ሕዝቡም ሁሉ ያን ባዩ ጊዜ በግንባራቸው ተደፍተው፥ “እግዚአብሔር በእውነት እርሱ አምላክ ነው፤ እግዚአብሔር እርሱ አምላክ ነው” አሉ።'),
  ('bed26303-8d19-5ebf-aed2-069943d09dac', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 11, 40, 'ኤልያስም ሕዝቡን፥ “የበዓልን ነቢያት ያዙ፤ ከእነርሱ አንድ ሰው እንኳን የሚያመልጥ አይኑር፤” አላቸው። ያዙአቸውም፤ ኤልያስም ወደ ቂሶን ወንዝ ወስዶ፥ በዚያ እየወጋ ጣላቸው።'),
  ('ff70dcab-d951-5a16-af0d-a09999b9b953', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 12, 41, 'ኤልያስም አክዓብን፥ “የዝናቡ ውሽንፍር እጅግ ነውና ተነሥተህ ውጣ፤ ብላም፤ ጠጣም” አለው።'),
  ('1abd5d1c-510f-5b17-aa52-f38b28f3bf50', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 13, 42, 'አክዓብም ሊበላና ሊጠጣ ወጣ። ኤልያስም ወደ ቀርሜሎስ አናት ወጣ፤ ፊቱንም በጕልበቱ መካከል አቀርቅሮ በግንባሩ ወደ ምድር ተደፋ።'),
  ('0f309cd2-fa4f-5756-ab69-111a62be6136', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 14, 43, 'ብላቴናውንም፥ “ወጥተህ ወደ ባሕሩ ተመልከት” አለው። ብላቴናውም ተመልክቶ፥ “ምንም የለም” አለ። ኤልያስም፥ “ሰባት ጊዜ ተመላለስ” አለው። ብላቴናውም ሰባት ጊዜ ተመላለሰ።'),
  ('70f873f5-1a5a-5f46-a6e5-9dd570ac589e', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 15, 44, 'በሰባተኛውም ጊዜ፥ “እነሆ፥ የሰው ጫማ የምታህል ትንሽ ደመና ከባሕር ውኃ ቋጥራ ስትወጣ አየሁ” አለ። እርሱም፥ “ወጥተህ አክዓብን፦ ዝናብ እንዳይዝህ ሰረገላህን ጭነህ ውረድ በለው” አለ።'),
  ('da51c74c-268f-5305-ac67-550755131f35', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 16, 45, 'ወዲያ ወዲህም እስኪመላለስ ድረስ ሰማዩ በደመናና በነፋስ ጨለመ፤ ትልቅም ዝናብ ዘነበ፤ አክዓብም በሰረገላ ተቀምጦ እያለቀሰ ወደ ኢይዝራኤል ሄደ።'),
  ('2cc7b2c1-98c9-5104-a557-2ec46b0e7465', '29642a53-1a94-59a2-a3e8-10df702b5c62', 'f013c1c2-48f5-599f-a994-a48afa880996', 17, 46, 'የእግዚአብሔርም እጅ በኤልያስ ላይ ነበረች፤ ወገቡንም ታጥቆ ወደ ኢይዝራኤል እስኪገባ ድረስ በአክዓብ ፊት ይሮጥ ነበር።'),
  ('3fa642a3-cb83-512f-a784-f58a2ea410d0', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 1, 1, 'አክዓብም ኤልያስ ያደረገውን፥ የሐሰት ነቢያትንም ሁሉ በሰይፍ እንደ ገደላቸው ለሚስቱ ለኤልዛቤል ነገራት።'),
  ('87d3bfe8-405c-584a-a6af-f3680e9bb6c2', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 2, 2, 'ኤልዛቤልም፥ “አንተ ኤልያስ ከሆንህ እኔም ኤልዛቤል ከሆንሁ ነገ በዚህ ጊዜ ሰውነትህን ከእነዚህ እንደ አንዱ ሰውነት ባላደርጋት፥ አማልክት እንዲህ ያድርጉብኝ፤ እንዲህም ይግደሉኝ” ብላ ወደ ኤልያስ ላከች።'),
  ('bfc6dec1-267f-5468-aff5-20e41f49e555', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 3, 3, 'ኤልያስም ፈርቶ ተነሣ፤ ነፍሱንም ሊያድን ሄደ፤ በይሁዳም ወዳለው ወደ ቤርሳቤህ መጥቶ ብላቴናውን በዚያ ተወ።'),
  ('5b4075c1-9680-54af-ad45-4fd26ec01751', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 4, 4, 'እርሱም አንድ ቀን የሚያህል መንገድ በምድረ በዳ ሄደ፤ መጥቶም ከደድሆ ዛፍ በታች ተቀመጠና፦ ይበቃኛል፤ አሁንም አቤቱ! እኔ ከአባቶቼ አልበልጥምና ነፍሴን ውሰድ” ብሎ እንዲሞት ለመነ።'),
  ('1e00cbe5-f2b0-5401-ab3e-e34fa83074b9', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 5, 5, 'በደድሆውም ዛፍ በታች ተኛ፤ እንቅልፍም አንቀላፋ፤ እነሆም፥ መልአክ ዳሰሰውና፥ “ተነሥተህ ብላ” አለው።'),
  ('1822c30f-7a67-5b37-ad76-28e9beb66be8', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 6, 6, 'ከዚህ በኋላ ኤልያስ ተነሥቶ፥ እነሆ፥ በራሱ አጠገብ የተጋገረ እንጎቻና በማሰሮ ውኃ አገኘ። በላም፤ ጠጣም፤ ተመልሶም ተኛ።'),
  ('318087ab-b7ce-536e-a321-42dbecde73ce', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 7, 7, 'የእግዚአብሔር መልአክ ደግሞ ሁለተኛ ጊዜ መጥቶ ዳሰሰውና፥ “የምትሄድበት መንገድ ሩቅ ነውና ተነሥተህ ብላ” አለው።'),
  ('1a5092cb-1e32-554e-a273-2a45079d716b', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 8, 8, 'ተነሥቶም በላ፤ ጠጣም፤ በዚያም በበላው የምግብ ኀይል እስከ ኮሬብ ድረስ አርባ ቀንና አርባ ሌሊት ሄደ።'),
  ('f235b7bc-f39a-57db-ab36-f7eab866e04c', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 9, 9, 'እዚያም ወዳለ ዋሻ ገባ፤ በዚያም አደረ፤ እነሆም፥ “ኤልያስ ሆይ! ምን አመጣህ?” የሚል የእግዚአብሔር ቃል ወደ እርሱ መጣ።'),
  ('bf206368-e8d8-50c4-a731-e012d0e33be2', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 10, 10, 'ኤልያስም፥ “ሁሉን ለሚገዛ ለእግዚአብሔር እጅግ ቀንቻለሁ፤ የእስራኤል ልጆች ቃል ኪዳንህን ትተዋልና፥ መሠዊያዎችህንም አፍርሰዋልና፥ ነቢያትህንም በሰይፍ ገድለዋልና፤ እኔም ብቻዬን ቀርቻለሁ ነፍሴንም ሊወስዱአት ይሻሉ” አለ።'),
  ('1e214ef8-1680-5bfe-a592-cd5009ff9a14', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 11, 11, 'እርሱም አለ፥ “ነገ ውጣ፤ በተራራውም ላይ በእግዚአብሔር ፊት ቁም። እነሆም፥ እግዚአብሔር በዚያ አለፈ፤ በእግዚአብሔርም ፊት ትልቅና ብርቱ ነፋስ ተራሮቹን ሰነጠቀ፤ ዓለቶቹንም ሰባበረ፤ እግዚአብሔር ግን በነፋሱ ውስጥ አልነበረም። ከነፋሱም በኋላ የምድር መናወጥ ሆነ፤ እግዚአብሔር ግን በምድር መናወጥ ውስጥ አልነበረም።'),
  ('77859f02-1941-5ecb-a988-377ebbcae257', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 12, 12, 'ከምድር መናወጥ በኋላ እሳት ሆነ፤ እግዚአብሔርም በእሳቱ ውስጥ አልነበረም። ከእሳቱም በኋላ እንደ ፉጨት ያለ ቀጭን ድምፅ ሆነ፤ በዚያም እግዚአብሔር ነበረ።'),
  ('45bf06bf-8d8e-5967-a116-b94600cd4e0d', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 13, 13, 'ኤልያስም ያን በሰማ ጊዜ ፊቱን በመጐናጸፊያው ሸፈነ፤ ወጥቶም በዋሻው ደጃፍ ቆመ። እነሆም፥ “ኤልያስ ሆይ፥ ወደዚህ ለምን መጣህ?” የሚል ቃል ወደ እርሱ መጣ።'),
  ('906de55a-e186-56a6-af9d-c6561037e3c7', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 14, 14, 'እርሱም፥ “ሁሉን ለሚገዛ ለእግዚአብሔር እጅግ ቀንቻለሁ፤ የእስራኤል ልጆች ቃል ኪዳንህን ትተዋልና፥ መሠዊያዎችህንም አፍርሰዋልና፥ ነቢያትህንም በሰይፍ ገድለዋልና፤ እኔም ብቻዬን ቀርቻለሁ፤ ነፍሴንም ሊወስዱአት ይሻሉ” አለ።'),
  ('ae76499c-8682-56be-ab0e-b6ce3690c867', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 15, 15, 'እግዚአብሔርም አለው፥ “ሂድ፤ በመጣህበትም መንገድ በምድረ በዳ ወደ ደማስቆ ተመለስ፤ ከዚያም በደረስህ ጊዜ በሶርያ ላይ ንጉሥ ይሆን ዘንድ አዛሄልን ቅባው፤'),
  ('c1d07ab4-a45f-5747-a92b-853cb9007f7b', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 16, 16, 'በእስራኤልም ላይ ንጉሥ ይሆን ዘንድ የናሚሶን ልጅ ኢዩን ቅባው፤ በፋንታህም ነቢይ ይሆን ዘንድ የአቤልመሁላን ሰው የሣፋጥን ልጅ ኤልሳዕን ቅባው፤'),
  ('24d9b078-2038-5a8b-a091-04e44336a575', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 17, 17, 'ከአዛሄልም ሰይፍ የሚያመልጠውን ሁሉ ኢዩ ይገድለዋል፤ ከኢዩም ሰይፍ የሚያመልጠውን ሁሉ ኤልሳዕ ይገድለዋል።'),
  ('22105a2b-d1de-5842-a4e1-16fcfe5ba4d5', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 18, 18, 'እኔም ከእስራኤል ጕልበታቸውን ለበዓል ያላንበረከኩትን ሁሉ፥ በአፋቸውም ያልሳሙትን ሁሉ፥ ሰባት ሺህ ሰዎች ለእኔ አስቀራለሁ።”'),
  ('f5b258be-afb2-541c-a6bd-696ff8649a55', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 19, 19, 'ከዚያም ሄደ፤ የሣፋጥንም ልጅ ኤልሳዕን በዐሥራ ሁለት ጥማድ በሬዎች ሲያርስ፥ እርሱም ከዐሥራ ሁለተኛው ጋር ሆኖ አገኘው። ኤልያስም ወደ እርሱ አልፎ መጐናጸፊያውን ጣለበት።'),
  ('03cb3ac5-0702-52b8-a3c9-dcbc42063f00', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 20, 20, 'ኤልሳዕም በሬዎቹን ተወ፤ ኤልያስንም ተከትሎ ሄደ፥ “አባቴንና እናቴን እስማቸው ዘንድ፥ እባክህ ተወኝ፤ ከዚያም በኋላ እከተልሃለሁ” አለው። እርሱም“ሂድና ተመለስ፤ ምን አድርጌልሃለሁ?” አለው።'),
  ('5c53707b-fd8c-5847-a10a-8c999a505c60', '18ceac3d-49a8-5fa2-afa4-a8985e7977e7', 'd9ae4e9d-046c-5ecb-a6c8-15fcaccdd5d9', 21, 21, 'ከእርሱም ዘንድ ተመልሶ ሁለቱን በሬዎች ወስዶ አረዳቸው፤ ሥጋቸውንም በበሬዎቹ ዕቃ ቀቀለው፤ ለሕዝቡም ሰጣቸው፤ በሉም፤ እርሱም ተነሥቶ ኤልያስን ተከትሎ ሄደ፤ ያገለግለውም ነበር።'),
  ('62762a1b-da75-58b9-a1e9-c9913c3b6d9f', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 1, 1, 'ለኢይዝራኤላዊው ለናቡቴ በሰማርያ ንጉሥ በአክዓብ ቤት አጠገብ የወይን ቦታ ነበረው።'),
  ('3359d580-f20c-512f-ac44-d8aafea983e8', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 2, 2, 'አክዓብም ናቡቴን፥ “በቤቴ አቅራቢያ ነውና የአትክልት ቦታ አደርገው ዘንድ የወይን ቦታህን ስጠኝ፤ ስለ እርሱም ከእርሱ የተሻለ የወይን ቦታ እሰጥሃለሁ፤ ወይም ብትወድድ ዋጋውን ወርቅ እሰጥሃለሁ” ብሎ ተናገረው።'),
  ('14f94862-7a38-52ee-aa7d-aad68e515af3', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 3, 3, 'ናቡቴም አክዓብን፥ “የአባቶቼን ርስት እሰጥህ ዘንድ እግዚአብሔር አያምጣብኝ” አለው።'),
  ('71ba45a8-7e59-5129-ae8d-1d3b989fbb86', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 4, 4, 'አክዓብም አዝኖ ሄደ፤ በአልጋውም ላይ ተኝቶ ፊቱን ተሸፋፈነ፤ እንጀራንም አልበላም።'),
  ('e110a47d-4b42-586f-adb2-53731284c903', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 5, 5, 'ሚስቱም ኤልዛቤል ወደ እርሱ ገብታ፥ “ምን ያሳዝንሃል? እንጀራስ የማትበላ ምን ሆነሃል?” አለችው።'),
  ('ace5204e-c638-5bcc-a08f-9ef58299eb39', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 6, 6, 'እርሱም፥ “ኢይዝራኤላዊውን ናቡቴን፦ የወይንህን ቦታ በገንዘብ ስጠኝ፤ ወይም ብትወድድ በፋንታው ሌላ የወይን ቦታ እሰጥሃለሁ ብዬ ተናገርሁት፤ እርሱ ግን የአባቶቼን ርስት አልሰጥህም ስለ አለኝ ነው” አላት።'),
  ('27f28de5-a208-5e4b-acbc-a8a4e5453322', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 7, 7, 'ሚስቱ ኤልዛቤልም፥ “አሁንም አንተ የእስራኤል ንጉሥ ሆነህ እንደዚህ ታደርጋለህን? ተነሣ፤ እንጀራንም ብላ፤ ራስህንም አጽና፤ ልብህም ደስ ይበላት፤ የኢይዝራኤላዊውንም የናቡቴን የወይን ቦታ እሰጥሃለሁ” አለችው።'),
  ('2f04efc2-c5c1-5ef3-a8d6-1ad6ba7decb4', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 8, 8, 'በአክዓብም ስም ደብዳቤ ጻፈች፤ በማኅተሙም አተመችው፤ በከተማው ወደ ነበሩትና ከናቡቴም ጋር ወደ ተቀመጡት ሽማግሌዎችና አለቆች ደብዳቤውን ላከች።'),
  ('8d92a30a-4a53-5666-a255-f813597b32d3', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 9, 9, 'የዚያች ደብዳቤም ቃል እንዲህ ይላል፥ “ጾምን ጹሙ፤ ናቡቴንም በሕዝቡ መካከል በከፍተኛ ቦታ አስቀምጡት፤'),
  ('b176f3d9-0997-5e97-add5-b9af30b597ef', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 10, 10, 'ሁለት የሐሰት ምስክሮችንም በፊቱ አስቀምጡና፦ እግዚአብሔርንና ንጉሡን ሰድቦአል ብለው ይመስክሩበት፤ አውጥታችሁም እስኪሞት ድረስ በድንጋይ መትታችሁ ግደሉት።”'),
  ('37e28109-499c-5903-a1a9-fc6a055988d0', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 11, 11, 'በከተማውም የተቀመጡት የከተማው ሰዎችና ሽማግሌዎች፥ አለቆችም ኤልዛቤል እንዳዘዘቻቸውና ወደ እነርሱ በተላከው ደብዳቤ እንደ ተጻፈው እንዲሁ አደረጉ።'),
  ('e3b72743-76c6-5664-ab7c-265eaa5531a3', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 12, 12, 'የጾም አዋጅም ነገሩ፤ ናቡቴንም በሕዝቡ ፊት በከፍተኛ ቦታ አስቀመጡት።'),
  ('d4c75491-7681-5793-a54f-444fce5d40ab', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 13, 13, 'ሁለቱም የዐመፅ ልጆች የሆኑ ሰዎች ገብተው በፊቱ ቆሙ፤ “እግዚአብሔርንና ንጉሡን ሰድበሃል” ብለው መሰከሩበት። የዚያ ጊዜም ከከተማ አውጥተው በድንጋይ ደብድበው ገደሉት።'),
  ('5ceeb09b-dc17-536b-a16e-0b711ec7778e', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 14, 14, 'ወደ ኤልዛቤልም፥ “ናቡቴ በድንጋይ ተደብድቦ ሞተ” ብለው ላኩ።'),
  ('5c397eee-1b0d-5b5c-aa5a-0e1b1cb68a02', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 15, 15, 'ኤልዛቤልም በሰማች ጊዜ አክዓብን፥ “ናቡቴ ሞቶአል እንጂ በሕይወት አይደለምና በገንዘብ ይሰጥህ ዘንድ እንቢ ያለውን የኢይዝራኤላዊውን የናቡቴን የወይን ቦታ ተነሥተህ ውረስ” አለችው።'),
  ('159e115b-26f1-562a-ac3c-b2cb3a87f35c', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 16, 16, 'አክዓብም ኢይዝራኤላዊው ናቡቴ እንደ ሞተ በሰማ ጊዜ ወደ ኢይዝራኤላዊው ወደ ናቡቴ ወይን ቦታ ሊወርሰው ተነሥቶ ወረደ።'),
  ('44f29187-4395-5561-af86-22002be7f1c8', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 17, 17, 'እግዚአብሔርም ቴስብያዊው ኤልያስን እንዲህ አለው፦'),
  ('9e4751b9-5dc7-59ed-a2f1-2ac565e082fc', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 18, 18, '“ተነሥተህ በሰማርያ የሚኖረውን የእስራኤልን ንጉሥ አክዓብን ትገናኝ ዘንድ ውረድ፤ እነሆ፥ ይወርሰው ዘንድ በወረደበት በናቡቴ የወይን ቦታ ውስጥ አለ።'),
  ('dd008577-92c1-5d85-acae-677019364cd1', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 19, 19, 'እንዲህም ብለህ ንገረው፦ እግዚአብሔር እንዲህ ይላል፦ ናቡቴን ገድለህ ወረስኸው፤ ስለዚህም ደግሞ እግዚአብሔር እንዲህ ይላል፦ ጅቦችና ውሾች የናቡቴን ደም በላሱበት ስፍራ የአንተን ደም ደግሞ ውሾች ይልሱታል፤ አመንዝራዎችም በደምህ ይታጠባሉ” ብለህ ንገረው።'),
  ('f1fa110e-92bf-5f61-a326-41d6efc0c34a', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 20, 20, 'አክዓብም ኤልያስን፥ “ጠላቴ ሆይ! አገኘኸኝን?” አለው። እርሱም እንዲህ ብሎ መለሰለት፥ “አግኝቼሃለሁ፤ ታስቈጣው ዘንድ በእግዚአብሔር ፊት ክፉ አድርገሃልና እግዚአብሔር እንዲህ ይላል፦'),
  ('87858385-be00-519a-af0c-865bf5054d52', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 21, 21, 'እነሆ፥ ክፉ ነገር አመጣብሃለሁ፤ እሳትን ከኋላህ አነድዳለሁ፤ ዐጥር ተጠግቶ እስከሚሸን ድረስ የአክዓብን ዘር አጠፋዋለሁ፤ በእስራኤል ውስጥ ያሉትንም፥ የሌሉትንም እነቅላለሁ፤'),
  ('83f5c7aa-a70c-5fdd-a25c-9e8e82a0dbd6', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 22, 22, 'በሥራህም አስቈጥተኸኛልና፥ እስራኤልንም አስተሃልና ቤትህን እንደ ናባጥ ልጅ እንደ ኢዮርብዓም ቤት እንደ አኪያም ልጅ እንደ ባኦስ ቤት አደርገዋለሁ።”'),
  ('727f3c6d-419a-5684-a49a-dc4aec3dd44f', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 23, 23, 'እግዚአብሔርም እንዲህ ብሎ ተናገረ፥ “በኢይዝራኤል ቅጥር አጠገብ ኤልዛቤልን ውሾች ይበሉአታል፥'),
  ('1d2bad2a-9f14-5941-a766-24b4648153d2', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 24, 24, 'ከአክዓብም ወገን በከተማዪቱ ውስጥ የሞተውን ውሾች ይበሉታል፤ በሜዳውም የሞተውን የሰማይ ወፎች ይበሉታል።”'),
  ('8d25f849-c1b1-574e-afa8-de1c8502478e', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 25, 25, 'ነገር ግን አክዓብ በእግዚአብሔር ፊት ክፉን ያደርግ ዘንድ ራሱን ሸጠ፤ ሚስቱ ኤልዛቤል አስታዋለችና።'),
  ('72dfd2b6-3650-5b94-a968-dd0a107f1059', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 26, 26, 'እግዚአብሔር ከእስራኤል ልጆች ፊት ያጠፋቸው አሞራውያን እንደ ሠሩት ሁሉ፥ ጣዖትን በመከተል እጅግ ርኩስ ነገርን ሠራ።'),
  ('868ad56c-c3e8-5289-ab6c-f62afa742cde', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 27, 27, 'አክዓብም ይህን ቃል በሰማ ጊዜ ከእግዚአብሔር ፊት የተነሣ ደነገጠ፤ ልብሱንም ቀደደ፤ እያለቀሰም ሄደ፤ በሰውነቱም ላይ ማቅ ለበሰ፤ ጾመም፤ ኢይዝራኤላዊው ናቡቴንም በገደለበት ቀን ደግሞ ማቅ ለብሶ ነበር።'),
  ('c6d12a44-ff1f-5c03-add3-40f9228ba82c', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 28, 28, 'የእግዚአብሔርም ቃል ስለ አክዓብ ወደ ባሪያው ወደ ኤልያስ መጣ፤ እግዚአብሔርም አለው፦'),
  ('0c4abb23-72cc-5459-a40f-631725c435fd', 'ea151171-0a38-59d9-ad43-a51808415e1b', '76e6cd36-554d-51a6-aac7-641b0313301d', 29, 29, '“አክዓብ በፊቴ እንደ ደነገጠ አየህን? በፊቴ በልጁ ዘመን በቤቱ ላይ ክፉ ነገር አመጣለሁ እንጂ በእርሱ ዘመን ክፉ ነገር አላመጣም።”'),
  ('3a4dabee-8350-54c3-a8f5-b41735081642', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 1, 1, 'የሶርያም ንጉሥ ወልደ አዴር ሠራዊቱን ሁሉ ሰበሰበ፤ ወጥቶም ሰማርያን ከበባት፤ እየጠበቃቸውም ተቀመጠ። ከእርሱም ጋር ሠላሳ ሁለት ነገሥታት ነበሩ፤ ፈረሶችና ሰረገሎችም ነበሩ፤ ወጥተውም ሰማርያን ከበቧት፥ ወጓትም።'),
  ('a8050ee6-5296-5a6b-ad8e-475d8c78d4e2', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 2, 2, 'ወደ ከተማው ወደ እስራኤልም ንጉሥ ወደ አክዓብ እንዲህ ብሎ ላከ፦'),
  ('7fd8ac55-4c73-5020-a2dc-a74d237a9332', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 3, 3, '“ወልደ አዴር እንዲህ ይላል፦ ብርህና ወርቅህ የእኔ ነው፤ ሚስቶችህና ልጆችህም የእኔ ናቸው።”'),
  ('036ad662-9800-57f0-afa7-5c1a53cdf67f', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 4, 4, 'ንጉሡ አክዓብም መልሶ፥ “ጌታዬ ሆይ! አንተ እንዳልህ፤ እኔ የአንተ ነኝ፤ ለእኔም የሆነው ሁሉ የአንተ ነው” አለ።'),
  ('ca6c71a4-fc80-5bb3-abeb-e3847cebf60b', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 5, 5, 'ደግሞም መልእክተኞች ተመልሰው መጥተው እንዲህ አሉት፥ “ወልደ አዴር እንዲህ ይላል፦ ቀድመህ ብርህንና ወርቅህን፥ ሚስቶችህንና ልጆችህንም ላክልኝ ብዬ ልኬብህ ነበር፤'),
  ('ebc55315-78fe-5f07-a00d-96f7dbe741cc', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 6, 6, 'ይህ ካልሆነ ነገ በዚህ ጊዜ አገልጋዮቼን እልክብሃለሁ፤ ቤትህንም፥ የአገልጋዮችህንም ቤቶች ይበረብራሉ፤ ለዐይናቸው ደስ ያሰኛቸውን ሁሉና በእጃቸው የዳሰሱትንም ሁሉ ይወስዳሉ።”'),
  ('4bb43dfc-8110-5f16-af56-db0a52464867', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 7, 7, 'የእስራኤልም ንጉሥ የሀገሩን አለቆች ሁሉ ጠርቶ፥ “ተመልከቱ፤ ይህም ሰው ክፉ እንዲሻ እዩ፤ ስለ ሚስቶቼ ስለ ወንዶች ልጆቼና ሴቶች ልጆቼ ላከብኝ፤ ብሬንና ወርቄን ግን አልከለከልሁትም” አላቸው።'),
  ('ba32e568-1ff0-55b1-ac21-24acd4f8054f', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 8, 8, 'አለቆችና ሕዝቡም ሁሉ፥ “እንቢ በለው፤ እሺም አትበለው” አሉት።'),
  ('b206f8a3-57a0-5e2e-a94f-75e87e064edb', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 9, 9, 'ለወልደ አዴር መልእክተኞችም፥ “ለጌታችሁ፦ ለእኔ አገልጋይህ በመጀመሪያ የላክህብኝን ሁሉ አደርጋለሁ፤ ይህን ነገር ግን አደርገው ዘንድ አይቻለኝም” በሉት አላቸው። መልክእክተኞችም ተመልሰው ይህን ነገር ነገሩት።'),
  ('e9c72bf8-6faf-5c32-a14f-66c8b570fe0d', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 10, 10, 'ዳግመኛም ወልደ አዴር እንዲህ ብሎ ወደ እርሱ ላከ፥ “ሕዝቤና ሠራዊቴ ሁሉ ሀገርህን ሰማርያን ባያጠፉት፥ የቀበሮም ማደሪያ ባያደርጉት አማልክት እንዲህ ያድርጉብኝ፤ እንዲህም ይግደሉኝ።”'),
  ('7596a69b-81f0-5e78-ad34-921913966d3d', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 11, 11, 'የእስራኤልም ንጉሥ መልሶ፥ “ይሁን፤ ይህ ጐባጣ እንደ ቀና አይመካ” ብሎ መለሰ።'),
  ('edbfe373-ab0a-5162-aa6a-30bea638686e', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 12, 12, 'ከዚህም በኋላ ይህን ነገር በሰማ ጊዜ አብረውት ካሉት ከነገሥታቱ ሁሉ ጋር በድንኳኑ ውስጥ ይጠጣ ነበር፤ አገልጋዮቹንም፥ “ከተማውን እጠሩት” አላቸው። እነርሱም በከተማዪቱ ትይዩ ተሰለፉ።'),
  ('315bd171-cf20-59d9-aa0f-a0ffb48b6a18', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 13, 13, 'እነሆም፥ አንድ ነቢይ ወደ እስራኤል ንጉሥ ወደ አክዓብ መጥቶ፥ “እግዚአብሔር እንዲህ ይላል፦ ይህን ብዙ ሕዝብ ሁሉ ታያለህን? እነሆ፥ ዛሬ በእጅህ አሳልፌ እሰጣቸዋለሁ፤ እንግዲህ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃለህ” አለው።'),
  ('367df732-ab28-593c-aa0c-113778cde237', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 14, 14, 'አክዓብም፥ “በምን አውቃለሁ?” አለ፤ እርሱም፥ “እግዚአብሔር እንዲህ ይላል፦ በአውራጃዎቹ አለቆች ጐልማሶች” አለ፤ አክዓብም፥ “ውጊያውን ማን ይጀምራል?” አለ፤ እርሱም፥ “አንተ” አለው።'),
  ('3dbd9d1b-1699-5ffe-a937-640c72615c80', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 15, 15, 'አክዓብም የአውራጃዎቹን አለቆች ጐልማሶች ቈጠረ፤ ሁለት መቶ ሠላሳ ሁለትም ሆኑ፤ ከእነርሱም በኋላ ሕዝቡን ሁሉ፥ የእራኤልን ልጆች ሁሉ ቈጠረ፤ ሰባት ሺህም ሆኑ።'),
  ('faa3e1d6-08f4-5972-aaa9-0e3c55dc10e9', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 16, 16, 'ቀትርም በሆነ ጊዜ ወጡ፤ ወልደ አዴርም በማቅ ድንኳን ውስጥ ጠጥቶ ሰክሮ ነበረ፤ የሚረዱት ሠላሳ ሁለት ነገሥታትም አብረውት ነበሩ።'),
  ('1134e47a-5073-55ee-aa1a-1e9dd8b5cf3e', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 17, 17, 'የአውራጃዎቹም አለቆች ጐልማሶች አስቀድመው መጥተው ለሶርያ ንጉሥ ለወልደ አዴር፥ “እነሆ፥ ሰዎች ከሰማርያ መጡ” ብለው ነገሩት።'),
  ('b10c2e3e-51db-5fc2-a519-16d147918c98', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 18, 18, 'እርሱም፥ “ለሰላም መጥተው እንደ ሆነ በሕይወታቸው ያዙአቸው፤ ለውጊያ መጥተው እንደ ሆነ ግን ተዋጓቸው” አለ።'),
  ('0795e3b0-108d-5525-a7d1-9086bd071bb1', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 19, 19, 'እነዚህም የአውራጃዎች አለቆች ጐልማሶች ከከተማዪቱ ወጡ፤ ሠራዊትም ተከተላቸው።'),
  ('0721a0dd-1dd1-5bd3-ae7a-86745cb1eef2', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 20, 20, 'ሁሉም እያንዳንዱ በፊቱ የነበረውን ሰው ገደለ፤ ደጋግመውም ገደሉ። ከዚህም በኋላ ሶርያውያን ሸሹ፤ እስራኤልም አሳደዱአቸው፤ የሶርያ ንጉሥ ወልደ አዴርም በፈጣን ፈረስ አመለጠ።'),
  ('7fad9e4d-5451-5c76-a204-b8f56f0d7d6f', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 21, 21, 'የእስራኤልም ንጉሥ ወጥቶ ፈረሶቹንና ሰረገሎቹን ያዘ፤ ሶርያውያንንም በታላቅ አገዳደል ገደላቸው።'),
  ('caa54375-9982-5e10-aaea-941dfa5a2e9a', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 22, 22, 'አንድ ነቢይም ወደ እስራኤል ንጉሥ መጥቶ፥ “የሶርያ ንጉሥ ወልደ አዴር በሚመጣው ዓመት ይመጣብሃልና፥ በርታ፤ የምታደርገውንም ዕወቅ” አለው።'),
  ('a47cc030-b873-58ed-abd1-9beb0df7bfc9', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 23, 23, 'የሶርያም ንጉሥ አገልጋዮች እንዲህ አሉት፥ “የእስራኤል አምላክ የተራሮች አምላክ ነው እንጂ የሸለቆ አምላክ አይደለም፤ ስለዚህ በርትተውብን ነበር፤ ነገር ግን በሜዳ ብንዋጋቸው ድል እናደርጋቸው ነበር።'),
  ('da4c24b0-5c2e-50e8-ae40-9d97f268ca55', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 24, 24, 'ይህንም የምነግርህን ነገር አድርግ፤ ወደ ቤታቸው ይመለሱ ዘንድ እኒህን ነገሥታት አሰናብታቸው፤ በፋንታቸውም አለቆችን ሹም።'),
  ('46bdc6eb-0db8-508f-ae47-9ca470a0b337', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 25, 25, 'ሌሎች ሠራዊትን እናመጣልሃለን፤ አንተም ቀድሞ በሞቱብህ ሠራዊት ምትክ ሹም፤ ፈረሱን በፈረስ ፋንታ፥ ሰረገላውን በሰረገላ ፋንታ ለውጥ፤ በሜዳውም እንዋጋቸዋለን፤ ድልም እናደርጋቸዋለን።” እርሱም ምክራቸውን ሰማ፤ እንዲሁም አደረገ።'),
  ('5785152f-f0c9-5824-ab97-1569c5b7940c', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 26, 26, 'ከዚህም በኋላ በዓመቱ ወልደ አዴር ሶርያውያንን ቈጠራቸው፤ ከእስራኤልም ጋር ይዋጋ ዘንድ ወደ አፌቅ ወጣ።'),
  ('c9b92512-2061-5bc8-ab84-f68c6b51ba43', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 27, 27, 'የእስራኤልም ልጆች ተቈጠሩ፤ ሊገጥሙአቸውም ወጡ፤ የእስራኤልም ልጆች እንደ ሁለት ትናንሽ የፍየል መንጋዎች ሆነው በፊታቸው ሰፈሩ፤ ሶርያውያን ግን ምድርን ሞልተዋት ነበር።'),
  ('e9ae4329-0a11-59a0-a4c0-209096801274', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 28, 28, 'የእግዚአብሔርም ሰው መጥቶ የእስራኤልን ንጉሥ፥ “እግዚአብሔር እንዲህ ይላል፦ ሶርያውያን፦ የእስራኤል አምላክ እግዚአብሔር የተራሮች አምላክ ነው እንጂ የሸለቆ አምላክ አይደለም ብለዋልና ይህን ታላቅ ሠራዊት ሁሉ በእጅህ አሳልፌ እሰጠዋለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃለህ” አለው።'),
  ('f2a92468-7520-570f-a901-1e746f5fa859', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 29, 29, 'እነዚህም በእነዚያ ትይዩ ሰባት ቀን ያህል ሰፈሩ፤ በሰባተኛውም ቀን ተጋጠሙ፤ የእስራኤልም ልጆች ከሶርያውያን በአንድ ቀን መቶ ሺህ እግረኛ ገደሉ።'),
  ('dca38f5b-9ae6-5de1-a945-7f9b370afde4', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 30, 30, 'የቀሩትም ወደ አፌቅ ወደ ከተማዪቱ ውስጥ ሸሹ፤ ቅጥሩም በቀሩት በሃያ ሰባት ሺህ ሰዎች ላይ ወደቀ። ወልደ አዴርም ሸሽቶ ወደ ከተማዪቱ ወደ እልፍኙ ውስጥ ገባ።'),
  ('80613787-f7aa-5555-a0f2-14f69f4b28b3', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 31, 31, 'እርሱም ለአገልጋዮቹ፥ “እነሆ፥ የእስራኤል ነገሥታት መሓሪዎች ነገሥታት እንደ ሆኑ አውቃለሁ፤ በወገባችን ማቅ እንታጠቅ፤ በራሳችንም ገመድ እንጠምጥም፤ ወደ እስራኤልም ንጉሥ እንሂድ፤ ምናልባት ሰውነታችንን ያድናት ይሆናል” አላቸው።'),
  ('a3a9c0c3-dbcb-580c-a897-88f2f8721de5', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 32, 32, 'ወገባቸውንም በማቅ ታጠቁ፤ በራሳቸውም ገመድ ጠመጠሙ፤ ወደ እስራኤልም ንጉሥ ገብተው፥ “ባሪያህ ወልደ አዴር፦ ሰውነታችንን አድነን አለህ” አሉት። እርሱም፥ “ገና በሕይወት አለን? ወንድሜ ነው” አለ።'),
  ('ab1cab93-e6b0-51bd-af27-e1b258428b5a', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 33, 33, 'ሰዎቹም የደግ ምልክት አደረጉትና ቃሉን ከአፉ ተቀብለው፥ “ወንድምህ ወልደ አዴር አለ” አሉት። እርሱም፥ “ሂዱና አምጡት” አለ። ወልደ አዴርም ወደ እርሱ መጣ፤ በሰረገላውም ላይ አስቀመጠው።'),
  ('78b48e74-81a3-5ac3-ac40-6cf09f2723d9', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 34, 34, 'ወልደ አዴርም፥ “አባቴ ከአባትህ የወሰዳቸውን ከተሞች እመልስልሃለሁ፤ አባቴ በሰማርያ እንዳደረገ አንተም በደማስቆ መንገድ ታደርጋለህ” አለው። አክዓብም፥ “እኔም በዚህ ቃል ኪዳን እሰድድሃለሁ” አለ። ከእርሱም ጋር ቃል ኪዳን አድርጎ ሰደደው።'),
  ('82b2be53-1c38-5833-ad59-bba980647e5b', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 35, 35, 'ከነቢያትም ልጆች አንድ ሰው መጥቶ በእግዚአብሔር ቃል ባልንጀራውን፥ “ግደለኝ” አለው። ሰውዬውም ይገድለው ዘንድ እንቢ አለ።'),
  ('869d16c5-73e4-5986-a7cb-3d6768ad6031', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 36, 36, 'እርሱም፥ “የእግዚአብሔርን ቃል መስማት እንቢ ብለሃልና እነሆ፥ ከእኔ ተለይተህ በሄድህ ጊዜ አንበሳ ይገድልሃል” አለው። ከእርሱም ተለይቶ በሄደ ጊዜ አንበሳ አግኝቶ ገደለው።'),
  ('0621c55c-f854-5959-a3db-8862f5286f7a', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 37, 37, 'ደግሞም ሌላ ሰው አግኝቶ፥ “ግደለኝ” አለው። ሰውዬውም መታው በመምታቱም አቈሰለው።'),
  ('1ff4a6df-c6c4-5fcc-ad07-5632bc23d0e6', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 38, 38, 'ነቢዩም ሄዶ በመንገድ አጠገብ ንጉሡን ጠበቀው፤ ዐይኖቹንም በቀጸላው ሸፈነ።'),
  ('2297ec63-a6df-5cad-a0b7-8b04abffd9d0', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 39, 39, 'ንጉሡም ባለፈ ጊዜ ወደ እርሱ ጮኸ፥ “ባሪያህ ወደ ሰልፍ መካከል ወጣ፤ እነሆም፥ አንድ ሰው ፈቀቅ ብሎ ወደ እኔ መጣ፤ አንድ ሰውም አመጣና፦ ይህን ሰው ጠብቅ፤ ቢኰበልልም ነፍስህ በነፍሱ ፋንታ ትሆናለች፤ ወይም አንድ መክሊት ብር ትከፍላለህ አለኝ።'),
  ('2813008a-7f41-55c5-ac17-2a6a59d569e9', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 40, 40, 'ከዚህም በኋላ አገልጋይህ ወዲህና ወዲያ ሲመለከት ጠፋ” አለው። የእስራኤልም ንጉሥ፥ “ፍርድህ እንዲሁ ይሆናል፤ አንተ ፈርደኸዋል” አለው።'),
  ('38a09316-1b29-5683-aa49-e46749eae825', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 41, 41, 'ፈጥኖም ቀጸላውን ከዐይኑ አነሣ፤ የእስራኤልም ንጉሥ ከነቢያት ወገን እንደ ሆነ ዐወቀው።'),
  ('401013c2-c3b6-58e3-ae58-b0aa5f8785a4', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 42, 42, 'ያም ነቢይ፥ “እግዚአብሔር እንዲህ ይላል፦ እኔ እርም ያልሁትን፥ ሞትም የሚገባውን ሰው ከእጅህ አውጥተሃልና፥ ነፍስህ በነፍሱ ፋንታ፥ ሕዝብህም በሕዝቡ ፋንታ ይሆናሉ” አለው።'),
  ('df0b18c7-197d-5608-ad17-af46d659a073', '6a1e794d-c4b7-5363-aeb8-a5edcb815965', 'c12f9e18-16b0-5e7d-a09d-1d1b0283a31a', 43, 43, 'የእስራኤልም ንጉሥ አዝኖና ተክዞ ወደ ሰማርያ ሄደ።'),
  ('2be5e003-5785-5c6f-a534-ed3fea997a77', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 1, 1, 'በሰማርያም ሦስት ዓመት ተቀመጠ፤ በሶርያና በእስራኤልም መካከል ጦርነት አልነበረም።'),
  ('d4e40112-500e-53e9-ae4c-a4642a515945', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 2, 2, 'ከዚህም በኋላ በሦስተኛው ዓመት የይሁዳ ንጉሥ ኢዮሣፍጥ ወደ እስራኤል ንጉሥ ወረደ።'),
  ('209e1cb8-4bdd-57e6-a788-9b065351a09c', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 3, 3, 'የእስራኤልም ንጉሥ አገልጋዮቹን፥ “ሬማት ዘገለዓድ የእኛ እንደ ሆነች፥ እኛም ከሶርያ ንጉሥ እጅ ሳንወስዳት ዝም እንዳልን ታውቃላችሁን?” አላቸው።'),
  ('65096595-00b8-53a1-ac44-9e201bbe2c2e', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 4, 4, 'የእስራኤል ንጉሥም ኢዮሣፍጥን፥ “በሬማት ዘገለዓድ እንዋጋ ዘንድ ከእኔ ጋር ትዘምታለህን?” አለው። ኢዮሣፍጥም ለእስራእል ንጉሥ፥ “እኔ እንደ አንተ፥ ሕዝቤም እንደ ሕዝብህ፥ ፈረሶቼም እንደ ፈረሶችህ ናቸው” አለው።'),
  ('afe5b1d8-eed5-528b-a156-15f73b63086f', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 5, 5, 'የይሁዳ ንጉሥ ኢዮሣፍጥም የእስራኤልን ንጉሥ፥ “ወደ እግዚአብሔር ዛሬ ጠይቁልን” አለው።'),
  ('812b17ec-ac92-5a10-ac33-7a96caf4e057', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 6, 6, 'የእስራኤልም ንጉሥ ነቢያቱን አራት መቶ የሚያህሉትን ሰዎች ሰበሰበ፤ የእስራኤል ንጉሥም፥ “ወደ ሬማት ዘገለዓድ ለሰልፍ ልሂድን? ወይስ ልቅር?” አላቸው። እነርሱም፥ “እግዚአብሔር በንጉሥ እጅ አሳልፎ ይሰጣታልና ውጣ” አሉት።'),
  ('1bbe5ef8-a538-55f3-ae2f-6e4de116a22f', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 7, 7, 'ኢዮሳፍጥም፥ “የእስራኤልን ንጉሥ የእግዚአብሔርን ቃል እንጠይቀው ዘንድ የእግዚአብሔር ነቢይ በዚህ አይገኝምን?” አለው።'),
  ('6f813a8b-f0c3-5f4f-aea9-173107588d1f', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 8, 8, 'የእስራኤልም ንጉሥ ኢዮሣፍጥን፥ “እግዚአብሔርን የምንጠይቅበት የይምላ ልጅ ሚክያስ የሚባል አንድ ሰው አለ፤ ነገር ግን ክፉ እንጂ መልካም አይናገርልኝምና እጠላዋለሁ” አለው። የይሁዳ ንጉሥ ኢዮሣፍጥም፥ “ንጉሥ እንዲህ አይበል” አለ።'),
  ('28d5b561-ad43-5169-a7ba-e0e553803eea', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 9, 9, 'የእስራኤልም ንጉሥ አንዱን ጃንደረባ ጠርቶ፥ “የይምላን ልጅ ሚክያስን ፈጥነህ ጥራው” አለው።'),
  ('740e414f-e763-56aa-aa65-d3456bb775ed', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 10, 10, 'የእስራኤል ንጉሥ አክዓብና የይሁዳ ንጉሥ ኢዮሣፍጥም ከጦር መሣሪያቸው ጋር በሰማርያ በር መግቢያ አጠገብ በአደባባይ በዙፋኖቻቸው ላይ ተቀምጠው ነበር፤ ነቢያቱም ሁሉ በፊታቸው ትንቢት ተናገሩ።'),
  ('1bc01522-0a07-5d98-a5cd-e621dacddff4', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 11, 11, 'የከሓና ልጅ ሴዴቅያስም የብረት ቀንዶች ሠርቶ፥ “እግዚአብሔር እንዲህ ይላል፦ እስኪጠፉ ድረስ በእነዚህ ቀንዶች ሶርያውያንን ትወጋቸዋለህ” አለ።'),
  ('b14afb32-7dd1-501a-a881-be9f61babefe', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 12, 12, 'ነቢያትም ሁሉ እንዲህ ብለው ትንቢት ተናገሩ፥ “ወደ ሬማት ዘገለዓድ ዝመት፤ እግዚአብሔርም ይረዳሃል። ሶርያውያንንና ንጉሣቸውንም በእጅህ አሳልፎ ይሰጣቸዋል።”'),
  ('b3a27861-c60a-5b07-a675-65479710d73c', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 13, 13, 'ሚክያስንም ሊጠራ የሄደ መልእክተኛ፥ “እነሆ፥ ነቢያት ሁሉ በአንድ አፍ ሆነው ለንጉሡ መልካምን ይናገራሉ፤ ቃልህም እንደ ቃላቸው እንዲሆን መልካም እንድትናገር እለምንሃለሁ” አለው።'),
  ('399517be-87fa-5f6d-a5a6-ece99ca9ea14', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 14, 14, 'ሚክያስም፥ “ሕያው እግዚአብሔርን! እግዚአብሔር የሚነግረኝን እርሱን እናገራለሁ” አለ።'),
  ('407a13eb-9efd-58df-a6fe-f9db2c55323e', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 15, 15, 'ወደ ንጉሡም ደረሰ። ንጉሡም፥ “ሚክያስ ሆይ! ወደ ሬማት ዘገለዓድ ለሰልፍ እንሂድን? ወይስ እንቅር?” አለው። እርሱም፥ “ውጣና ተከናወን፤ እግዚአብሔርም በንጉሡ እጅ አሳልፎ ይሰጣታል” ብሎ መለሰለት።'),
  ('518de096-55f1-5aa8-afca-4f567fb7413f', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 16, 16, 'ንጉሡም፥ “በእግዚአብሔር ስም እውነት ትነግረኝ ዘንድ ስንት ጊዜ አምልሃለሁ?” አለው።'),
  ('67400c4a-01cb-5a03-a8cc-c2d2ba8ac50b', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 17, 17, 'እርሱም አለ፥ “እንዲህ አይደለም፤ እስራኤል ሁሉ ጠባቂ እንደሌላቸው በጎች በተራሮች ላይ ተበትነው አየሁ፤ እግዚአብሔርም አለ፦ እግዚአብሔር የእነዚህ አምላክ አይደለምን? እያንዳንዱ በሰላም ወደ ቤቱ ይመለስ።”'),
  ('82afc7b6-b056-5f80-a3ff-3fb2ffd00667', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 18, 18, 'የእስራኤልም ንጉሥ የይሁዳ ንጉሥ ኢዮሳፍጥን፥ “ክፉ እንጂ መልካም እንደማይናገርልኝ አላልሁምን?” አለው።'),
  ('fd596777-0553-5132-a7c3-41d1eceba192', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 19, 19, 'ሚክያስም አለ፥ “እንዲህ አይደለም፤ የእግዚአብሔርን ቃል የሰማሁት እኔ አይደለሁምን? እንዲህ አይደለም፤ እግዚአብሔር በዙፋኑ ተቀምጦ፥ የሰማይም ሠራዊት ሁሉ በቀኙና በግራው ቆመው አየሁ።'),
  ('9f4260b5-b2a0-5ee1-a61e-4c9bc2fbf0f5', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 20, 20, 'እግዚአብሔርም፦ ወጥቶ በሬማት ዘገለዓድ ይወድቅ ዘንድ አክዓብን የሚያሳስት ማን ነው? አለ። አንዱም እንዲህ ያለ ነገር፥ ሌላውም እንዲያ ያለ ነገር ተናገረ።'),
  ('eb8a1909-e94a-583e-a5c9-a3eecb95cf82', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 21, 21, 'መንፈስም ወጣ፤ በእግዚአብሔርም ፊት ቆሞ፦ እኔ አስተዋለሁ አለ።'),
  ('7fbbd353-3447-5de0-a581-427c5f789814', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 22, 22, 'እግዚአብሔርም፦ በምን ታስተዋለህ? አለው፤ እርሱም ወጥቼ በነቢያቱ ሁሉ አፍ ሐሰተኛ መንፈስ እሆናለሁ አለ። እግዚአብሔርም፦ ማሳሳትስ ታሳስተዋለህ፤ ይሆንልሃልም፤ ውጣ፤ እንዲሁም አድርግ አለ።'),
  ('2770c268-c9f5-5ca1-ac7e-5df6f31b2b50', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 23, 23, 'አሁንም፥ እነሆ፥ እግዚአብሔር በእነዚህ በነቢያትህ ሁሉ አፍ ሐሰተኛ መንፈስ አድርጎአል፤ እግዚአብሔርም በላይህ ክፉ ተናግሮብሃል።”'),
  ('a25066d8-835d-5c82-ae86-2f5133c568cb', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 24, 24, 'የከሓናም ልጅ ሴዴቅያስ ቀረበ፤ ሚክያስንም ጕንጩን በጥፊ መታውና፥ “ምን ዓይነት የእግዚአብሔር መንፈስ ነው የተናገረህ?” አለው።'),
  ('21fb1a47-4a3c-5048-a35f-fc41433ccb60', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 25, 25, 'ሚክያስም፥ “እነሆ፥ በዚያ ቀን ልትሸሸግ ወደ ውስጠኛው እልፍኝህ በሄድህ ጊዜ ታያለህ” አለ።'),
  ('07dcd3ba-4777-575c-a311-3afa6a088af0', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 26, 26, 'የእስራኤልም ንጉሥ፥ “ሚክያስን ውሰዱ፤ ወደ ከተማዪቱም ሹም ወደ አሞን ወደ ንጉሡም ልጅ ወደ ኢዮአስ መልሳችሁ፦'),
  ('2126d9a5-52c6-523b-a25d-a9171fb2c70e', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 27, 27, 'ንጉሡ እንዲህ ይላል፦ በደኅና እስክመለስ ድረስ ይህን ሰው በግዞት አኑሩት፤ የመከራም እንጀራ መግቡት፤ የመከራም ውኃ አጠጡት በሉአቸው” አለ።'),
  ('4e9604e0-5b0d-5537-ace1-d95bbfd89eb2', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '13bf312c-8dbb-5e01-a7fd-3f09c2b26c65', 28, 28, 'ሚክያስም፥ “በሰላም ብትመለስ እግዚአብሔር በእኔ የተናገረ አይደለም” አለ። ደግሞም አሕዛብ ሁሉ ሆይ! ስሙኝ” አለ።'),
  ('ef3095cc-b8fa-5a2d-abe0-cbd3f484ef20', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 1, 29, 'የእስራኤልም ንጉሥና የይሁዳ ንጉሥ ኢዮሣፍጥ ወደ ሬማት ዘገለዓድ ዘመቱ።'),
  ('8c003a28-5467-5094-a9b7-45ebf2d7e7b3', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 2, 30, 'የእስራኤልም ንጉሥ የይሁዳን ንጉሥ ኢዮሣፍጥን፥ “ልብሴን ለውጬ ወደ ሰልፍ እገባለሁ፤ አንተ ግን የእኔን ልብስ ልበስ” አለው። የእስራኤልም ንጉሥ ልብሱን ለውጦ ወደ ሰልፍ ገባ።'),
  ('c740bed1-a911-513e-ab36-38a63494dcbd', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 3, 31, 'የሶርያም ንጉሥ ሠላሳ ሁለቱን የሰረገሎች አለቆች፥ “ከእስራኤል ንጉሥ በቀር፥ ታናሽ ቢሆን ወይም ታላቅ ከማናቸውም ጋር አትዋጉ” ብሎ አዝዞ ነበር።'),
  ('a39e1f45-9588-5b71-ad55-5d6d9c715332', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 4, 32, 'የሰረገሎች አለቆችም የይሁዳ ንጉሥ ኢዮሣፍጥን ባዩ ጊዜ፥ “በእውነት የእስራኤልን ንጉሥ ይመስላል፤” አሉ ይዋጉትም ዘንድ ከበቡት፤ ኢዮሣፍጥም ጮኸ።'),
  ('7fb74da1-365b-582f-abc3-19a1fa23cd63', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 5, 33, 'የሰረገሎች አለቆችም የእስራኤል ንጉሥ እንዳልሆነ ባዩ ጊዜ እርሱን ከማሳደድ ተመለሱ።'),
  ('03ff282e-3778-51f4-a5a8-2c4f80ad198b', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 6, 34, 'አንድ ሰውም ቀስቱን ድንገት ገትሮ የእስራኤልን ንጉሥ በሳንባውና በደረቱ መካከል ወጋው፤ ሰረገለኛውንም፥ “መልሰህ ንዳ፤ ተወግቻለሁና ከሰልፍ ውስጥ አውጣኝ” አለው።'),
  ('8eedf301-01b6-5eae-a405-ee6a0691a8b5', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 7, 35, 'በዚያም ቀን ሰልፍ በረታ፤ ንጉሡም ከጥዋት እስከ ማታ በሶርያውያን ፊት በሰረገላው ላይ ተደግፎ ነበር፤ የቍስሉም ደም በሰረገላው ውስጥ ፈሰሰ፤ ማታም ሞተ።'),
  ('8b04692f-4ac3-593b-a424-6b296ddebd1e', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 8, 36, 'ፀሐይም በገባች ጊዜ አዋጅ ነጋሪው ወጥቶ፥ “ንጉሡ ሞቶአልና እያንዳንዱ ወደ ከተማው፥ እያንዳንዱም ወደ ሀገሩ ይሂድ” ብሎ አዋጅ ነገረ።'),
  ('c9c7e438-6fb2-5d65-ae6d-8be62a9ace30', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 9, 37, 'ወደ ሰማርያም መጡ፤ ንጉሡንም በሰማርያ ቀበሩት፤'),
  ('f8adc95c-c518-5788-a6c6-705c4d848dbb', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 10, 38, 'ሰረገላውንም በሰማርያ ምንጭ አጠቡት። እግዚአብሔርም በነቢዩ አድሮ እንደ ተናገረ ውሾችና ጅቦች ደሙን ላሱት። አመንዝሮች ሴቶችም በደሙ ታጠቡበት።'),
  ('322d270a-35ee-5de8-ab3c-13b9339e3c24', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 11, 39, 'የቀረውም የአክዓብ ነገር፥ ያደረገውም ነገር ሁሉ፥ ከዝሆን ጥርስም የሠራው ቤት፥ የሠራቸውም ከተሞች ሁሉ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ ተጽፎአል።'),
  ('c4d23c8e-fac8-5c45-a220-f09ca981dd1d', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9aedb82e-18ad-5c72-a55e-e59757cf7015', 12, 40, 'አክዓብም ከአባቶቹ ጋር አንቀላፋ፤ በእርሱም ፋንታ ልጁ አካዝያስ ነገሠ።'),
  ('039c2cbf-1211-5f7c-a2b2-392887087c49', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 1, 41, 'የእስራኤል ንጉሥ አክዓብም በነገሠ በአራተኛው ዓመት የአሳ ልጅ ኢዮሣፍጥ በይሁዳ ላይ ነገሠ።'),
  ('cae81a43-4397-549a-a63c-51da981a2bbd', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 2, 42, 'ኢዮሣፍጥም መንገሥ በጀመረ ጊዜ የሠላሳ አምስት ዓመት ጎበዝ ነበረ፤ በኢየሩሳሌምም ሃያ አምስት ዓመት ነገሠ። እናቱም ዓዙባ የተባለች የሴሜይ ልጅ ነበረች።'),
  ('7a0f8615-2bc8-59d0-adf1-d37a3368c192', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 3, 43, 'በአባቱም በአሳ መንገድ ሁሉ ሄደ፤ ከእርሱም ፈቀቅ አላለም፤ በእግዚአብሔርም ፊት ቅን አደረገ፤ ነገር ግን በኮረብቶቹ ላይ ያሉትን መስገጃዎችን አላራቀም፤ ሕዝቡም ገና በኮረብቶቹ ላይ ባሉት መስገጃዎች ይሠዋና ያጥን ነበር።'),
  ('077f2008-0ee9-529a-a1c9-dba3fa3db087', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 4, 44, 'ኢዮሣፍጥም ከእስራኤል ንጉሥ ጋር ታረቀ።'),
  ('90e40028-fc44-5d09-a41e-28c5bdd58b71', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 5, 45, 'የቀረውም የኢዮሣፍጥ ነገር፥ ኀይሉም፥ የሠራውም ሥራ ሁሉ፥ እነሆ፥ በይሁዳ ነገሥታት የታሪክ መጽሐፍ ተጽፎአል።'),
  ('d9021561-8c0b-54d7-ab79-328ae7fec31c', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 6, 46, 'ከአባቱም ከአሳ ዘመን የቀረውን ርኩስ ሥራ ከምድር አጠፋ።'),
  ('3889a0e1-a578-519c-ab07-861df7d94358', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 7, 47, 'በኤዶምያስም ንጉሥ አልነበረም፤ ሹሙም እንደ ንጉሥ ነበረ።'),
  ('bc3dbd1e-4283-55bb-abfd-fe4e4847a10a', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 8, 48, 'ኢዮሣፍጥም ወደ ኦፌር ሄደው ወርቅ ያመጡ ዘንድ በተርሴስ መርከብን ሠራ፤ ነገር ግን መርከቢቱ በጋሴዎንጋቤር ተሰብራለችና አልሄደችም።'),
  ('97b90f90-8d45-5665-ad07-d3cc7109b616', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 9, 49, 'የአክዓብም ልጅ አካዝያስ ኢዮሣፍጥን፥ “አገልጋዮችህ ከአገልጋዮቼ ጋር በመርከብ ይሂዱ” አለው፤ ኢዮሣፍጥ ግን አልወደደም።'),
  ('edca190d-b00e-5db8-a401-27fa7066a9f4', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 10, 50, 'ኢዮሣፍጥም ከአባቶቹ ጋር አንቀላፋ፤ በአባቱም በዳዊት ከተማ ከአባቶቹ ጋር ተቀበረ፤ በእርሱም ፋንታ ልጁ ኢዮራም ነገሠ።'),
  ('04ca0cb5-a202-5736-a4cb-9c3f296a5e41', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 11, 51, 'በይሁዳም ንጉሥ በኢዮሣፍጥ በዐሥራ ሰባተኛው ዓመተ መንግሥት የአክዓብ ልጅ አካዝያስ በእስራኤል ላይ በሰማርያ መንገሥ ጀመረ፤ በእስራኤልም ላይ ሁለት ዓመት ነገሠ።'),
  ('564356cf-c878-5db9-a774-4bc6b0cf918c', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 12, 52, 'በእግዚአብሔርም ፊት ክፉ አደረገ፤ በአባቱ በአክዓብ፥ በእናቱም በኤልዛቤል መንገድ፥ እስራኤልንም ባሳተው በናባጥ ልጅ በኢዮርብዓም መንገድ ሄደ።'),
  ('08af648e-1e82-57e8-a957-9b854388ebcf', 'cd2d8f09-8772-5141-a4b8-e0e6edeb6fbd', '9efde05c-f2c6-5031-ae56-43c9e12c00f1', 13, 53, 'በዓሊምንም አመለከ፤ ሰገደላቸውም፤ ከእርሱም አስቀድሞ አባቶቹ እንዳደረጉት ሁሉ የእስራኤል አምላክ እግዚአብሔርን አስቈጣው።'),
  ('4b53fb69-686e-565d-a7c3-ab09d301ed74', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 1, 1, 'አክዓብም ከሞተ በኋላ ሞዓብ በእስራኤል ላይ ዐመፀ።'),
  ('c6e9382e-05c8-5b9c-a0cf-61cf3f695fd2', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 2, 2, 'አካዝያስም በሰማርያ በሰገነቱ ላይ ሳለ በዐይነ ርግቡ ወድቆ ታመመ፤ እርሱም፥ “ሂዱ፥ ከዚህ ደዌ እድን እንደ ሆነ የአቃሮንን አምላክ ብዔልዜቡልን ጠይቁ” ብሎ መልእክተኞችን ላከ፤ እነርሱም ሊጠይቁለት ሄዱ።'),
  ('c4b2469d-246f-5daa-a230-67fa05f9c792', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 3, 3, 'የእግዚአብሔርም መልአክ ቴስብያዊውን ኤልያስን ጠርቶ፥ “ተነሣ፤ የሰማርያን ንጉሥ መልእክተኞች ለመገናኘት ሂድና፦ የአቃሮንን አምላክ ብዔልዜቡልን ትጠይቁ ዘንድ የምትሄዱት በእስራኤል ዘንድ አምላክ ስለሌለ ነውን?'),
  ('8406b2ef-c2c6-5379-a006-4e2bf1173d0b', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 4, 4, 'ነገሩ እንዲህ አይደለም፤ እግዚአብሔር እንዲህ ይላል፦ ትሞታለህ እንጂ ከወጣህበት አልጋ አትወርድም በላቸው” አለው። ኤልያስም ሄደ፤ እንዲሁም ነገራቸው።'),
  ('352031d3-4cd1-536c-a6cc-16d3412e8914', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 5, 5, 'መልእክተኞቹም ወደ አካዝያስ ተመለሱ፤ እርሱም፥ “ለምን ተመለሳችሁ?” አላቸው።'),
  ('b3f66d8d-cb09-510d-a1a4-da457abdf3da', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 6, 6, 'እነርሱም፥ “አንድ ሰው ሊገናኘን መጣና፦ ሂዱ፤ ወደ ላካችሁ ንጉሥ ተመልሳችሁ፦ እግዚአብሔር እንዲህ ይላል፦ የአቃሮንን አምላክ ብዔልዜቡልን ትጠይቅ ዘንድ የላክህ በእስራኤል ዘንድ አምላክ ስለሌለ ነውን? ስለዚህ ትሞታለህ እንጂ ከወጣህበት አልጋ አትወርድም በሉት አለን” አሉት።'),
  ('3ada5a8b-2815-5065-af5c-cda75b6e719f', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 7, 7, 'እርሱም፥ “ሊገናኛችሁ የወጣው፦ ይህንስ ቃል የነገራችሁ ሰው መልኩ ምን ይመስላል?” አላቸው።'),
  ('f4f1a7b6-9860-546c-aaf1-e945295cbebb', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 8, 8, 'እነርሱም፥ “ሰውዬው ጠጕራም ነው፤ በወገቡም ጠፍር ታጥቆ ነበር” አሉት። እርሱም፥ “ቴስብያዊው ኤልያስ ነው” አላቸው።'),
  ('d8dc9840-c553-5c83-a6e2-1aa3b510a6fb', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 9, 9, 'ንጉሡም ይጠሩት ዘንድ የአምሳ አለቃውን ከአምሳ ሰዎች ጋር ወደ እርሱ ላከ፤ ወደ እርሱም ሄዱ፤ እነሆም፥ በተራራ ራስ ላይ ተቀምጦ አገኙት። የአምሳ አለቃውም፥ “የእግዚአብሔር ሰው ሆይ! ንጉሡ ይጠራሃል ፈጥነህ ና፤ ውረድ” አለው።'),
  ('808b0439-ed5f-5623-a077-99bedf23a643', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 10, 10, 'ኤልያስም መልሶ የአምሳ አለቃውን፥ “እኔስ የእግዚአብሔር ሰው እንደ ሆንሁ እሳት ከሰማይ ትውረድ፤ አንተንም፥ አምሳውንም ሰዎችህን ትብላ” አለው። እሳትም ከሰማይ ወርዳ እርሱንና አምሳውን ሰዎች በላች።'),
  ('4b992c9e-e4d1-5c2b-a0bb-90c66c5d2014', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 11, 11, 'ደግሞም ሌላ የአምሳ አለቃ ከአምሳ ሰዎች ጋር ላከበት፤ የአምሳ አለቃውም፥ “የእግዚአብሔር ሰው ሆይ! ንጉሡ፦ ና፤ ፈጥነህ ውረድ ይላል” ብሎ ተናገረ።'),
  ('279c3651-1f78-573e-a322-839e389ed1a6', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 12, 12, 'ኤልያስም፥ “እኔስ የእግዚአብሔር ሰው እንደ ሆንሁ እሳት ከሰማይ ትውረድ፤ አንተንም፥ አምሳውንም ሰዎችህን ትብላ” አለው። እሳትም ከሰማይ ወርዳ እርሱንና አምሳውን ሰዎች በላች።'),
  ('b7c94c4b-9aa3-5253-a855-7baffaafb342', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 13, 13, 'ንጉሡም ደግሞ ሦስተኛ የአምሳ አለቃ ከአምሳ ሰዎች ጋር ላከ፤ ሦስተኛውም የአምሳ አለቃ ወጥቶ በኤልያስ ፊት በጕልበቱ ተንበረከከና ለመነው እንዲህም አለው፥ “የእግዚአብሔር ሰው ሆይ! ሰውነቴና የእነዚህ የአምሳው ባሪያዎችህ ሰውነት በፊትህ የከበረች ትሁን።'),
  ('2f35b679-9592-59f7-a6ab-d93e8619ecf2', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 14, 14, 'እነሆ፥ እሳት ከሰማይ ወርዳ የፊተኞቹን ሁለቱን የአምሳ አለቆችና አምሳ አምሳውን ሰዎቻቸውን በላች፤ አሁን ግን ነፍሴ በፊትህ የከበረች ትሁን።”'),
  ('a4a3747f-5c9f-594d-ad67-a5a7eb902739', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 15, 15, 'የእግዚአብሔርም መልአክ ኤልያስን፥ “ከእርሱ ጋር ውረድ፤ ከፊታቸውም የተነሣ አትፍራ” ብሎ ነገረው። ኤልያስም ተነሥቶ ከእርሱ ጋር ወደ ንጉሡ ወረደ።'),
  ('92deeead-f81b-53b0-abe6-c32a406ebd8b', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 16, 16, 'ኤልያስም፥ “እግዚአብሔር እንዲህ ይላል፦ የአቃሮንን አምላክ ብዔልዜቡልን ትጠይቅ ዘንድ መልእክተኞችን ለምን ላክህ? በእስራኤል ዘንድ አምላክ ስለሌለ ነውን? እንደዚህ አይደለም፤ ትሞታለህ እንጂ ከወጣህበት አልጋ አትወርድም” አለው።'),
  ('40fe211b-3a9f-5f0d-a58b-e19f31a2a83d', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 17, 17, 'ኤልያስም እንደ ተናገረው እንደ እግዚአብሔር ቃል ሞተ።'),
  ('b3664b11-f5dc-51fb-a4c5-349e66d88c53', '8864019d-5e00-54a7-a2c2-734552b3303a', 'da51eca9-8e15-5602-ac5c-644b9c1e47ac', 18, 18, 'አካዝያስ ያደረገው የቀረውም ነገር እነሆ፦ በእስራኤል ነገሥታት የታሪክ መጽሐፍ ተጽፎአል። በእርሱም ፋንታ የአክዓብ ልጅ ወንድሙ ኢዮራም ነገሠ።'),
  ('dee38b8b-680d-569e-a784-0bfb667ac5d7', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 1, 1, 'ከዚህም በኋላ እግዚአብሔር ኤልያስን በዐውሎ ነፋስ ወደ ሰማይ በሚያወጣው ጊዜ ኤልያስና ኤልሳዕ ከጌልጌላ ተነሥተው ሄዱ።'),
  ('3e40ad2d-1c49-5a89-a3c5-5721742e11d9', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 2, 2, 'ኤልያስም ኤልሳዕን፥ “እግዚአብሔር ወደ ቤቴል ልኮኛልና በዚሁ ቈይ” አለው። ኤልሳዕም፥ “ሕያው እግዚአብሔርን! ሕያው ነፍስህንም አልለይህም” አለው። ወደ ቤቴልም ደረሱ።'),
  ('52aa8095-4c37-51a0-a510-83602f92b74d', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 3, 3, 'በቤቴልም የነበሩ የነቢያት ልጆች ወደ ኤልሳዕ መጥተው፥ “እግዚአብሔር ጌታህን ከአንተ ለይቶ ዛሬ እንደሚወስደው ዐውቀሃልን?” አሉት። እርሱም፥ “አዎን፥ ዐውቄአለሁ፤ ዝም በሉ” አላቸው።'),
  ('6308d031-6365-57bd-abac-d6d9068c7458', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 4, 4, 'ኤልያስም ኤልሳዕን፥ “እግዚአብሔር ወደ ኢያሪኮ ልኮኛልና፥ በዚህ ቈይ” አለው። ኤልሳዕም፥ “ሕያው እግዚአብሔርን! ሕያው ነፍስህንም አልለይህም” አለው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('39025123-f940-5543-a92e-3f55e815c21d', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 5, 5, 'ወደ ኢያሪኮም ደረሱ፤ በኢያሪኮም የነበሩ የነቢያት ልጆች ወደ ኤልሳዕ ቀርበው፥ “እግዚአብሔር ጌታህን ከራስህ ላይ ዛሬ እንዲወስደው ዐውቀሃልን?” አሉት። እርሱም፥ “አዎን፥ ዐውቄአለሁ፤ ዝም በሉ” አላቸው።'),
  ('77d94056-b4f8-516f-ad66-35ccb282689f', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 6, 6, 'ኤልያስም ኤልሳዕን፥ “እግዚአብሔር ወደ ዮርዳኖስ ልኮኛልና እባክህ፥ በዚህ ቈይ” አለው። ኤልሳዕም፥ “ሕያው እግዚአብሔርን! ሕያው ነፍስህንም አልለይህም” አለው፤ ሁለቱም ሄዱ።'),
  ('9a226b11-be26-5ccf-a1ef-3981963a65c9', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 7, 7, 'ከነቢያትም ልጆች አምሳ ሰዎች ሄዱ፤ በፊታቸውም ርቀው ቆሙ፤ እነዚህም ሁለቱ በዮርዳኖስ ዳር ቆመው ነበር።'),
  ('7e583b77-c8b0-544c-a1cf-8c2f079e8b06', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 8, 8, 'ኤልያስም መጠምጠሚያውን ወስዶ ጠቀለለው፤ የዮርዳኖስንም ውኃ መታበት፤ ውኃውም ወዲህና ወዲያ ተከፈለ፤ ሁለቱም በደረቅ ተሻገሩ። ወጥተውም በምድረ በዳው ቆሙ።'),
  ('4b53925a-f5f4-5753-af72-fb989c3d5923', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 9, 9, 'ከተሻገሩም በኋላ ኤልያስ ኤልሳዕን፥ “ከአንተ ሳልወሰድ አደርግልህ ዘንድ የምትሻውን ለምን” አለው፤ ኤልሳዕም፥ “መንፈስህ በእኔ ላይ ሁለት እጥፍ ይሆን ዘንድ እለምንሃለሁ” አለ።'),
  ('6993d55a-e5cb-54d6-abdf-8eb961b8eb01', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 10, 10, 'ኤልያስም፥ “አስቸጋሪ ነገር ለምነሃል፤ ነገር ግን ከአንተ ዘንድ በተወሰድሁ ጊዜ ብታየኝ ይሆንልሃል፤ አለዚያ ግን አይሆንልህም” አለው።'),
  ('7400efbd-eb9b-54e6-af60-d6deef9753e6', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 11, 11, 'ሁለቱም እየተነጋገሩ ሲሄዱ፥ እነሆ፥ የእሳት ሰረገላና የእሳት ፈረሶች በሁለቱ መካከል ገብተው ከፈሉአቸው፤ ኤልያስም በዐውሎ ነፋስ ንውጽውጽታ ወደ ሰማይ ወጣ።'),
  ('45eca3f8-86a9-51db-a732-96e9457b5fa9', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 12, 12, 'ኤልሳዕም አይቶ፥ “አባቴ! አባቴ ሆይ! የእስራኤል ኀይላቸውና ጽንዓቸው፥” ብሎ ጮኸ። ከዚያም ወዲያ ዳግመኛ አላየውም፤ ልብሱንም ይዞ ከሁለት ቀደደው።'),
  ('15b78c12-eae7-52ec-af2c-73ae5500afe2', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 13, 13, 'ኤልያስም መጠምጠሚያውን ለኤልሳዕ ጣለለት፤ በኤልሳዕም ራስ ላይ ዐረፈ። ኤልሳዕም ተመልሶ በዮርዳኖስ ዳር ቆመ።'),
  ('f08b5d9b-3b68-5800-a320-6f60462f6b40', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 14, 14, 'በራሱ ላይ ያረፈችውን የኤልያስን መጠምጠሚያ ወስዶ ውኃውን መታባት፦ ውኃው ግን አልተከፈለም፤ እርሱም፥ “የኤልያስ አምላክ እግዚአብሔር ወዴት ነው? እንዴትስ ነው?” አለ። ከዚህም በኋላ ውኃውን በመታ ጊዜ ወዲህና ወዲያ ተከፈለ፤ ኤልሳዕም ተሻገረ።'),
  ('5a8ebabc-8b51-5e10-a12d-e8b0b6b24107', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 15, 15, 'በኢያሪኮም የነበሩት የነቢያት ልጆች ኤልሳዕ ወደ እነርሱ ሲመጣ ባዩት ጊዜ፥ “የኤልያስ መንፈስ በኤልሳዕ ላይ ዐርፎአል” አሉ። ሊገናኙትም መጥተው በፊቱ በምድር ላይ ሰገዱለት።'),
  ('bad2bfa8-d7e6-524f-aaf1-e369cdef35e5', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 16, 16, 'እነርሱም፥ “እነሆ፥ ከአገልጋዮችህ ጋር አምሳ ኀ`ያላን ሰዎች አሉ፤ የእግዚአብሔር መንፈስ ወደ ዮርዳኖስ ወይም ወደ አንድ ተራራ ወይም ወደ አንድ ኮረብታ ጥሎት እንደ ሆነ፥ ሄደው ጌታህን ይፈልጉት” አሉት። ኤልሳዕም፥ “አትላኩ፤” አላቸው።'),
  ('d4ec5888-e42c-5875-a7ec-b0c4b3e4f1cc', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 17, 17, 'እስኪያፍራቸውም ድረስ ግድ ባሉት ጊዜ፥ “ላኩ” አለ፤ አምሳም ሰዎች ላኩ፤ ሦስት ቀንም ፈልገው አላገኙትም።'),
  ('941d32ee-bdcb-5cdd-a2d3-d6027913c121', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', '96db3fe1-ca1f-581c-a61e-719568609359', 18, 18, 'በኢያሪኮም ተቀምጦ ሳለ ወደ እርሱ ተመለሱ፤ እርሱም፥ “አትላኩ፥ አትሂዱም አላልኋችሁምን?” አላቸው።'),
  ('11cce97b-6f4a-54c5-af79-77fec64edff0', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', 'c29a58df-88a3-56b0-a2e6-9c17ced1cdd7', 1, 19, 'የከተማዪቱም ሰዎች ኤልሳዕን፥ “እነሆ፥ ጌታችን እንደምታይ የዚች ከተማ ኑሮ መልካም ነው፤ ውኃው ግን ክፉ ነው፤ ሴቶችም ሲጠጡት ይመክናሉ፥” አሉት።'),
  ('1e6aac6a-e5cb-501e-aa9e-2717264c7449', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', 'c29a58df-88a3-56b0-a2e6-9c17ced1cdd7', 2, 20, 'እርሱም፥ “አዲስ ማሰሮ አምጡልኝ፤ ጨውም ጨምሩበት” አለ፤ ያንም አመጡለት።'),
  ('e0277689-94cd-53ed-a52d-eb9644726433', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', 'c29a58df-88a3-56b0-a2e6-9c17ced1cdd7', 3, 21, 'ውኃው ወዳለበትም ምንጭ ወጥቶ ጨው ጣለበትና፥ “እግዚአብሔር እንዲህ ይላል፦ ይህን ውኃ ፈውሼዋለሁ፤ ከዚህም በኋላ የሚሞት፥ የሚመክንም አይኖርም” አለ።'),
  ('9e5349d4-c354-5b27-a100-dec8953fbdec', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', 'c29a58df-88a3-56b0-a2e6-9c17ced1cdd7', 4, 22, 'ኤልሳዕም እንደ ተናገረው ነገር ውኃው ከዚያ ቀን ጀምሮ እስከ ዛሬ ድረስ ተፈውሶአል።'),
  ('2b807210-72df-54a4-a788-ded7c976d314', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', 'c29a58df-88a3-56b0-a2e6-9c17ced1cdd7', 5, 23, 'ከዚያም ወደ ቤቴል ወጣ፤ በመንገድም ሲወጣ ልጆች ከከተማዪቱ ወጥተው፥ “አንተ ራሰ በራ! ውጣ! አንተ ራሰ በራ! ውጣ” ብለው አፌዙበት።'),
  ('4c62a6ec-579d-5db2-a4fa-3b148cadf4ab', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', 'c29a58df-88a3-56b0-a2e6-9c17ced1cdd7', 6, 24, 'ዘወርም ብሎ አያቸው፤ በእግዚአብሔርም ስም ረገማቸው፤ ወዲያውም ከዱር ሁለት ድቦች ወጥተው ከእነርሱ አርባ ሁለቱን ሰባበሩአቸው።'),
  ('f009321c-7115-56d2-a5de-8ca3fd064d56', 'ce54b059-d306-582f-a13b-7871bb4f4d5f', 'c29a58df-88a3-56b0-a2e6-9c17ced1cdd7', 7, 25, 'ከዚያም ወደ ቀርሜሎስ ተራራ ሄደ፤ ከዚያም ወደ ሰማርያ ተመለሰ።'),
  ('c0cfb670-c97e-51a9-a213-68442581c876', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 1, 1, 'በይሁዳም ንጉሥ በኢዮሣፍጥ በዐሥራ ስምንተኛው ዓመተ መንግሥት የአክዓብ ልጅ ኢዮራም በእስራኤል ላይ በሰማርያ መንገሥ ጀመረ፤ ዐሥራ ሁለትም ዓመት ነገሠ።'),
  ('c3e04d5d-f9a5-5442-a9a3-d390c418541a', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 2, 2, 'በእግዚአብሔርም ፊት ክፉ አደረገ፤ ነገር ግን እንደ አባቱና እንደ እናቱ አልነበረም፤ አባቱም ያሠራውን የበዓልን ምስል አጠፋ።'),
  ('28489049-f606-5fbe-ad3d-91b324299082', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 3, 3, 'ነገር ግን እስራኤልን ያሳታቸውን የናባጥን ልጅ የኢዮርብዓምን ኀጢአት ተከተለ፤ እርሱንም አልተወም።'),
  ('8ee03f4d-7d33-5e08-a971-176a082bacdd', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 4, 4, 'የሞዓብም ንጉሥ ሞሳ ባለ በጎች ነበር፤ ለእስራኤልም ንጉሥ መቶ ሺህ የጠጕር አውራ በጎችንና መቶ ሺህ ጠቦቶችን ይገብርለት ነበር።'),
  ('15e0bf67-15bf-5c9b-aec8-22a001e77cbb', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 5, 5, 'አክዓብም ከሞተ በኋላ የሞዓብ ንጉሥ የእስራኤልን ንጉሥ ከዳው።'),
  ('c09b05b2-00bc-5477-a843-37f8288df192', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 6, 6, 'በዚያም ጊዜ ንጉሡ ኢዮራም ከሰማርያ ወጥቶ እስራኤልን ሁሉ ቈጠራቸው።'),
  ('016d851f-2754-5058-af7a-c38b0f83c0de', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 7, 7, 'ወደ ይሁዳም ንጉሥ ወደ ኢዮሣፍጥ፥ “የሞዓብ ንጉሥ ከዳኝ፤ ከእኔ ጋር በሞዓብ ላይ ለሰልፍ ትሄዳለህን?” ብሎ፤ ላከ። እርሱም፥ “እወጣለሁ፤ እኔ እንደ አንተ፥ አንተም እንደ እኔ፥ ሕዝቤም እንደ ሕዝብህ፥ ፈረሶቼም እንደ ፈረሶችህ ናቸው” አለ።'),
  ('a6e5cdfa-9fe8-5880-a320-3244efca5e77', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 8, 8, 'ደግሞም፥ “በየትኛው መንገድ እንሄዳለን?” አለ፤ እርሱም፥ “በኤዶምያስ ምድረ በዳ መንገድ” አለው።'),
  ('5c4d0c00-d48e-5f12-acf0-72ec394fd5e8', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 9, 9, 'የእስራኤልም ንጉሥና የይሁዳ ንጉሥ፥ የኤዶምያስም ንጉሥ ሄዱ፤ የሰባትም ቀን መንገድ ዞሩ፤ ለሠራዊቱና ለሚጫኑ እንስሶች ውኃ አጡ።'),
  ('cc64636f-1e4b-5a84-a4ff-8beeb0d893ef', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 10, 10, 'የእስራኤልም ንጉሥ፥ “እግዚአብሔር በሞዓብ እጅ አሳልፎ ይሰጣቸው ዘንድ እነዚህን ሦስቱን ነገሥታት ጠርቶአልና ወዮ!” አለ።'),
  ('9125643e-4820-5f74-a7de-174294b058ed', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 11, 11, 'ኢዮሣፍጥም፥ “በእርሱ እግዚአብሔርን የምንጠይቅበት የእግዚአብሔር ነቢይ በዚህ አይገኝምን?” አለ። ከእስራኤልም ንጉሥ አገልጋዮች አንዱ፥ “ኤልያስን እጁን ያስታጥብ የነበረው የሣፋጥ ልጅ ኤልሳዕ እዚህ አለ” ብሎ መለሰ።'),
  ('236af582-6236-577a-a039-47759a5c88ec', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 12, 12, 'ኢዮሣፍጥም፥ “የእግዚአብሔር ቃል በእርሱ ዘንድ ይገኛል” አለ። የእስራኤል ንጉሥና የይሁዳ ንጉሥ ኢዮሣፍጥ የኤዶምያስም ንጉሥ ወደ እርሱ ወረዱ።'),
  ('84ce120a-de1e-5b7d-aa7c-d5c4eb8eed47', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 13, 13, 'ኤልሳዕም የእስራኤልን ንጉሥ፥ “እኔ ከአንተ ጋር ምን አለኝ? ወደ አባትህ ነቢያትና ወደ እናትህ ነቢያት ሂድ፥” አለው። የእስራኤልም ንጉሥ፥ “አይደለም፤ በሞዓብ እጅ ይጥላቸው ዘንድ እግዚአብሔር እነዚህን ሦስት ነገሥታት ጠርቶአልን?” አለው።'),
  ('836fc5d5-33e9-5bf6-a437-c73ba2aba1de', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 14, 14, 'ኤልሳዕም፥ “በፊቱ የቆምሁት የሠራዊት ጌታ ሕያው እግዚአብሔርን! የይሁዳን ንጉሥ ኢዮሣፍጥን ያፈርሁ ባልሆን ኖሮ አንተን ባልተመለከትሁና ባላየሁ ነበር።'),
  ('533c6118-4d40-5a9b-a0d7-6b7b4bc37853', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 15, 15, 'አሁንም ባለ በገና አምጡልኝ” አለ። ባለ በገናውም በደረደረ ጊዜ የእግዚአብሔር እጅ በእርሱ ላይ መጣ።'),
  ('e8efa1b9-005f-5ea4-aa80-566db336de26', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 16, 16, 'እንዲህም አለ፥ “እግዚአብሔር እንዲህ ይላል፦ በዚህ ሸለቆ ሁሉ ጕድጓድ ቈፍሩ።'),
  ('e30c5956-9dc8-5134-ac6e-32da6de17719', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 17, 17, 'እግዚአብሔርም እንዲህ ይላል፦ ነፋስ አታዩም፤ ዝናብም አታዩም፤ ይህ ሸለቆ ግን ውኃ ይሞላል፤ እናንተም፥ ከብቶቻችሁም፥ እንስሶቻችሁም፥ ትጠጣላችሁ።'),
  ('28a19ddc-8369-526d-a912-f614ca0359ee', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 18, 18, 'ይህ በእግዚአብሔር ዐይን ቀላል ነገር ነውና፤ ደግሞም ሞዓባውያንን በእጃችሁ አሳልፎ ይሰጣል።'),
  ('1583fcc5-9d83-5109-ad23-7c35d230bf19', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 19, 19, 'የተመሸጉትንም ከተሞች ሁሉ ትመታላችሁ፤ የሚያምሩትንም ዛፎች ሁሉ ትቈርጣላችሁ፤ የውኃውንም ምንጮች ሁሉ ትደፍናላችሁ፤ መልካሞቹንም እርሻዎች ሁሉ በድንጋይ ታበላሻላችሁ።”'),
  ('2568815b-98ee-5fb1-a142-1e58dec1ee7c', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 20, 20, 'በነጋውም መሥዋዕት በሚቀርብበት ጊዜ፥ እነሆ፥ ውኃ በኤዶምያስ መንገድ መጣ፤ ምድሪቱም ውኃ ሞላች።'),
  ('051c1596-d880-51e7-a214-b77bf6265a91', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 21, 21, 'ሞዓባውያንም ሁሉ እነዚያ ነገሥታት ሊወጉአቸው እንደ መጡ በሰሙ ጊዜ፥ “ሁላችሁ መሣሪያዎችን ይዛችሁ ርዱን” ብለው በሀገራቸው ሁሉ ጮኹ። ተሰበሰቡም፤ ወጥተውም በተራራው ራስ ላይ ቆሙ።'),
  ('5978ea9d-37fd-5d20-a7c9-18258310909d', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 22, 22, 'ማልደውም ተነሡ፤ ፀሐይም በውኃው ላይ አንጸባረቀ፤ ሞዓባውያንም በፊታቸው ውኃው እንደ ደም ቀልቶ አዩና፦'),
  ('3ddf9d9a-7e0d-59c9-afce-93485cc9c383', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 23, 23, '“ይህ የጦር ደም ነው፤ እነዚያ ነገሥታት እርስ በርሳቸው ተጋደሉ፤ ባልንጀሮቻቸውንም ገደሉ፤ አሁንም ሞዓብ ሆይ! እንግዲህ ወደ ምርኮህ ሂድ” አሉ።'),
  ('7885fa21-90a2-5da9-a801-c878b863d9e1', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 24, 24, 'ወደ እስራኤልም ሰፈር በመጡ ጊዜ እስራኤላውያን ተነሥተው ሞዓባውያንን መቱ፤ እነርሱም ከፊታቸው ሸሹ፤ ሞዓባውያንንም እየመቱ ወደ ሀገሩ ውስጥ ገቡ።'),
  ('c07ff854-df0c-5473-ae0d-dd5eb447ea33', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 25, 25, 'ከተሞቻቸውንም አፈረሱ፤ በመልካሞቹም እርሻዎቻቸው ሁሉ ላይ እስኪሞሉ ድረስ እያንዳንዱ ሰው አንድ አንድ ድንጋይ ይጥል ነበር፤ የውኃውንም ምንጮች ሁሉ ደፈኑ፤ የከተሞቻቸውንም ቅጥር አፈረሱ፤ የሚያምሩትን ዛፎች ሁሉ ቈረጡ፤ ባለ ወንጭፎችም ከብበው መቱአቸው።'),
  ('85481c7c-4447-5337-a436-e548b8e0b2f8', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 26, 26, 'የሞዓብም ንጉሥ እንደ ገደሉአቸውና ድል እንደነሡአቸው ባየ ጊዜ ሰይፍ የሚመዝዙ ሰባት መቶ ሰዎችን ከእርሱ ጋር ወሰደ፤ ወደ ኤዶምያስም ንጉሥ ያልፉ ዘንድ ሞከሩ፤ አልቻሉምም።'),
  ('538f092e-8345-5b33-a7cd-176d76fb9274', 'd62d4965-29b5-5b94-a54a-2049e0fbecd8', 'd44a7917-0e80-5903-af8c-88176cf5c944', 27, 27, 'ከዚህ በኋላ በእርሱ ፋንታ ንጉሥ የሚሆነውን የበኵር ልጁን ወስዶ ለሚቃጠል መሥዋዕት በቅጥሩ ላይ አቀረበው። እስራኤልም ታላቅ ጸጸት ተጸጸቱ፤ ከዚያም ርቀው ወደ ምድራቸው ተመለሱ።'),
  ('ea5b4ce1-1005-53f1-ad8e-a165cf3442f4', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e3907b34-3b99-5555-ad80-974c5298cb63', 1, 1, 'ከነቢያትም ልጆች የአንዱ ሚስት የሆነች አንዲት ሴት፥ “ባሌ ባሪያህ ሞቶአል፤ ባሪያህም እግዚአብሔርን የሚፈራ ሰው እንደ ነበረ አንተ ታውቃለህ፤ ባለ ዕዳም ሁለቱ ልጆቼን ባሪያዎች አድርጎ ሊወስዳቸው መጥቶአል” ብላ ወደ ኤልሳዕ ጮኸች።'),
  ('150389bc-84f9-5a30-ad74-687156af0ca7', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e3907b34-3b99-5555-ad80-974c5298cb63', 2, 2, 'ኤልሳዕም፥ “አደርግልሽ ዘንድ ምን ትሻለሽ? በቤትሽም ያለውን ንገሪኝ” አላት። እርስዋም፥ “ለእኔ ለአገልጋይህ ከዘይት ማሰሮ በቀር በቤቴ አንዳች የለኝም” አለችው።'),
  ('f26c35f9-e30c-5162-a209-efc523709f86', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e3907b34-3b99-5555-ad80-974c5298cb63', 3, 3, 'እርሱም፥ “ሂጂና ከጎረቤቶችሽ ሁሉ ከውጭ ባዶ ማድጋዎችን ተዋሺ፤ አታሳንሻቸውም።'),
  ('33fd7a4b-eb76-5220-af2b-6ca5eb777021', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e3907b34-3b99-5555-ad80-974c5298cb63', 4, 4, 'ወደ ቤትሽም ገብተሽ ከአንቺና ከልጆችሽ በኋላ በሩን ዝጊ፤ ወደ እነዚህም ማድጋዎች ሁሉ ዘይቱን ገልብጪ፤ የሞላውንም ፈቀቅ አድርጊ” አላት።'),
  ('b595a917-6795-5d30-a286-cffba20ec0f6', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e3907b34-3b99-5555-ad80-974c5298cb63', 5, 5, 'እንዲሁም ከእርሱ ሄዳ፥ በሩን ከእርስዋና ከልጆችዋ በኋላ ዘጋች፤ እነርሱም ማድጋዎቹን ወደ እርስዋ ያቀርቡላት ነበር፤ እርስዋም ትገለብጥ ነበር።'),
  ('14a23d63-94c0-55ab-a5b4-06570d549ac5', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e3907b34-3b99-5555-ad80-974c5298cb63', 6, 6, 'ከዚህም በኋላ ልጆችዋን፥ “ደግሞ ማድጋ አምጡልኝ” አለቻቸው፤ እነርሱም፥ “ሌላ ማድጋ የለም” አሏት፤ ዘይቱም ቆመ።'),
  ('2873a36a-d149-5c7c-af45-86fd4ae303d5', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e3907b34-3b99-5555-ad80-974c5298cb63', 7, 7, 'መጥታም ለእግዚአብሔር ሰው ነገረችው፤ እርሱም፥ “ሄደሽ ዘይቱን ሽጭ ዕዳሽንም ክፈዪ፤ በተረፈውም ዘይት የአንቺንና የልጆችሽን ሰውነት አድኚ” አላት።'),
  ('f8fe3388-1e12-5aae-acb5-124945a15a43', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 1, 8, 'ከዚህም በኋላ አንድ ቀን እንዲህ ሆነ፤ ኤልሳዕ ወደ ሱማን አለፈ፤ በዚያም ታላቅ ሴት ነበረች፤ እንጀራም ይበላ ዘንድ አቆመችው፤ በዚያም ባለፈ ቍጥር እንጀራ ሊበላ ወደዚያ ይገባ ነበር።'),
  ('20081725-1e32-5e3d-a87e-01af6298676f', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 2, 9, 'ሴትዮዋም ለባልዋ፥ “ይህ በእኛ ዘንድ ሁልጊዜ የሚያልፈው ቅዱስ የእግዚአብሔር ሰው እንደ ሆነ አውቃለሁ።'),
  ('7c1b3955-f99e-59ed-afc4-bc7806494846', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 3, 10, 'ትንሽ ቤት በሰገነቱ ላይ እንሥራ፤ በዚያም አልጋና ጠረጴዛ፥ ወንበርና መቅረዝ እናኑርለት፤ ወደ እኛም ሲመጣ ወደዚያ ይግባ” አለችው።'),
  ('4415fbbb-2855-5e14-a2d2-34e6a51f2829', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 4, 11, 'አንድ ቀንም ወደዚያ በመጣ ጊዜ ወደ ቤቱ ገብቶ በዚያ ተኛ።'),
  ('94366b2f-4564-506f-afd0-3af69a173944', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 5, 12, 'ሎሌውንም ግያዝን፥ “ይህችን ሱማናዊት ጥራ” አለው። በጠራትም ጊዜ በፊቱ ቆመች።'),
  ('c2b50db1-2958-5c54-a301-af3ebd941eb8', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 6, 13, 'እርሱም፥ “እነሆ፥ ይህን ሁሉ ክብር አከበርሽኝ ምን ላድርግልሽ? ለንጉሥ ወይስ ለሠራዊት አለቃ የምነግርልሽ ጉዳይ እንዳለሽ በላት” አለው፤ እርስዋም፥ “እኔ በወገኔ መካከል እኖራለሁ” ብላ መለሰች።'),
  ('ac98adc8-164e-559f-a836-eb7337ee4bd0', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 7, 14, 'እርሱም ግያዝን፥ “እንግዲህ ምን እናድርግላት?” አለው። ሎሌው ግያዝም፤ “ልጅ የላትም፥ ባልዋም ሸምግሎአል” ብሎ መለሰ።'),
  ('1bfed9cb-988d-5749-a7ff-64f107269006', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 8, 15, 'እርሱም፥ “ጥራት” አለው። ጠራትም በደጃፉም ቆመች።'),
  ('b416cd3d-d316-58f0-a9c1-dbcf437e9a97', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 9, 16, 'ኤልሳዕም፥ “በሚመጣው ዓመት በዚህ ወራት ወንድ ልጅ ትታቀፊያለሽ” አላት፤ እርስዋም፥ “አይደለም ጌታዬ ሆይ፥ አገልጋይህን አትዋሻት” አለችው።'),
  ('a8a0c8c3-5c08-55b1-a048-f98488b27ccb', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 10, 17, 'ከዚያም በኋላ ሴቲቱ ፀነሰች፥ በዓመቱም ኤልሳዕ በነገራት ወራት ወንድ ልጅ ወለደች።'),
  ('a1ae8601-9fbf-50fa-addb-893c9f3dc010', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 11, 18, 'ሕፃኑም አደገ፤ እህል አጫጆችም ወዳሉበት ወደ አባቱ መጣ። አባቱንም፥ “ራሴን ራሴን” አለው፤'),
  ('7c98fc3b-b7a3-5ba2-ac44-d1513a9583df', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 12, 19, 'አባቱም ሎሌውን፥ “ተሸክመህ ወደ እናቱ ውስደው” አለው።'),
  ('11ad67f8-1cc1-57df-ab2a-52f0cb7d12da', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 13, 20, 'አንሥቶም ወደ እናቱ ወሰደው፤ በጕልበቷም ላይ እስከ ቀትር ድረስ አስተኛችው፤ ሞተም።'),
  ('b86ae065-d714-574e-a538-ddadfac30cad', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 14, 21, 'አውጥታም በእግዚአብሔር ሰው አልጋ ላይ አጋደመችው፤ በሩንም ዘግታበት ወጣች።'),
  ('29beb6f9-9617-5ba7-af34-b5139d64ce6d', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 15, 22, 'ባልዋንም ጠርታ፥ “ወደ እግዚአብሔር ሰው ዘንድ በፍጥነት እሄዳለሁና አንድ ሎሌና አንድ አህያ ላክልኝ” አለችው።'),
  ('dd61b1c0-8bd9-5b62-a8b4-34ed3f474bc2', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 16, 23, 'እርሱም፥ “መባቻ ወይም ሰንበት ያይደለ ዛሬ ለምን ትሄጃለሽ?” አለ። እርስዋም፥ “ደኅና ነው” አለች።'),
  ('9f982379-5d74-5dfb-a96e-ecc94e4f721f', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 17, 24, 'አህያውንም አስጭና ሎሌዋን፥ “ንዳ፥ ሂድ፤ እኔ ሳላዝዝህ አታዘግየኝ፤ ወደ እግዚአብሔር ሰው ወደ ቄርሜሎስ ተራራ እንሂድ” አለችው።'),
  ('926cf888-2757-5b95-a4b0-93a5c8193bc6', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 18, 25, 'እንዲሁም ሄደች፤ ወደ እግዚአብሔርም ሰው ወደ ቀርሜሎስ ተራራ ወጣች። ኤልሳዕም ያችን ሴት ወደ እርሱ ስትመጣ ባያት ጊዜ ሎሌውን ግያዝን፥ “እነኋት፥ ሱማናዊት መጣች፤'),
  ('a6eaec53-d169-53de-a32c-7181fca3b351', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 19, 26, 'አሁንም ሩጥና ተቀበላት፤ በደኅናሽ ነውን? ባልሽ ደኅና ነውን? ልጅሽስ ደኅና ነውን? በላት” አለው። እርስዋም፥ “ደኅና ነው” አለች።'),
  ('1f0b7212-c747-5197-a199-fe3475e4fdcf', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 20, 27, 'ወደ ተራራውም ወደ ኤልሳዕ ደርሳ እግሮቹን ጨበጠች፤ ግያዝም ሊያርቃት መጣ፤ ኤልሳዕም፥ “ነፍስዋ አዝናለችና ተዋት፤ እግዚአብሔርም ያን ከእኔ ሰውሮታል፤ አልነገረኝምም” አለ።'),
  ('94c74714-7871-53f0-adcc-2123c38da379', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 21, 28, 'እርስዋም፥ “በውኑ ከጌታዬ ልጅን ለመንሁን? እኔም አታታልለኝ አላልሁህምን?” አለች።'),
  ('35094826-eb41-51d6-a7bd-061e5cc71930', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 22, 29, 'ኤልሳዕም ግያዝን፥ “ወገብህን ታጠቅ፤ በትሬንም በእጅህ ይዘህ ሂድ፤ ሰውም ብታገኝ ሰላም አትበል፤ እርሱም ሰላም ቢልህ አትመልስለት፤ በትሬንም በሕፃኑ ፊት ላይ አኑር” አለው።'),
  ('27829fba-4db8-5278-a298-6555738a8257', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 23, 30, 'የሕፃኑም እናት፥ “ሕያው እግዚአብሔርን! ሕያው ነፍስህንም! አልተውህም” አለች፤ ኤልሳዕም ተነሥቶ ተከተላት።'),
  ('45469aa7-d0f1-5f4c-a411-33eae68056f4', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 24, 31, 'ግያዝም በፊታቸው ይሄድ ነበር፤ ግያዝም ቀድሞአቸው ደረሰ፤ በትሩንም በሕፃኑ ፊት ላይ አኖረው፤ ነገር ግን ድምፅ ወይም መስማት አልነበረም፤ እርሱንም ሊገናኘው ተመልሶ፥ “ሕፃኑ አልተነሣም” ብሎ ነገረው።'),
  ('cc10cf43-7cd6-5164-a449-03071f9338cd', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 25, 32, 'ኤልሳዕም ወደ ቤት በገባ ጊዜ እነሆ፥ ሕፃኑ ሞቶ በአልጋው ላይ ተጋድሞ ነበር።'),
  ('bcbd595c-e59e-5ba5-a13f-9218c26c6b48', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 26, 33, 'ኤልሳዕም ወደ ቤት ገብቶ በሩን በሁለቱ ላይ ዘጋ፤ ወደ እግዚአብሔርም ጸለየ።'),
  ('4dac5899-198a-513f-a675-83e93341456c', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 27, 34, 'መጥቶም በሕፃኑ ላይ ተኛ፤ አፉንም በአፉ፥ ዐይኖቹንም በዐይኖቹ፥ እጆቹንም በእጆቹ ላይ አድርጎ ተጋደመበት፤ የሕፃኑም ሰውነት ሞቀ።'),
  ('128dbce8-2ffe-551a-abf8-04fc8b67e971', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 28, 35, 'ተመልሶም በቤቱ ውስጥ አንድ ጊዜ ወዲህና ወዲያ ተመላለሰ፤ ደግሞም ወጥቶ ሰባት ጊዜ በሕፃኑ ላይ ተጋደመ፤ ከዚያም በኋላ ሕፃኑ ዐይኖቹን ከፈተ።'),
  ('db141fd5-e334-533e-afd9-f188f8e80406', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 29, 36, 'ግያዝንም ጠርቶ፥ “ይህችን ሱማናዊት ጥራ” አለው። ጠራትም፤ ወደ እርሱም በገባች ጊዜ፥ “ልጅሽን አንሥተሽ ውሰጂ” አላት።'),
  ('2b13632c-0bd4-50f5-adbb-cc259a4597af', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'dcd4cafb-a278-5ea0-a1ec-b506117d3c0c', 30, 37, 'ሴትዮዋም ገብታ በእግሩ አጠገብ ወደቀች በምድርም ላይ ሰገደች፤ ልጅዋንም አንሥታ ወጣች።'),
  ('e30058b3-4dba-55e6-aa2c-0650bfab096e', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e70bd2e1-9fe3-566c-a4e5-3d09b1da4728', 1, 38, 'ኤልሳዕም ዳግመኛ ወደ ጌልጌላ ተመለሰ፤ በምድርም ላይ ራብ ነበረ፤ የነቢያትም ልጆች በፊቱ ተቀምጠው ነበር፤ ኤልሳዕም ሎሌውን፥ “ታላቁን ምንቸት ጣድ፤ ለነቢያትም ልጆች ቅጠላ ቅጠል አብስልላቸው” አለው።'),
  ('ebc897a4-8c57-5e36-a0ed-80f3894ffba6', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e70bd2e1-9fe3-566c-a4e5-3d09b1da4728', 2, 39, 'አንዱም ቅጠላ ቅጠል ያመጣ ዘንድ ወደ ሜዳ ወጣ፤ በምድረ በዳውም የወይን ቦታ አገኘ፤ ከዚያም የምድር ቅጠላ ቅጠል ሰብሰበ፤ ልብሱንም ሞላ፤ መትሮም በወጡ ምንቸት ውስጥ ጨመረው፤ አበሰለውም፤ ምን እንደ ሆነ ግን አላወቁም።'),
  ('7b730f5d-c44e-5df7-ab89-0af78d9fd931', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e70bd2e1-9fe3-566c-a4e5-3d09b1da4728', 3, 40, 'ከዚህም በኋላ ሰዎቹ ይበሉ ዘንድ አቀረበላቸው፤ የበሰለውንም ቅጠል በሚበሉበት ጊዜ፥ “የእግዚአብሔር ሰው ሆይ፥ በምንቸቱ ውስጥ መርዝ አለ” ብለው ጮኹ፤ ይበሉም ዘንድ አልቻሉም።'),
  ('1fb8c350-11e8-514d-a480-e9819cf59be6', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e70bd2e1-9fe3-566c-a4e5-3d09b1da4728', 4, 41, 'ኤልሳዕም፥ “ዶቄት አምጣና በምንቸቱ ውስጥ ጨምረው” አለው፥ ኤልሳዕም ግያዝን፥ “ለሕዝቡ መልስላቸው ይብሉ” አለው። ከዚህም በኋላ በምንቸቱ ውስጥ ክፉ ነገር አልተገኘም።'),
  ('8288f5b2-1b77-5109-a39c-6ce175e63e8d', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e70bd2e1-9fe3-566c-a4e5-3d09b1da4728', 5, 42, 'አንድ ሰውም ከቤትሣሪሳ ከእህሉ ቀዳምያት፥ ሃያ የገብስ እንጀራ፥ የእህልም እሸት በአቁማዳ ይዞ ወደ እግዚአብሔር ሰው መጣ፤ ኤልሳዕም አገልጋዩን፥ “ይበሉ ዘንድ ለሕዝቡ ስጣቸው” አለ።'),
  ('6e0ac683-cefa-503d-a211-ca33ed85ca15', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e70bd2e1-9fe3-566c-a4e5-3d09b1da4728', 6, 43, 'ሎሌውም፥ “ይህን እንዴት አድርጌ ለመቶ ሰው አቀርባለሁ?” አለ። እርሱም፥ “ይበላሉ፥ ያተርፋሉም ብሎ እግዚአብሔር ተናግሮአልና ይበሉ ዘንድ ለሕዝቡ ስጣቸው” አለው።'),
  ('e8027f92-01d0-558e-a599-068ad343eb7c', '72320c36-f514-5e52-ab8d-9d8d91fd2adc', 'e70bd2e1-9fe3-566c-a4e5-3d09b1da4728', 7, 44, 'እርሱም አቀረበላቸው፤ እንደ እግዚአብሔርም ቃል በሉ፤ አተረፉም።'),
  ('aa32f0d5-9397-5ff2-ad59-d54650ae2487', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 1, 1, 'የሶርያ ንጉሥ ሠራዊት አለቃ ንዕማንም እግዚአብሔር በእርሱ እጅ ለሶርያ ደኅንነትን ስለ ሰጠ፥ በጌታው ዘንድ ታላቅና ክቡር ሰው ነበረ፤ ሰውዬውም ጽኑዕ፥ ኀያል ነበረ፤ ነገር ግን ለምጻም ነበረ።'),
  ('eb68ff48-581d-5b9a-a0aa-c5da53b929c1', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 2, 2, 'ከሶርያውያንም ጋር ወደ ሰልፍ በወጣ ጊዜ ከእስራኤል ምድር ታናሽ ብላቴና ሴት ማረከ፤ ለሚስቱም አገልጋይ አደረጋት።'),
  ('8f310a60-380f-5b8b-a81c-a40e8a6ee240', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 3, 3, 'እመቤቷንም፥ “ጌታዬ በሰማርያ ወደሚኖረው ወደ እግዚአብሔር ሰው ወደ ነቢዩ ይሄድ ዘንድ በተገባው ነበር፤ ከለምጹም በፈወሰው ነበር” አለቻት።'),
  ('a6e72171-767c-5134-af85-a7d5e42e396a', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 4, 4, 'ሚስቱም ወደ እርሱ ገብታ፥ “ከእስራኤል ሀገር የመጣች ይች ብላቴና እንደዚህና እንደዚህ አለች” ብላ ነገረችው።'),
  ('69ee16b7-23a0-59f4-a469-8e50ccdafbb2', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 5, 5, 'የሶርያም ንጉሥ ንዕማንን፥ “ሂድ፥ ለእስራኤል ንጉሥ ደብዳቤ እልካለሁ” አለው። እርሱም ሄደ፤ ዐሥርም መክሊት ብር፥ ስድስት ሺህም ወቄት ወርቅ፥ ዐሥርም መለወጫ ልብስ በእጁ ወሰደ።'),
  ('d0e4bbd9-4e6a-5ead-a434-ebc5a8167eab', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 6, 6, 'ወደ እስራኤልም ንጉሥ፦ ደብዳቤውን አደረሰ። ደብዳቤውም እንዲህ ይላል፥ “ደብዳቤው ካንተ ዘንድ በደረሰ ጊዜ ባለሟሌን ንዕማንን ወደ አንተ ልኬዋለሁና ከለምጹ ፈውሰው።”'),
  ('b9c06d48-1304-5c6d-a094-da5be293f1f1', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 7, 7, 'የእስራኤልም ንጉሥ ደብዳቤውን ባነበበ ጊዜ ልብሱን ቀድዶ፥ “ሰውን ከለምጹ እፈውስ ዘንድ ይህ ሰው ወደ እኔ መስደዱ እኔ በውኑ ለመግደልና ለማዳን የምችል አምላክ ነኝን? ተመልከቱ፥ የጠብ ምክንያት እንደሚፈልግብኝ ተመልከቱ” አለ።'),
  ('8a415b3d-29fa-52cf-aae8-65bb9369244f', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 8, 8, 'ኤልሳዕም የእስራኤል ንጉሥ ልብሱን እንደ ቀደደ በሰማ ጊዜ፥ “ልብስህን ለምን ቀደድህ? ንዕማን ወደ እኔ ይምጣ፤ በእስራኤልም ዘንድ ነቢይ እንዳለ ያውቃል” ብሎ ወደ ንጉሡ ላከ።'),
  ('7f627ab6-1b10-5126-ad7f-a26fddab2f78', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 9, 9, 'ንዕማንም በፈረሱና በሰረገላው መጣ፤ በኤልሳዕም ቤት ደጃፍ ውጭ ቆመ።'),
  ('306629c7-a47e-50f3-a165-cc199ffa1abd', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 10, 10, 'ኤልሳዕም፥ “ሂድ፥ በዮርዳኖስም ሰባት ጊዜ ተጠመቅ፤ ሰውነትህም ይፈወሳል፤ አንተም ንጹሕ ትሆናለህ” ብሎ ወደ እርሱ መልእክተኛ ላከ።'),
  ('860813c6-3925-5dea-af02-3fb8c30a6842', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 11, 11, 'ንዕማን ግን ተቈጥቶ ሄደ፤ እንዲህም አለ፥ “እነሆ፥ ወደ እኔ የሚመጣ፥ ቆሞም የአምላኩን የእግዚአብሔርን ስም የሚጠራ፥ የለምጹንም ስፍራ በእጁ ዳስሶ የሚፈውሰኝ መስሎኝ ነበር።'),
  ('87ef0c53-c3d9-5817-ab8b-aeef914b3c7f', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 12, 12, 'የደማስቆ ወንዞች ባብናና ፋርፋ ከእስራኤል ውኆች ሁሉ አይሻሉምን? ሄጄስ በእነርሱ ውስጥ መጠመቅና መንጻት አይቻለኝም ኖሮአልን?” ብሎ በቍጣ ተመልሶ ሄደ።'),
  ('3d29ea25-6d86-5976-ab39-88916d0fc24d', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 13, 13, 'አገልጋዮቹም ወደ እርሱ መጥተው፥ “ነቢዩ ታላቅ ነገር ቢነግርህ ባደረግኸው ነበር፤ ይልቁንስ፦ ተጠመቅና ንጹሕ ሁን ቢልህ እንዴት ነዋ!” ብለው ተናገሩት።'),
  ('39a1ca67-f3da-5c7e-aac2-2b154defd586', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 14, 14, 'ንዕማንም ወረደ፤ የእግዚአብሔርም ሰው ኤልሳዕ እንደ ተናገረው በዮርዳኖስ ሰባት ጊዜ ተጠመቀ፤ ሰውነቱም እንደ ገና እንደ ትንሽ ብላቴና ሰውነት ሆኖ ተመለሰ፤ ንጹሕም ሆነ።'),
  ('b3ddb6cf-6f72-5dc0-aacb-4dd683e6dc34', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 15, 15, 'እርሱም ከጭፍራው ሁሉ ጋር ወደ ኤልሳዕ ተመለሰ፤ ወደ እርሱም ደርሶ በፊቱ ቆመና፥ “እነሆ፥ በእስራኤል ነው እንጂ በምድር ሁሉ አምላክ እንደሌለ ዐወቅሁ፤ አሁንም ከአገልጋይህ በረከት ተቀበል” አለው።'),
  ('42489972-f94b-5caa-aabd-f564762c1505', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 16, 16, 'ኤልሳዕም፥ “በፊቱ የቆምሁት ሕያው እግዚአብሔርን! አልቀበልም” አለ። ይቀበለውም ዘንድ ግድ አለው፤ እርሱ ግን እንቢ አለ።'),
  ('5bfb9476-67ab-5903-a489-c3f9ae0b99fe', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 17, 17, 'ንዕማንም፥ “እኔ አገልጋይህ ከእንግዲህ ወዲህ ከእግዚአብሔር በቀር ለሌሎች አማልክት የሚቃጠል መሥዋዕት ወይም ሌላ መሥዋዕት አላቀርብምና ሁለት የበቅሎ ጭነት አፈር ለአገልጋይህ ይስጡት።'),
  ('c921f0c0-9455-5a25-a33e-5a4471189486', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 18, 18, 'እግዚአብሔርም የእኔን የአገልጋይህን ኀጢአት በዚህ ነገር ብቻ ይቅር ይበለኝ፤ ጌታዬ በዚያ ይሰግድ ዘንድ እጄን ተደግፎ ወደ ሬማን ቤት በገባና በሰገደ ጊዜ፥ እኔም በሬማን ቤት በሰገድሁ ጊዜ፥ እግዚአብሔር በዚህ ነገር እኔን አገልጋይህን ይቅር ይለኛል” አለ።'),
  ('aa9fa240-169f-5a1c-a21a-60ccb9fedecc', '82773bae-9dea-5e81-a442-3269ff73eb98', 'd1b18a72-6aee-5894-aafc-1fbb711669f7', 19, 19, 'ኤልሳዕም ንዕማንን፥ “በሰላም ሂድ” አለው። ጥቂት መንገድም ከእርሱ ራቀ።'),
  ('79120722-535e-5a97-a944-d1fea65d873c', '82773bae-9dea-5e81-a442-3269ff73eb98', '6b5d3588-f295-5b9b-aea3-fe430c1034bb', 1, 20, 'የኤልሳዕም ሎሌ ግያዝ፥ “ጌታዬ ሶርያዊውን ይህን ንዕማንን ማረው፤ ካመጣለትም ነገር ምንም አልተቀበለም፤ ሕያው እግዚአብሔርን! በስተኋላው እሮጣለሁ፤ ከእርሱም አንዳች እወስዳለሁ” አለ።'),
  ('29c9a068-5cdd-56a8-af06-1cfafa1fb60f', '82773bae-9dea-5e81-a442-3269ff73eb98', '6b5d3588-f295-5b9b-aea3-fe430c1034bb', 2, 21, 'ግያዝም ንዕማንን ተከተለው፤ ንዕማንም ዘወር ብሎ ወደ እርሱ ሲሮጥ ባየው ጊዜ ሊገናኘው ከሰረገላው ወርዶ፥ “ሁሉ ደኅና ነውን?” አለው።'),
  ('e3710c4d-7fdd-5e80-ab9d-121640cd6529', '82773bae-9dea-5e81-a442-3269ff73eb98', '6b5d3588-f295-5b9b-aea3-fe430c1034bb', 3, 22, 'እርሱም፥ “ሁሉ ደኅና ነው፦ አሁን ከነቢያት ወገን የሆኑ ሁለት ጐልማሶች ከተራራማው ከኤፍሬም ሀገር ወደ እኔ መጥተዋልና፤ አንድ መክሊት ብርና ሁለት መለወጫ ልብስ ትሰጣቸው ዘንድ እለምንሃለሁ ብሎ ጌታዬ ላከኝ” አለው።'),
  ('0a3756c2-f0c9-526c-a371-fb23562276e3', '82773bae-9dea-5e81-a442-3269ff73eb98', '6b5d3588-f295-5b9b-aea3-fe430c1034bb', 4, 23, 'ንዕማንም፥ “ሁለት የብር መክሊት ውሰድ” አለው፤ ሁለቱንም መክሊት ብር ተቀብሎ በሁለት ከረጢት ውስጥ ጨመረና ከሁለት መለወጫ ልብስ ጋር ለሁለት ሎሌዎቹ አስያዘ፤ እነርሱም ተሸክመው በፊቱ ሄዱ።'),
  ('b1b49fa1-211d-589e-a9ab-5d1bcc893703', '82773bae-9dea-5e81-a442-3269ff73eb98', '6b5d3588-f295-5b9b-aea3-fe430c1034bb', 5, 24, 'ወደ ስውር ቦታም በደረሱ ጊዜ ከእጃቸው ወስዶ በቤቱ ውስጥ አኖራቸው፤ ሰዎቹንም አሰናበተ።'),
  ('3b1d7f78-915b-5ceb-a1b6-2890428a8f21', '82773bae-9dea-5e81-a442-3269ff73eb98', '6b5d3588-f295-5b9b-aea3-fe430c1034bb', 6, 25, 'ከዚህም በኋላ ገብቶ፥ በጌታው ፊት ቆመ፤ ኤልሳዕም፥ “ግያዝ ሆይ፥ ከወዴት መጣህ?” አለው። እርሱም፥ “እኔ አገልጋይህ ወዴትም አልሄድሁም” አለ።'),
  ('2cd654cf-b85e-5fd7-a8d4-376df6088ef5', '82773bae-9dea-5e81-a442-3269ff73eb98', '6b5d3588-f295-5b9b-aea3-fe430c1034bb', 7, 26, 'እርሱም፥ “ያ ሰው ከሰረገላው ወርዶ ሊቀበልህ በተመለሰ ጊዜ ልቤ ከአንተ ጋር አልሄደምን? አሁንም ወርቁንና ልብሱን፥ ተቀብለሃል፤ ለወይን ቦታ፥ ለመሰማርያ ቦታና ለዘይት ቦታ፥ ለላሞችና ለበጎች፥ ለወንዶችና ለሴቶች ባሮች ይሁንህ።'),
  ('5ff7f32d-20f8-5a99-a535-f81dcbfd9d0d', '82773bae-9dea-5e81-a442-3269ff73eb98', '6b5d3588-f295-5b9b-aea3-fe430c1034bb', 8, 27, 'ነገር ግን የንዕማን ለምጽ በአንተና በዘርህ ላይ፥ ለዘለዓለም ይመለስ” አለው። እንደ በረዶም ለምጻም ሆኖ ከእርሱ ዘንድ ወጣ።'),
  ('9b464895-d7b6-5dee-abb9-40a277876d2e', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 1, 1, 'የነቢያትም ልጆች ኤልሳዕን፥ “እነሆ፥ በፊትህ የምናድርበት ቤት ጠብቦናል።'),
  ('6931b417-cbae-5c2f-a36f-913e9b5d93a2', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 2, 2, 'ወደ ዮርዳኖስም እንሂድ፤ ከእኛም እያንዳንዱ ከዚያ ምሰሶ ያምጣ፥ የምናድርበትም ቤት እንሥራ፥” አሉት፤ እርሱም፥ “ሂዱ” አለ።'),
  ('79bae49a-0bdd-5b9a-ac99-4c2e7739284e', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 3, 3, 'ከእነርሱም አንዱ፥ “አንተ ደግሞ ከእኛ ከአገልጋዮችህ ጋር ለመሄድ ና” አለ። ኤልሳዕም፥ “እሽ እኔም እመጣለሁ” አለ።'),
  ('c2dda263-c32b-5ba5-aacc-f32419fc5bfb', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 4, 4, 'ከእነርሱም ጋር ሄደ፤ ወደ ዮርዳኖስም በደረሱ ጊዜ እንጨት ቈረጡ።'),
  ('b50eb39c-47c9-5ad6-adc1-ce74b1d351b2', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 5, 5, 'ከእነርሱም አንዱ ዛፉን ሲቈርጥ የምሳሩ ብረት ወልቆ ወደ ውኃው ውስጥ ወደቀ፤ እርሱም፥ “ጌታዬ ሆይ፥ ወየው! ወየው! የተዋስሁት ነበር” ብሎ ጮኸ።'),
  ('05b4a6fe-5559-5b77-ab82-4ce1af6b686e', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 6, 6, 'የእግዚአብሔርም ሰው፥ “የወደቀው ወዴት ነው?” አለ፤ ስፍራውንም አሳየው፤ ከእንጨትም ቅርፊት ቀርፎ በዚያ ጣለው፤ ብረቱም ተንሳፈፈ።'),
  ('669b77c4-3e15-5658-a6f1-75401ff35b72', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 7, 7, 'እርሱም፥ “እነሆ፥ ምሳርህ ውሰደው” አለ፤ እጁንም ዘርግቶ ወሰደው።'),
  ('315a6be8-465f-502b-aebf-7448b10ba305', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 8, 8, 'የሶርያም ንጉሥ ከእስራኤል ጋር ይዋጋ ነበር፤ ከአገልጋዮቹም ጋር ተማክሮ፥ “በዚህ ስውር ቦታ ተደብቀን እናድራለን።” አላቸው።'),
  ('1a9de841-c63f-59de-aa2a-11f3d8a7f026', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 9, 9, 'ኤልሳዕም፥ “ሶርያውያን በዚያ ተደብቀዋልና በዚያ ስፍራ እንዳታልፍ ተጠንቀቅ” ብሎ ወደ እስራኤል ንጉሥ ላከ።'),
  ('646e74c3-0f18-5c01-ab43-9d449e150c4e', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 10, 10, 'የእስራኤልም ንጉሥ ኤልሳዕ ወደ ነገረው ስፍራ ላከ፤ አንድ ጊዜም ሳይሆን፥ ሁለት ጊዜም ሳይሆን በዚያ ራሱን አዳነ።'),
  ('41af14b2-a297-504f-af5b-8cff86d7184a', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 11, 11, 'የሶርያም ንጉሥ መንፈስ ስለዚህ እጅግ ተበሳጨች፤ አገልጋዮቹንም ጠርቶ፥ “ለእስራኤል ንጉሥ ማን እንደሚነግረው አትነግሩኝምን?” አላቸው።'),
  ('9d7d616d-3ce3-5799-a0ff-b6b250b3d529', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 12, 12, 'ከአገልጋዮቹም አንዱ፥ “ጌታዬ ሆይ፥ በእስራኤል ሀገር ነቢዩ ኤልሳዕ ያለ አይደለምን? በእልፍኝህ ውስጥ ሆነህ የምትናገረውንና ቃልህን ሁሉ ለእስራኤል ንጉሥ እርሱ ይነግረዋል፤” አለ።'),
  ('bf278d7b-aa7a-507f-a343-da401346669d', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 13, 13, 'እርሱም፥ “ልኬ አስይዘው ዘንድ ሄዳችሁ ወዴት እንደ ሆነ ዕወቁ፤” አለ። እነርሱም፥ “እነሆ፥ በዶታይን አለ” ብለው ነገሩት።'),
  ('b63fc3ba-4679-505f-a0a9-cf3ca13c7b66', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 14, 14, 'ወደዚያም ፈረሶችንና ሰረገሎችን ብዙም ጭፍራ ላከ፤ በሌሊትም መጥተው ከተማዪቱን ከበቡአት።'),
  ('1f8d926e-b594-54af-ae95-b8ae794c8302', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 15, 15, 'የኤልሳዕም ሎሌ ማለዳ ነቃ፤ ተነሥቶም በወጣ ጊዜ፥ እነሆ፥ በከተማዪቱ ዙሪያ ጭፍሮች ከተማዋን ከብበዋት አየ። ፈረሶችና ሰረገሎችም ነበሩ። ሎሌውም፥ “ጌታዬ ሆይ፥ ወዮ! ምን እናድርግ?” አለው።'),
  ('580fa76b-bab5-5f22-aa84-ca99b7482ff1', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 16, 16, 'እርሱም፥ “ከእኛ ጋር ያሉት ከእነርሱ ጋር ካሉት ይበልጣሉና አትፍራ” አለው።'),
  ('ae88d5c3-2431-5133-a7cb-387a44cccca2', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 17, 17, 'ኤልሳዕም፥ “አቤቱ፥ ያይ ዘንድ ዐይኖቹን፥ እባክህ፥ ግለጥ” ብሎ ጸለየ። እግዚአብሔርም የብላቴናውን ዐይኖች ገለጠ፤ እነሆም፥ የእሳት ፈረሶችና ሰረገሎች በኤልሳዕ ዙሪያ ተራራውን ሞልተውት አየ።'),
  ('231fa647-2412-531d-a680-1996079d1d6f', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 18, 18, 'ወደ እርሱም በወረዱ ጊዜ ኤልሳዕ፥ “አቤቱ፥ እነዚህን ሰዎች አሳውራቸው” ብሎ ወደ እግዚአብሔር ጸለየ። ኤልሳዕም እንደ ተናገረው ቃል አሳወራቸው።'),
  ('ae8996ac-c833-592c-ae84-d94e9c96f4a0', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 19, 19, 'ኤልሳዕም፥ “መንገዱ በዚህ አይደለም፥ ከተማዪቱም ይህች አይደለችም፤ የምትሹትን ሰው አሳያችሁ ዘንድ ተከተሉኝ” አላቸው፤ ወደ ሰማርያም ወሰዳቸው።'),
  ('32389c8b-986e-5e69-a509-392e0e7a3eb2', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 20, 20, 'ወደ ሰማርያም በገቡ ጊዜ ኤልሳዕ፥ “አቤቱ፥ ያዩ ዘንድ የእነዚህን ሰዎች ዐይኖች ግለጥ” አለ፤ እግዚአብሔርም ዐይኖቻቸውን ገለጠ፤ እነርሱም አዩ። እነሆም፥ በሰማርያ መካከል እንዳሉ ዐወቁ።'),
  ('ba412e65-d424-5842-ae34-858c1463e9c6', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 21, 21, 'የእስራኤልም ንጉሥ ባያቸው ጊዜ ኤልሳዕን፥ “አባቴ ሆይ፥ ልግደላቸውን?” አለው።'),
  ('2ead4b28-b979-5da5-a438-b91371ef1943', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 22, 22, 'እርሱም፥ “በሰይፍህና በቀስትህ የማረክሃቸውን ግደል እንጂ በሰይፍህና በቀስትህ የማረክሃቸው አይደሉምና አትግደላቸው። ይልቁንስ እንጀራና ውኃ በፊታቸው አቅርብላቸው፤ በልተውና ጠጥተውም ወደ ጌታቸው ይመለሱ” አለው።'),
  ('ef094dec-e9ee-56f5-a297-ca947c25a852', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'b6b16768-f6d6-58ac-a8d2-6cfd9be87091', 23, 23, 'ብዙም መብል አዘጋጀላቸው፤ በበሉና በጠጡ ጊዜም አሰናበታቸው፤ እነርሱም ወደ ጌታቸው ሄዱ። ከዚያም በኋላ የሶርያውያን አደጋ ጣዮች ዳግመኛ ወደ እስራኤል ሀገር አልመጡም።'),
  ('59f9a9cc-cecf-5ad2-a0c6-48cc31af1897', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'ad732a86-e43b-503c-a2f6-ea19d4fbd559', 1, 24, 'ከዚያም በኋላ የሶርያ ንጉሥ ወልደ አዴር ሠራዊቱን ሁሉ ሰበሰበ፤ ወጥቶም ሰማርያን ከበባት፤ በዚያም ተቀመጠ።'),
  ('f18d3659-0d66-53c4-ab81-e2fad3e09f39', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'ad732a86-e43b-503c-a2f6-ea19d4fbd559', 2, 25, 'በሰማርያም ታላቅ ራብ ሆኖ ነበር፤ እነሆም፥ የአህያ ራስ በኀምሳ ብር፥ የድርጎ አንድ አራተኛ የሚሆን ኵስሐ ርግብም በአምስት ብር እስኪሽጥ ድረስ ከበቡአት።'),
  ('80ffc664-ce94-5981-a3a4-1b2b2e38d412', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'ad732a86-e43b-503c-a2f6-ea19d4fbd559', 3, 26, 'የእስራኤልም ንጉሥ በቅጥር ላይ ሲመላለስ አንዲት ሴት፥ “ጌታዬ ንጉሥ ሆይ፥ ርዳኝ” ብላ ወደ እርሱ ጮኸች።'),
  ('775a3f33-4d99-5b26-a169-4819aadf76ac', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'ad732a86-e43b-503c-a2f6-ea19d4fbd559', 4, 27, 'እርሱም፥ “እግዚአብሔር ካልረዳሽ እኔ እንዴት እረዳሻለሁ? ከአውድማው ወይስ ከመጭመቂያው ነውን?” አለ።'),
  ('359bfd82-6c3e-524e-af6b-c529e5f916ab', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'ad732a86-e43b-503c-a2f6-ea19d4fbd559', 5, 28, 'ንጉሡም፥ “ምን ሆነሻል?” አላት፤ እርስዋም፥ “ይህች ሴት፦ ዛሬ እንድንበላው ልጅሽን አምጪ፤ ነገም ልጄን እንበላለን አለችኝ።'),
  ('46259a8f-98e7-5aed-a370-ddc82c704e88', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'ad732a86-e43b-503c-a2f6-ea19d4fbd559', 6, 29, 'ልጄንም ቀቅለን በላነው፤ በማግሥቱም፦ እንድንበላው ልጅሽን አምጪ አልኋት፤ ልጅዋንም ሸሸገችው” ብላ መለሰችለት።'),
  ('e5852d6e-6e6c-59f1-a446-25f9dd33afcf', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'ad732a86-e43b-503c-a2f6-ea19d4fbd559', 7, 30, 'የእስራኤልም ንጉሥ የሴቲቱን ቃል ሰምቶ ልብሱን ቀደደ፤ በቅጥርም ይመላለስ ነበር፤ ሕዝቡም በስተውስጥ በሥጋው ላይ ለብሶት የነበረውን ማቅ አዩ።'),
  ('5b644a9d-7f98-500f-ad89-51835db4ff0c', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'ad732a86-e43b-503c-a2f6-ea19d4fbd559', 8, 31, 'ንጉሡም፥ “የሣፋጥ ልጅ የኤልሳዕ ራስ ዛሬ በላዩ ያደረ እንደ ሆነ እግዚአብሔር እንዲህ ያድርገኝ እንዲህም ይግደለኝ” አለ።'),
  ('c86e01a4-b9e8-5ccc-aa26-aa644caceec1', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'ad732a86-e43b-503c-a2f6-ea19d4fbd559', 9, 32, 'ኤልሳዕ ግን በቤቱ ተቀምጦ ነበር፤ ሽማግሌዎችም ከእርሱ ጋር ተቀምጠው ነበር፤ ንጉሡም በፊቱ ከሚቆሙት አንድ ሰው ላከ፤ መልእክተኛውም ገና ሳይደርስ ለሽማግሌዎች፥ “ይህ የነፍሰ ገዳይ ልጅ ራሴን ይቈርጥ ዘንድ እንደ ላከ እዩ፤ መልእክተኛውም በመጣ ጊዜ ደጁን ዘግታችሁ ከልክሉት፤ በደጅም ይቆም ዘንድ ተዉት፤ የጌታው የእግሩ ኮቴ በኋላው ነው” አላቸው።'),
  ('3e09eba0-aaf8-51a1-a070-1293e2c82434', 'c5b8da08-22e5-5a4e-a197-363de20e23b1', 'ad732a86-e43b-503c-a2f6-ea19d4fbd559', 10, 33, 'ከእነርሱም ጋር ሲነጋገር እነሆ፥ መልእክተኛው ወደ እርሱ ደረሰ፤ እርሱም፥ “እነሆ፥ ይህ ክፉ ነገር ከእግዚአብሔር ዘንድ ነው፥ እግዚአብሔርን ገና እጠብቅ ዘንድ ምንድን ነኝ?” አለ።'),
  ('5574e148-5ba4-59f6-abc9-0fad930f876e', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 1, 1, 'ኤልሳዕም፥ “የእግዚአብሔርን ቃል ስማ፤ እግዚአብሔር እንዲህ ይላል፦ ነገ በዚህ ጊዜ በሰማርያ በር፥ ሁለት መስፈሪያ ገብስ በአንድ ሰቅል አንድ መስፈሪያ መልካም ዱቄትም በአንድ ሰቅል ይሸመታል” አለው።'),
  ('01cec49a-179e-5755-acfb-baf13360646f', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 2, 2, 'ንጉሡም በእጁ ተደግፎት የሚቆም የነበረ ያ ብላቴና ለኤልሳዕ መልሶ፥ “እነሆ፥ እግዚአብሔር በሰማይ የእህል ሿሿቴ ቢያደርግ ይህ ነገር ይሆናልን?” አለው። ኤልሳዕም፥ “እነሆ፥ በዐይኖችህ ታየዋለህ፤ ከዚያ ግን አትቀምስም” አለ።'),
  ('76df289b-0c47-565e-addc-f0d50df1890a', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 3, 3, 'በከተማዋም በር አራት ለምጻሞች ሰዎች ነበሩ፤ እርስ በርሳቸውም፥ “እስክንሞት ድረስ በዚህ ለምን እንቀመጣለን?'),
  ('b5bd32e6-2ff3-591d-a53e-9bd27476f181', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 4, 4, 'ወደ ከተማ ብንገባ ራብ በከተማ አለና፥ በዚያ እንሞታለን፤ በዚህም ብንቀመጥ እንሞታለን። እንግዲህ ኑ፥ ወደ ሶርያውያን ሰፈር እንሂድ፤ በሕይወት ቢያኖሩን እንኖራለን፤ ቢገድሉንም እንሞታለን” ተባባሉ።'),
  ('9015c86d-407f-5744-a7dc-8961449b72f7', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 5, 5, 'በጨለማም ወደ ሶርያውያን ሰፈር ይሄዱ ዘንድ ተነሡ፤ ወደ ሶርያውያንም ሰፈር መጀመሪያ ዳርቻ በመጡ ጊዜ፥ እነሆ፥ በዚያ ማንም ሰው አልነበረም።'),
  ('d92d65b4-21db-578b-a9c1-3b975b36354c', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 6, 6, 'እግዚአብሔርም ለሶርያውያን የሰረገላ ድምፅ፥ የፈረስ ድምፅና የብዙ ጭፍራ ድምፅ አሰምቶአቸዋልና፥ እርስ በርሳቸው “እነሆ፥ የእስራኤል ንጉሥ ይከቡን ዘንድ የኬጤዎናውያንንና የግብፃውያንን ነገሥት ቀጥሮ አምጥቶብናል” ይባባሉ ነበር።'),
  ('1edfc854-24b6-5f66-a437-b89924fe0fd9', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 7, 7, 'ስለዚህም ተነሥተው በጨለማ ሸሹ፤ ድንኳኖቻቸውንና ፈረሶቻቸውን፥ አህዮቻቸውንና ሰፈሩን እንዳለ ትተው ነፍሳቸውን ያድኑ ዘንድ ሸሹ።'),
  ('b8afbff4-3fcc-5408-a210-9dab6770e82a', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 8, 8, 'እነዚያም ለምጻሞች ወደ ሰፈሩ መጀመሪያ ዳርቻ በመጡ ጊዜ ወደ አንድ ድንኳን ገብተው በሉ፤ ጠጡም፤ ከዚያም ወርቅና ብር ልብስም ወሰዱ፤ ሄደውም ሸሸጉት፤ ተመልሰውም ወደ ሌላ ድንኳን ገቡ፤ ከዚያም ደግሞ ወስደው ሸሸጉ።'),
  ('020caa26-e045-55a6-aa31-1d9596742528', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 9, 9, 'ከዚያም ወዲያ እርስ በርሳቸው፥ “መልካም አላደረግንም፤ ዛሬ የመልካም ምሥራች ቀን ነው፤ እኛ ዝም ብለናል፤ እስኪነጋም ድረስ ብንቆይ በደለኞች እንሆናለን፤ ኑ፥ እንሂድ፤ ለንጉሥ ቤተሰብም እንናገር” ተባባሉ።'),
  ('d2a07ddd-5612-5c5c-ada1-b434157dd99e', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 10, 10, 'ገብተውም በከተማው በር ጮኹ፤ እንዲህም ብለው ተናገሩ፥ “ወደ ሶርያውያን ሰፈር ገባን፤ እነሆም፥ ፈረሶችና አህዮች ታስረው፥ ድንኳኖችም ተተክለው ነበር እንጂ ያገኘነው አልነበረም፤ የሰውም ድምፅ አልነበረም።”'),
  ('cb1830ae-f39a-53a2-ae47-58c2199dc404', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 11, 11, 'የደጁም ጠባቂዎች ለንጉሡ ይነግሩ ዘንድ ወደ ውስጥ ገቡ፤ ለንጉሡም ቤት አወሩ።'),
  ('d4eacb6c-9be1-5a70-ac5e-47082abed11f', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 12, 12, 'ንጉሡም በሌሊት ተነሥቶ ብላቴኖቹን፥ “ሶርያውያን ያደረጉብንን እነግራችኋለሁ፤ እንደ ተራብን ያውቃሉ፤ ስለዚህ፦ ከከተማይቱ በወጡ ጊዜ በሕይወታቸው እንይዛቸዋለን፤ ወደ ከተማም እንገባለን ብለው በሜዳ ይሸሸጉ ዘንድ ከሰፈሩ ወጥተዋል” አላቸው።'),
  ('b29145ce-93f5-578e-a85f-2f610837a9de', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 13, 13, 'ከብላቴኖቹም አንዱ መልሶ፥ “እዚህ ከቀሩት ፈረሶች አምስት ይውሰዱ፤ እነሆ፥ እነርሱ በቀሩት በእስራኤል ቍጥር ናቸው፥ እንስደድና ይዩ” አለ።'),
  ('d913f972-504f-5b40-a335-573562d0c013', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 14, 14, 'ሁለት ፈረሰኞችንም ወሰዱ፤ የእስራኤል ንጉሥም፥ “ሄዳችሁ እዩ” ብሎ የሶርያውያንን ንጉሥ ይከተሉት ዘንድ ላከ።'),
  ('38187fbd-79ac-5e8f-a530-f2c62e6f5515', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 15, 15, 'በኋላቸውም እስከ ዮርዳኖስ ድረስ ተከትለዋቸው ሄዱ፤ እነሆም፥ ሶርያውያን ሲሸሹ የጣሉት ልብስና ዕቃ መንገዱን ሁሉ ሞልቶ አገኙ። እነዚያ መልእክተኞችም ተመልሰው ለእስራኤል ንጉሥ ነገሩት።'),
  ('413c1471-92c0-5813-af0a-a68e2762d709', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 16, 16, 'ሕዝቡም ወጥቶ የሶርያውያንን ሰፈር በዘበዘ፤ እንደ እግዚአብሔርም ቃል አንድ መስፈሪያ መልካም ዱቄት በአንድ ሰቅል፥ ሁለት መስፈሪያ ገብስም በአንድ ሰቅል ተሸመተ።'),
  ('b77ae936-233d-50c7-ad0e-fd874c2a2eea', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 17, 17, 'ንጉሡም ያን እጁን ይደግፈው የነበረውን ብላቴና በሩን ይጠብቅ ዘንድ አቆመው። ሕዝቡም በበሩ ረገጠው፥ መልእክተኛው ወደ እርሱ በወረደ ጊዜ የእግዚአብሔር ሰው እንደ ተናገረውም ሞተ።'),
  ('7c1750f1-6789-5d2e-afb5-d4f8164e8054', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 18, 18, 'ኤልሳዕም ለንጉሡ፥ “ነገ በዚህ ጊዜ በሰማርያ በር ሁለት መስፈሪያ ገብስ በአንድ ሰቅል፥ አንድ መስፈሪያ መልካም ዱቄትም በአንድ ሰቅል፥ ይሸመታል” ብሎ እንደ ተናገረው ነገር እንዲሁ ሆነ።'),
  ('d25db551-b1e5-5be7-a093-b4235233a656', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 19, 19, 'ያም ሎሌ ለኤልሳዕ መልሶ፥ “እነሆ፥ እግዚአብሔር በሰማይ የእህል ሿሿቴ ቢያወርድ ይህ ነገር ይሆናልን?” ብሎ ነበር፤ ኤልሳዕም፥ “እነሆ፥ በዐይኖችህ ታየዋለህ፥ ከዚያም አትቀምስም” ብሎት ነበር።'),
  ('843360c8-dd16-5939-a3c8-010231edb83a', '9c952a95-f776-5e8f-a343-28f4a72bd0fe', '35977837-e30e-5ace-a18a-a58924de233b', 20, 20, 'እንዲሁም ሆነ፤ ሕዝቡም በበሩ ረገጠውና ሞተ።'),
  ('4275b127-fe08-5881-aecc-edc53ee9ff2a', 'b881af65-27fc-595c-af20-5faf2a7913a0', 'e2b349fb-b64b-55c8-a305-137eb38223ae', 1, 1, 'ኤልሳዕም ልጅዋን ያስነሣላትን ሴት፥ “አንቺ ከቤተ ሰብሽ ጋር ተነሥተሽ ሂጂ፤ በምታገኚውም ስፍራ ተቀመጪ፤ እግዚአብሔር በምድር ራብን ጠርቶአልና፤ ሰባት ዓመትም በምድር ላይ ይቆያል” ብሎ ተናገራት።'),
  ('ce727764-cb27-5895-aae5-c210dbe22916', 'b881af65-27fc-595c-af20-5faf2a7913a0', 'e2b349fb-b64b-55c8-a305-137eb38223ae', 2, 2, 'ሴቲቱም ተነሥታ ኤልሳዕ እንደ ነገራት አደረገች፤ ከቤተ ሰብዋም ጋር ሄዳ በፍልስጥኤም ሀገር ሰባት ዓመት ተቀመጠች።'),
  ('66465085-a7e2-5742-a77e-c938b9891626', 'b881af65-27fc-595c-af20-5faf2a7913a0', 'e2b349fb-b64b-55c8-a305-137eb38223ae', 3, 3, 'ሰባቱም ዓመት ካለፈ በኋላ ያች ሴት ከፍልስጥኤም ሀገር ተመለሰች፤ ሄዳም ስለ ቤቷና ስለ መሬቷ ልትጮህ ወደ ንጉሡ ወጣች።'),
  ('180a72d0-9b2c-5a00-a78c-49729cb7343e', 'b881af65-27fc-595c-af20-5faf2a7913a0', 'e2b349fb-b64b-55c8-a305-137eb38223ae', 4, 4, 'ንጉሡም የእግዚአብሔር ሰው የኤልሳዕ ሎሌ ግያዝን፥ “ኤልሳዕ ያደረገውን ታላላቅ ተአምራት ሁሉ ንገረኝ” እያለ ይነጋገር ነበር።'),
  ('f8b9de52-6514-5d92-a490-8a091214e968', 'b881af65-27fc-595c-af20-5faf2a7913a0', 'e2b349fb-b64b-55c8-a305-137eb38223ae', 5, 5, 'እርሱም የሞተውን ሕፃን እንደ አስነሣ ለንጉሡ ሲናገር፥ እነሆ፥ ልጅዋን ያስነሣላት ያች ሴት መጥታ ስለ ቤቷና ስለ መሬቷ ወደ ንጉሥ ጮኸች፥ ግያዝም፥ “ጌታዬ ንጉሥ ሆይ፥ ሴቲቱ ይህች ናት፤ ኤልሳዕም ያስነሣው ልጅዋ ይህ ነው፤” አለ።'),
  ('6df9d23a-3a1e-5b67-a01d-f7130cdd03ce', 'b881af65-27fc-595c-af20-5faf2a7913a0', 'e2b349fb-b64b-55c8-a305-137eb38223ae', 6, 6, 'ንጉሡም ሴቲቱን ጠየቃት፤ እርስዋም ነገረችው። ንጉሡም ከባለሟሎቹ አንዱን ሰጣት፤ “እህልዋንና ገንዘብዋን ሁሉ ሀገሩን ከተወች ጀምሮ እስከ ዛሬ ድረስ የሄደ ቦታዋን ሁሉ መልስላት” አለው።'),
  ('f93fae1f-b665-5fca-af70-ac4577d0ce18', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 1, 7, 'ኤልሳዕም ወደ ደማስቆ ሄደ፤ የሶርያም ንጉሥ ወልደ አዴር ታምሞ ነበር፤ “የእግዚአብሔር ሰው ወደዚህ መጥቶአል” ብለውም ነገሩት።'),
  ('1b076a57-3f29-55d2-ad17-f8589bfd8ab3', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 2, 8, 'ንጉሡም አዛሄልን፥ “ገጸ በረከት በእጅህ ወስደህ የእግዚአብሔርን ሰው ተቀበለው፤ ከዚህም በሽታ እድን እንደ ሆነ የእግዚአብሔርን ቃል ጠይቀው” አለው።'),
  ('9ae15819-7c52-58e0-aa52-580bb7d029f9', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 3, 9, 'አዛሄልም ሊገናኘው ሄደ፤ ከእርሱም ጋር ከደማስቆ መልካሙን ነገር ሁሉ የአርባ ግመል ጭነት ገጸ በረከት ወሰደ፤ መጥቶም በፊቱ ቆመና፥ “ልጅህ የሶርያ ንጉሥ ወልደ አዴር፦ ከዚህ በሽታ እድናለሁን? ሲል ወደ አንተ ልኮኛል” አለው።'),
  ('159dd7f1-332a-5b1f-a03f-9654848370c4', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 4, 10, 'ኤልሳዕም፥ “ሂድ፥ መዳንስ ትድናለህ በለው፤ ነገር ግን እንዲሞት እግዚአብሔር አሳይቶኛል” አለው።'),
  ('6a7439b8-5737-525c-a9d9-dac97af3af15', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 5, 11, 'እስኪያፍርም ድረስ ትኩር ብሎ ፊቱን ተመለከተው፤ የእግዚአብሔርም ሰው አለቀሰ።'),
  ('cbe56f90-be09-5c78-acc6-f70ab6446135', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 6, 12, 'አዛሄልም፥ “ጌታዬን ምን ያስለቅሰዋል?” አለ። ኤልሳዕም፥ “በእስራኤል ልጆች ላይ የምታደርገውን ክፋት ስለማውቅ ነው፤ ምሽጎቻቸውን በእሳት ታቃጥላለህ፤ ጐልማሶቻቸውንም በሰይፍ ትገድላለህ፤ ሕፃናቶቻቸውንም ትፈጠፍጣለህ፤ እርጉዞቻቸውንም ትሰነጥቃለህ፤” አለው።'),
  ('3ee54400-28a0-5260-a1a3-9daa85cdde13', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 7, 13, 'አዛሄልም፥ “ይህን ታላቅ ነገር አደርግ ዘንድ እኔ የሞተ ውሻ አገልጋይህ ምንድን ነኝ?” አለ። ኤልሳዕም፥ “አንተ በሶርያ ላይ ንጉሥ እንድትሆን እግዚአብሔር አሳይቶኛል” አለው።'),
  ('a44f5a33-3aef-5f79-a2f9-ade45658aa1d', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 8, 14, 'ከኤልሳዕም ወጥቶ ወደ ጌታው መጣ፤ እርሱም፥ “ኤልሳዕ ምን አለህ?” አለው፤ እርሱም አለው፥ “መዳንን ትድናለህ በለው አለኝ።”'),
  ('24d0d3ca-05e1-53a7-a878-834b46d0c0c0', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 9, 15, 'ከዚህም በኋላ በነጋው ለሐፍ ወስዶ በውኃ ነከረው፤ በፊቱም ላይ ሸፈነው፥ ሞተም። አዛሄልም በፋንታው ነገሠ።'),
  ('2cb6f62f-54e2-5b52-ad10-792d3345b3c5', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 10, 16, 'በእስራኤልም ንጉሥ በአክዓብ ልጅ በኢዮራም በአምስተኛው ዓመት የይሁዳ ንጉሥ የኢዮሣፍጥ ልጅ ኢዮራም በይሁዳ ነገሠ።'),
  ('f869b7a3-baac-5f5e-a820-17b31a58c700', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 11, 17, 'መንገሥም በጀመረ ጊዜ የሠላሳ ሁለት ዓመት ጐልማሳ ነበረ፥ በኢየሩሳሌምም ስምንት ዓመት ነገሠ።'),
  ('0b294525-acfa-5f51-ab4e-5ed60545f313', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 12, 18, 'የአክዓብንም ልጅ አግብቶ ነበርና የአክዓብ ቤት እንዳደረገ በእስራኤል ነገሥታት መንገድ ሄደ፤ በእግዚአብሔርም ፊት ክፉ አደረገ።'),
  ('f0b62e07-f4a0-5353-a472-a97bc6d533cb', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 13, 19, 'ነገር ግን ለእርሱና ለልጆቹ በዘመኑ ሁሉ መብራት ይሰጠው ዘንድ ተስፋ እንደ አደረገለት፥ ስለ ባሪያው ስለ ዳዊት እግዚአብሔር ይሁዳን ያጠፋ ዘንድ አልወደደም።'),
  ('342a2574-509d-553b-ab8c-28173c532598', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 14, 20, 'በእርሱም ዘመን የኤዶምያስ ሰዎች ሸፍተው የይሁዳ ሰዎችን ከዱአቸው፤ በላያቸውም ንጉሥ አነገሡ።'),
  ('46d07625-a82b-5773-a5d6-359ee6b39a89', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 15, 21, 'ኢዮራምም ከሰረገሎቹ ሁሉ ጋር ወደ ሲሆር አለፈ፤ ተነሥቶም እርሱንና የሰረገሎችን አለቆች ከብበው የነበሩትን የኤዶምያስን ሰዎች አጠፋቸው፤ ሕዝቡ ግን ወደ እየቤቱ ሸሸ።'),
  ('237f7629-c0aa-565e-acf4-8a358847fd23', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 16, 22, 'ኤዶምያስ ግን ለይሁዳ እንዳይገብር እስከ ዛሬ ድረስ በይሁዳ ላይ ሸፈተ። በዚያም ዘመን ደግሞ የሎምና ሰዎች ሸፈቱ።'),
  ('b8001c0c-ace5-5c54-a5d8-e67716b727f0', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 17, 23, 'የተረፈውም የኢዮራም ነገር ያደረገውም ሁሉ፥ በይሁዳ ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('81b085b3-b7d5-5501-ae17-2cd2fb03a81a', 'b881af65-27fc-595c-af20-5faf2a7913a0', '00e60048-dd65-5a21-ab15-d2c139cab254', 18, 24, 'ኢዮራምም ከአባቶቹ ጋር አንቀላፋ፥ በአባቱም በዳዊት ከተማ ከአባቶቹ ጋር ተቀበረ፤ በፋንታውም ልጁ አካዝያስ ነገሠ።'),
  ('63ccec6c-0ae2-589b-a2da-ecdb8e4adfe4', 'b881af65-27fc-595c-af20-5faf2a7913a0', '02ab46f5-52cc-5289-a179-8fbf7ffdc3cd', 1, 25, 'በእስራኤልም ንጉሥ በአክዓብ ልጅ በኢዮራም በዐሥራ ሁለተኛው ዓመት የይሁዳ ንጉሥ የኢዮራም ልጅ አካዝያስ ነገሠ።'),
  ('2d54df4f-9f48-5dcb-a89c-4a937dcfdd5f', 'b881af65-27fc-595c-af20-5faf2a7913a0', '02ab46f5-52cc-5289-a179-8fbf7ffdc3cd', 2, 26, 'መንገሥም በጀመረ ጊዜ አካዝያስ የሃያ ሁለት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም አንድ ዓመት ነገሠ። እናቱም ጎቶልያ የተባለች የእስራኤል ንጉሥ የዘንበሪ ልጅ ነበረች።'),
  ('490b84cb-abfd-54e5-a4db-55585cf23221', 'b881af65-27fc-595c-af20-5faf2a7913a0', '02ab46f5-52cc-5289-a179-8fbf7ffdc3cd', 3, 27, 'በአክዓብም ቤት መንገድ ሄደ፤ እንደ አክዓብም ቤት በእግዚአብሔር ፊት ክፉ አደረገ።'),
  ('55f2a938-6839-550f-a4a7-4da11b78532f', 'b881af65-27fc-595c-af20-5faf2a7913a0', '02ab46f5-52cc-5289-a179-8fbf7ffdc3cd', 4, 28, 'ከአክዓብም ልጅ ከኢዮራም ጋር የሶርያን ንጉሥ አዛሄልን በሬማት ዘገለዓድ ሊጋጠም ሄደ፤ ሶርያውያንም ኢዮራምን አቈሰሉት።'),
  ('a8cee224-0150-5270-a0fb-5c9611692bad', 'b881af65-27fc-595c-af20-5faf2a7913a0', '02ab46f5-52cc-5289-a179-8fbf7ffdc3cd', 5, 29, 'ንጉሡም ኢዮራም ከሶርያ ንጉሥ ከአዛሄል ጋር በተዋጋ ጊዜ ሶርያውያን በሬማት ያቈሰሉትን ቍስል ይታከም ዘንድ ወደ ኢይዝራኤል ተመለሰ። የአክዓብም ልጅ ኢዮራም ታምሞ ነበርና የኢዮራም ልጅ አካዝያስ ሊያየው ወደ ኢይዝራኤል ወረደ።'),
  ('395724fc-ed9d-5fed-a7ba-a325a9b5a927', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 1, 1, 'ነቢዩም ኤልሳዕ ከነቢያት ልጆች አንዱን ጠርቶ እንዲህ አለው፥ “ወገብህን ታጥቀህ ይህን የዘይት ቀንድ በእጅህ ያዝ፤ ወደ ሬማት ዘገለዓድም ሂድ።'),
  ('97714086-1656-5fed-a601-1e2854bba1c2', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 2, 2, 'በዚያም በደረስህ ጊዜ የናሜሲን ልጅ የኢዮሣፍጥን ልጅ ኢዩን ታገኘዋለህ፤ ገብተህም ከወንድሞቹ መካከል አስነሣው፤ ወደ ጓዳም አግባው።'),
  ('39d7ec2a-947f-57bd-ac79-c67ad6b156ef', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 3, 3, 'የዘይቱንም ቀንድ ይዘህ በራሱ ላይ አፍስሰውና፥ “እግዚአብሔር እንዲህ ይላል፦ በእስራኤል ላይ ንጉሥ ትሆን ዘንድ ቀባሁህ በለው፤ ከዚህም በኋላ በሩን ከፍተህ ሽሽ፥ አትዘግይም።”'),
  ('95474314-ddcd-5a44-a139-81fc9b55939c', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 4, 4, 'እንዲሁም ጐልማሳው ነቢይ ወደ ሬማት ዘገለዓድ ሄደ።'),
  ('d3c94e42-57f6-5ee0-a6f2-380f2e12c1fc', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 5, 5, 'በገባም ጊዜ፥ እነሆ፥ የሠራዊት አለቆች ተቀምጠው አገኘ፤ እርሱም፥ “አለቃ ሆይ፥ የምናገረው መልእክት አለኝ” አለ። ኢዩም፥ “ከማንኛችን ጋር ነው?” አለ። እርሱም፥ “አለቃ ሆይ፥ ከአንተ ጋር ነው” አለ።'),
  ('fd927114-9eca-5813-acb6-cb04030cb2a0', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 6, 6, 'ተነሥቶም ወደ ቤቱ ገባ፥ ዘይቱንም በራሱ ላይ አፍስሶ እንዲህ አለው፥ “የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ በእግዚአብሔር ሕዝብ በእስራኤል ላይ ንጉሥ ትሆን ዘንድ ቀባሁህ።'),
  ('e1ed86f9-a196-51db-a248-d9304438fa03', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 7, 7, 'የባሪያዎቼን የነቢያትን ደም፥ የእግዚአብሔርንም ባሪያዎች ሁሉ ደም ከኤልዛቤል እጅና ከአክዓብ ቤት ሁሉ እጅ እበቀል ዘንድ የጌታህን የአክዓብን ቤት ታጠፋለህ።'),
  ('3985a320-8b29-53df-a27f-bdd6d0964cc0', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 8, 8, 'የአክዓብን ቤት ሁሉ ታጠፋለህ፤ በእስራኤልም ዘንድ አጥር ተጠግቶ እስከሚሸን የቀረበውን ሁሉና ከእነርሱ የቀረውን ሁሉ ታጠፋለህ።'),
  ('88c21025-4e57-507d-ac78-e23a7d0cf995', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 9, 9, 'የአክዓብንም ቤት እንደ ናባጥ ልጅ እንደ ኢዮርብዓም ቤት፥ እንደ አኪያም ልጅ እንደ ባኦስ ቤት አደርገዋለሁ።'),
  ('541eb2f6-d6f4-578f-ab8d-6dc16e3d73b8', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 10, 10, 'ኤልዛቤልንም በኢይዝራኤል እርሻ ውሾች ይበሉአታል፥ የሚቀብራትም አታገኝም።” በሩንም ከፍቶ ሸሸ።'),
  ('8ee68344-0fc7-5026-a28f-99ace459367d', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 11, 11, 'ኢዩም ወደ ጌታው ብላቴኖች ወጣ፤ እነርሱም፥ “ደኅና ነውን? ይህ እብድ ለምን ወደ አንተ መጣ?” አሉት። እርሱም፥ “ሰውዬው ፌዝ እንደሚናገር አታውቁምን?” አላቸው።'),
  ('08bb26d1-296e-5308-a5c0-42abcb326f5e', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 12, 12, 'እነርሱም፥ “ዋሸኸን፤ ነገር ግን ንገረን” አሉት፤ ኢዩም፦ ለጌታው ልጆች፥ “እግዚአብሔር እንዲህ ይላል፦ በእስራኤል ላይ ንጉሥ ትሆን ዘንድ ቀባሁህ ብሎ እንዲህና እንዲህ ነገረኝ” አላቸው።'),
  ('321ea6ce-344f-54a5-acd0-9cb374ceadb0', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 13, 13, 'በሰሙም ጊዜ ሁሉም ፈጥነው ልብሳቸውን ወሰዱ፤ በሰገነቱ መውጫ እርከን ላይም ከእግሩ በታች አነጠፉት፥ መለከትም እየነፉ፥ “ኢዩ ነግሦአል” አሉ።'),
  ('0a216af2-b88b-517f-a8c2-03933ea36f46', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 14, 14, 'እንዲሁም የናሜሲ ልጅ የኢዮሣፍጥ ልጅ ኢዩ ኢዮራምን ከዳው። ኢዮራምና የእስራኤልም ልጆች ሁሉ ከሶርያ ንጉሥ ከአዛሄል የተነሣ ሬማት ዘገለዓድን ይጠብቁ ነበር።'),
  ('9c354e98-8289-51c5-a90c-ab7a42fb32cf', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 15, 15, 'ንጉሡ ኢዮራም ግን ከሶርያ ንጉሥ ከአዛሄል ጋር በተዋጋ ጊዜ ሶርያውያን ያቈሰሉትን ቍስል ይታከም ዘንድ ወደ ኢይዝራኤል ተመልሶ ነበር። ኢዩም ከእርሱ ጋር ለነበሩት እንዲህ አላቸው፥ “ከእኔ ጋር ሰውነታችሁን ለሞት መስጠት ትችላላችሁን? እንግዲህ ማንም የሚያመልጣችሁ፥ ከከተማችሁም የሚወጣ እንዳይኖርና በኢይዝራኤል እንዳያወራ ተጠንቀቁ።”'),
  ('e6ac7d09-7b9c-588a-a3c1-9b39d7aa5dfe', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 16, 16, 'የእስራኤል ንጉሥ ኢዮራምም ከሶርያ ንጉሥ ከአዛሄል ጋር በተዋጋ ጊዜ አረማውያን የሶርያ ሰዎች በሬማት ያቈሰሉትን ቍስል በኢይዝራኤል ይታከም ስለ ነበረ ኢዩ በሰረገላው ላይ ተቀምጦ ወደ ኢይዝራኤል ሄደ። ጠንካራና ኀይለኛ ሰው ነበርና፤ የይሁዳም ንጉሥ አካዝያስ ኢዮራምን ለማየት ወርዶ ነበር።'),
  ('40f92482-970f-56ea-a818-d358d1259f05', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 17, 17, 'ሰላይም ያያቸው ዘንድ በኢይዝራኤል ግንብ ላይ ቆመ፤ ሲመጡም የእነኢዩን አቧራ አየ። “እነሆም፥ አቧራ አያለሁ” አለ። ኢዮራምም፥ “ይገናኛቸው ዘንድ አንድ ፈረሰኛ ይሂድ፤ እርሱም፦ ሰላም ነውን? ይበላቸው” አለ።'),
  ('fd63eb34-182e-5910-a3e6-5a2ba50c7bc3', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 18, 18, 'ፈረሰኛውም ሊቀበላቸው ሄዶ፥ “ንጉሡ እንዲህ ይላል፦ ሰላም ነውን?” አላቸው። ኢዩም፥ “አንተ ከሰላም ጋር ምን አለህ? ወደ ኋላዬ ተመልሰህ ተከተለኝ” አለ። ሰላዩም፥ “መልእክተኛው ደረሰባቸው፥ ነገር ግን አልተመለሰም” ብሎ ነገረው።'),
  ('fcd00e6d-6801-5159-ae8b-0beaac3fd850', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 19, 19, 'ሁለተኛውንም ፈረሰኛ ሰደደ፤ ወደ እነርሱም ደርሶ ንጉሡ እንዲህ ይላል፥ “ሰላም ነውን?” አላቸው። ኢዩም፥ “አንተ ከሰላም ጋር ምን አለህ? ወደ ኋላዬ ተመልሰህ ተከተለኝ” አለ።'),
  ('8db96e95-3138-530c-a814-5b5d711f6039', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 20, 20, 'ሰላዩም፥ “መልእክተኛው ደረሰባቸው፥ ነገር ግን አልተመለሰም፤ የሚመራው ግን እንደ ናሜሲ ልጅ እንደ ኢዩ ይመራል በችኮላ ይሄዳልና” ብሎ ነገረው።'),
  ('5fd843ac-daed-53ca-ac2f-e552d5a4ec89', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 21, 21, 'ኢዮራምም፥ “ሰረገላ አዘጋጁ” አለ፤ ሰረገላውንም አዘጋጁለት። የእስራኤልም ንጉሥ ኢዮራምና የይሁዳ ንጉሥ አካዝያስ ሁለቱም በሰረገሎቻቸው ተቀምጠው ወጡ፤ ኢዩንም ሊገናኙት ሄዱ፤ በኢይዝራኤላዊውም በናቡቴ እርሻ ውስጥ አገኙት።'),
  ('18d162a7-62db-5c98-a494-3d0c2565b172', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 22, 22, 'ኢዮራምም ኢዩን ባየ ጊዜ “ኢዩ ሆይ፥ ሰላም ነውን?” አለ። እርሱም፥ “የእናትህ የኤልዛቤል ግልሙትናዋና መተቷ ሲበዛ ምን ሰላም አለ?” ብሎ መለሰ።'),
  ('35b55d90-23f0-5aea-ac60-5d2521bd7a64', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 23, 23, 'ኢዮራምም መልሶ ነዳና ሸሸ፤ አካዝያስንም፥ “አካዝያስ ሆይ፥ ዐመፅ ነው” አለው።'),
  ('8030e61c-59ee-57c9-a88e-b0611aacb5e2', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 24, 24, 'ኢዩም በእጁ ቀስቱን ለጠጠ፤ ኢዮራምንም በጫንቃው መካከል ወጋው ፤ ፍላጻውም በልቡ አለፈ፤ ወደ ሰረገላውም ውስጥ በጕልበቱ ላይ ወደቀ።'),
  ('165ee6dc-22f4-5d72-ad8a-8b592eba21c5', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 25, 25, 'ኢዩም ጋሻጃግሬውን ቢድቃርን እንዲህ አለው፥ “አንሥተህ በኢይዝራኤላዊው በናቡቴ እርሻ ጣለው፤ አንተና እኔ ጎን ለጎን በፈረስ ተቀምጠን አባቱን አክዓብን በተከተልን ጊዜ እግዚአብሔር እንዲህ ብሎ ይህን መከራ እንደ ተናገረበት እኔ አስባለሁና አንተም ታውቃለህና፤'),
  ('bb87db82-e92d-570a-aa27-38ea1966d3ec', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 26, 26, 'በእውነት የናቡቴንና የልጆቹን ደም ትናንትና አይቻለሁ፥ ይላል እግዚአብሔር፥ በዚህም እርሻ እበቀለዋለሁ፥ ይላል እግዚአብሔር። ስለዚህ እግዚአብሔር እንደ ተናገረው ቃል ወስደህ በእርሻው ውስጥ ጣለው።”'),
  ('a2a37e61-9d77-5d24-a465-5a5d72e3a03a', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 27, 27, 'የይሁዳም ንጉሥ አካዝያስ ያን ባየ ጊዜ በአትክልት ቤት መንገድ ሸሸ። ኢዩም፥ “እርሱንም ደግሞ አልተወውም” ብሎ ተከተለው። በይብላሄምም አቅራቢያ ባለችው በጋይ አቀበት በሰረገላው ላይ ወጋው። ወደ መጊዶም ሸሸ፥ በዚያም ሞተ።'),
  ('b6870f4e-a0a8-5ab1-a72a-d87008667935', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 28, 28, 'ብላቴኖቹም በሰረገላው ጭነው ወደ ኢየሩሳሌም ወሰዱት፥ በዳዊትም ከተማ በመቃብሩ ቀበሩት።'),
  ('c62b3d50-0c0b-50e7-ad16-d45f13dd9256', '53cada1e-08fa-5886-afae-04c9391c3cf0', 'a3154fb0-a40f-581d-ae1b-8b34d1c19767', 29, 29, 'በአክዓብም ልጅ በኢዮራም በዐሥራ አንደኛው ዓመት አካዝያስ በይሁዳ ላይ ነገሠ።'),
  ('4a1a9f7d-1a9f-59c6-a025-825228b7b8cd', '53cada1e-08fa-5886-afae-04c9391c3cf0', '06b187cb-3c93-531a-aa20-6352c666fcb4', 1, 30, 'ኢዩም ወደ ኢይዝራኤል ሄደ፤ ኤልዛቤልም ይህን በሰማች ጊዜ ዐይንዋን ተኳለች፤ ራስዋንም አስጌጠች፤ በመስኮትም ዘልቃ ትመለከት ነበር።'),
  ('aa4c5b59-d975-59ef-a6aa-f3305d98d333', '53cada1e-08fa-5886-afae-04c9391c3cf0', '06b187cb-3c93-531a-aa20-6352c666fcb4', 2, 31, 'ኢዩም ወደ ከተማ በገባ ጊዜ፥ “ጌታውን የገደለ ዘምሪ ሰላም ነውን?” አለችው።'),
  ('78eeb878-6fea-5188-aa5b-9e38d42126a6', '53cada1e-08fa-5886-afae-04c9391c3cf0', '06b187cb-3c93-531a-aa20-6352c666fcb4', 3, 32, 'ፊቱንም አቅንቶ በመስኮቱ አያት። “አንቺ ማን ነሽ? ወደዚህ ወደ እኔ ውረጂ” አላት። ከዚህም በኋላ ሁለት ጃንደረቦች ወደ እርሱ ተመለከቱ።'),
  ('4fca9dee-6168-5dd9-a0d2-1227350ab028', '53cada1e-08fa-5886-afae-04c9391c3cf0', '06b187cb-3c93-531a-aa20-6352c666fcb4', 4, 33, 'እርሱም፥ “ወደ ታች ወርውሩአት” አላቸው፤ ወረወሩአትም፥ ደምዋም በግንቡና በፈረሶች መግሪያ ላይ ተረጨ፥ ረገጡአትም።'),
  ('90cd6842-fd05-5c74-a132-169e781f3ba5', '53cada1e-08fa-5886-afae-04c9391c3cf0', '06b187cb-3c93-531a-aa20-6352c666fcb4', 5, 34, 'ኢዩም ገብቶ በላ፤ ጠጣም፥ ከዝያም በኋላ፥ “ሂዱ፥ ይህችን የተረገመች እዩአት፤ የንጉሥ ልጅ ናትና ቅበሩአት” አለ።'),
  ('98f310dd-1726-5a65-accc-f79f3bea3efe', '53cada1e-08fa-5886-afae-04c9391c3cf0', '06b187cb-3c93-531a-aa20-6352c666fcb4', 6, 35, 'ሊቀብሩአትም በሄዱ ጊዜ ከአናቷና ከእግርዋ ተረከዝ ከመዳፍዋም በቀር ምንም አላገኙም።'),
  ('b3a6eb73-7251-56eb-a82e-a3864a6e6b17', '53cada1e-08fa-5886-afae-04c9391c3cf0', '06b187cb-3c93-531a-aa20-6352c666fcb4', 7, 36, 'ተመልሰውም ለኢዩ ነገሩት፤ እርሱም፥ “በባሪያው በቴስብያዊው ኤልያስ እጅ በኢይዝራኤል እርሻ የኤልዛቤልን ሥጋ ውሾች ይበላሉ፥'),
  ('55da164c-b326-543f-a857-964398da68a3', '53cada1e-08fa-5886-afae-04c9391c3cf0', '06b187cb-3c93-531a-aa20-6352c666fcb4', 8, 37, 'የኤልዛቤልም ሬሳ በኢይዝራኤል እርሻ መሬት ላይ እንደ ፍግ ይሆናልና ማንም፦ ይህች ኤልዛቤል ናት ይል ዘንድ አይችልም ብሎ የተናገረው የእግዚአብሔር ቃል ይህ ነው” አለ።'),
  ('fe27fc90-1a14-5e1c-a558-b367bd7f2700', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 1, 1, 'ለአክአብም በሰማርያ ሰባ ልጆች ነበሩት፤ ኢዩም ደብዳቤ ጽፎ፥ የአክአብን ልጆች ለሚያሳድጉ፥ ለሰማርያ አለቆችና ሽማግሌዎች ወደ ሰማርያ ላከ።'),
  ('c7553558-d21c-57d1-a5dd-38bad9293409', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 2, 2, 'እንዲህም አለ፥ “ይህ ደብዳቤ አሁን በደረሳችሁ ጊዜ የጌታችሁ ልጆች ሰረገሎቹና ፈረሶቹም፥ የተመሸጉ ከተሞቹም፥ የጦር መሣሪያዎቹም በእናንተ ዘንድ አሉ፤'),
  ('a026923b-8c8d-5713-a545-be5b7699ee40', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 3, 3, 'ከጌታችሁ ልጆች ደስ የሚያሰኛችሁንና የሚሻላችሁን ምረጡ፤ በአባቱም ዙፋን አስቀምጡት፤ ስለ ጌታችሁም ቤት ተዋጉ።”'),
  ('faca733c-64d1-5646-a881-afc921b70635', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 4, 4, 'እነርሱም እጅግ ፈርተው፥ “እነሆ፥ ሁለቱ ነገሥታት በፊቱ ይቆሙ ዘንድ አልቻሉም፤ እኛስ እንዴት በፊቱ መቆም እንችላለን?” አሉ።'),
  ('d5f85543-2239-5725-aa2d-533861100d1e', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 5, 5, 'የአክአብም የቤቱ አለቆች፥ የከተማዪቱም አለቆች፥ ሽማግሌዎቹና ልጆቹንም የሚያሳድጉ፥ “እኛ አገልጋዮችህ ነን፤ ያዘዝኸንንም ሁሉ እናደርጋለን፤ የምናነግሠው ሰው የለም፤ የምትወድደውን አድርግ” ብለው ወደ ኢዩ ላኩ።'),
  ('559db1f8-4196-5d06-aaa4-84b769e03b14', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 6, 6, 'ከዚህም በኋላ ኢዩ፥ “ወገኖቼስ ከሆናችሁ፥ ነገሬንም ከሰማችሁ የጌታችሁን ልጆች ራስ ቍረጡ፤ ነገም በዚህ ሰዓት ወደ ኢይዝራኤል ወደ እኔ ይዛችሁ ኑ” ብሎ ሁለተኛ ደብዳቤ ጻፈላቸው። የንጉሡም ልጆች ሰባው ሰዎች በሚያሳድጓቸው በከተማዪቱ ታላላቆች ዘንድ ነበሩ።'),
  ('28382c43-fb1f-5429-aabd-c8f6c933bdd3', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 7, 7, 'ደብዳቤውም በደረሳቸው ጊዜ የሀገሩ ሰዎች የንጉሡን ልጆች ሰባውን ሰዎች ይዘው ገደሉአቸው፤ ራሳቸውንም በቅርጫት አድርገው ወደ እርሱ ወደ ኢይዝራኤል ላኩ።'),
  ('af94ac7e-aa04-5378-a94c-f7769feb94e4', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 8, 8, 'መልእክተኛም መጥቶ፥ “የንጉሡን ልጆች ራስ ይዘው መጥተዋል” ብሎ ነገረው። ንጉሡም፥ “እስከ ነገ ድረስ በበሩ አደባባይ ሁለት ክምር አድርጋችሁ አኑሩአቸው” አለ።'),
  ('862f0301-ebc0-593b-a245-1d3c144ab375', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 9, 9, 'በነጋውም ንጉሡ ወጥቶ ቆመ፤ ሕዝቡንም ሁሉ፥ “እናንተ ንጹሓን ናችሁ፤ እነሆ፥ የጌታዬን ቤት የወነጀልሁ የገደልኋቸውም እኔ ነኝ፤ እነዚህንስ ሁሉ የገደለ ማን ነው?'),
  ('afc55f7f-5a08-5f83-a460-302b9180f3e5', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 10, 10, 'እነሆ፥ እግዚአብሔር በአክአብ ቤት ላይ ከተናገረው ከእግዚአብሔር ቃል በምድር ላይ አንዳች እንዳይወድቅ አሁን ዕወቁ፤ እግዚአብሔር በባሪያው በኤልያስ ቃል የተናገረውን አድርጎአል” አላቸው።'),
  ('c043427d-751d-576d-ae29-0c3e0915c29e', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'c02a2e5f-348a-5316-a74a-c2913ea1cd86', 11, 11, 'ኢዩም ከአክአብ ቤት በኢይዝራኤል የቀረውን ሁሉ፥ ታላላቆቹንም ሁሉ፥ ወዳጆቹንና ካህናቱን ሁሉ ገደላቸው፤ ከእነርሱ አንድስ እንኳ አላስቀረም።'),
  ('21366bdf-52d5-561d-a709-47a4734c223f', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'a86e401c-e99d-54d0-a63c-646c661d8138', 1, 12, 'ተነሥቶም ወደ ሰማርያ ሄደ፤ በመንገድም ወዳለው ወደ በግ ጠባቂዎች ቤት በደረሰ ጊዜ፥')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('5f72f634-1231-540d-ac1a-701bfa677648', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'a86e401c-e99d-54d0-a63c-646c661d8138', 2, 13, 'ኢዩ ከይሁዳ ንጉሥ ከአካዝያስ ወንድሞች ጋር ተገናኝቶ፥ “እናንተ እነማን ናችሁ?” አለ፤ እነርሱም፥ “እኛ የይሁዳ ንጉሥ የአካዝያስ ወንድሞች ነን፤ የንጉሡንና የእቴጌዪቱን ልጆች ደኅንነት እንነግረው ዘንድ ወረድን” አሉት።'),
  ('e37b311b-850c-5c5a-ad59-97c28ad29601', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'a86e401c-e99d-54d0-a63c-646c661d8138', 3, 14, 'እርሱም፥ “በሕይወታቸው ያዙአቸው” ብሎ አዘዘ። በበግ ጠባቂዎች ቤትም አጠገብ አርባ ሁለቱን ሰዎች ገደሉአቸው፤ ከእነርሱም አንድ ሰው እንኳ አላስቀረም።'),
  ('89667df9-b130-5008-a470-070054073b29', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'a86e401c-e99d-54d0-a63c-646c661d8138', 4, 15, 'ከዚያም በሄደ ጊዜ የሬካብን ልጅ ኢዮናዳብን በመንገድ አገኘው፤ ተቀብሎም መረቀው፤ ኢዩም፥ “ልቤ ከልብህ ጋር ቅን እንደ ሆነ ያህል ልብህ ከልቤ ጋር በቅንነት ነውን?” አለው። ኢዮናዳብም፥ “አዎን” አለው። ኢዩም፥ “እውነትህስ ከሆነ እጅህን ስጠኝ” አለ። እጁንም ሰጠው፤ ወደ እርሱም ወደ ሰረገላው አወጣው።'),
  ('d0aa77d7-dfc3-5668-a9a2-6af5e9bd6b28', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'a86e401c-e99d-54d0-a63c-646c661d8138', 5, 16, '“ከእኔ ጋር ና፥ ለሠራዊት ጌታ ለእግዚአብሔርም እንደምቀና ታያለህ” አለው። ከእርሱም ጋር በሰረገላው አስቀመጠው።'),
  ('3066ef90-df58-5d82-afef-7970fb284dd1', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'a86e401c-e99d-54d0-a63c-646c661d8138', 6, 17, 'ወደ ሰማርያም ገብቶ ለኤልያስ እንደ ተናገረው እንደ እግዚአብሔር ቃል እስኪያጠፋው ድረስ በሰማርያ የቀረውን የአክአብን ሰው ገደለ።'),
  ('324fb58a-90b3-5070-a84e-e4c76a76f7d4', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 1, 18, 'ኢዩም ሕዝቡን ሁሉ ሰብስቦ፥ “አክአብ በዓልን በጥቂቱ አመለከው፤ ኢዩ ግን በብዙ ያመልከዋል።'),
  ('60eb1545-df5f-527b-ad9e-7044a77b750e', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 2, 19, 'አሁንም የበዓልን ነቢያት ሁሉ፥ አገልጋዮቹንም ሁሉ፥ ካህናቱንም ሁሉ ወደ እኔ ጥሩ፤ ማንም እንዳይቀር፤ ለበዓል ታላቅ መሥዋዕት አቀርባለሁ፤ የቀረውም ሁሉ በሕይወት አይኖርም” አላቸው። ኢዩ ግን የበዓልን አገልጋዮች ያጠፋ ዘንድ በተንኮል ይህን አደረገ።'),
  ('c4e3eef1-425e-54f0-adcd-f045ca900bdd', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 3, 20, 'ኢዩም፥ “ለበዓል መሥዋዕታችሁን አንጹ” አላቸው፤ እነርሱም አዋጅ ነገሩ።'),
  ('6954be7b-926d-54e9-a5d7-928e82cc86ce', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 4, 21, 'ኢዩም ወደ እስራኤል ሀገሮች ሁሉ ላከ፤ የበዓልም አገልጋዮች ሁሉ፥ ካህናቱም ሁሉ፥ ነቢያቶቹም ሁሉ መጡ፤ ከእነርሱም ሳይመጣ የቀረ አንድ ሰው እንኳ አልነበረም። ሁሉም ወደ በዓል ቤት ገቡ፤ የበዓልንም ቤት ከዳር እስከ ዳር ድረስ ሞሉት።'),
  ('79abfb98-7517-540e-ab77-0c4ec41e646f', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 5, 22, 'የዕቃ ቤቱንም ሹም፥ “ለበዓል አገልጋዮች ሁሉ ልብስን አውጣ” አለው። የሚያለብሳቸውንም ልብሱን አወጣላቸው።'),
  ('ceaa0970-682e-5003-ab3e-ee7748b48337', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 6, 23, 'ኢዩና የሬካብ ልጅ ኢዮናዳብም ወደ በዓል ቤት ገቡ። የበዓልንም አገልጋዮች፥ “መርምሩ፥ ከበዓል አገልጋዮች ብቻ በቀር እግዚአብሔርን ከሚያመልኩ ወገን በእናንተ ዘንድ አንድ እንኳ እንዳይኖር ተመልከቱ” አላቸው።'),
  ('9d73837f-da6d-592d-aa07-15ed94646a0e', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 7, 24, 'የሚቃጠል መሥዋዕትና ሌላ መሥዋዕትም ያቀርቡ ዘንድ ገቡ፤ ኢዩም፥ “በእጃችሁ አሳልፌ ከምሰጣችሁ ሰዎች አንድ ሰው ያመለጠ እንደ ሆነ ነፍሱ በዚያ እንዲያመልጥ ባደረገው ሰው ነፍስ ፋንታ ትሆናለች” ብሎ በውጭ ሰማንያ ሰዎችን አዘጋጅቶ ነበር።'),
  ('2c7a812a-a844-518e-abb9-b2d22bfa82b7', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 8, 25, 'የሚቃጠለውንም መሥዋዕት አቅርበው በፈጸሙ ጊዜ ኢዩ ዘበኞቹንና አለቆቹን፥ “ግቡና ግደሉአቸው፤ አንድም አያምልጥ” አላቸው። በሰይፍም ስለት ገደሉአቸው፤ ዘበኞችና አለቆችም ወደ ውጭ ጣሉአቸው፤ ወደ በዓልም ቤት ከተማ ሄዱ።'),
  ('79eb8576-5874-53c0-ab0f-5ba3987d1d37', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 9, 26, 'ከበዓልም ቤት ሐውልቶቹን አወጡ፤ አቃጠሉአቸውም።'),
  ('698a494f-68c8-5551-a817-11e73c9f3d95', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 10, 27, 'የበዓልን ሐውልት ቀጠቀጡ፤ የበዓልንም ቤት አፈረሱ፤ እስከ ዛሬም ድረስ የውዳቂ መጣያ አደረጉት።'),
  ('d3a4d136-08fe-5c1c-ac29-33973a485974', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 11, 28, 'እንዲሁም ኢዩ በዓልን ከእስራኤል አጠፋ።'),
  ('56c76e1f-615b-5c7d-abd3-510871bc922e', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 12, 29, 'ነገር ግን እስራኤልን ካሳተው ከናባጥ ልጅ ከኢዮርብዓም ኀጢአት ኢዩ አልራቀም፥ በቤቴልና በዳን የነበሩትን የወርቅ እንቦሶችንም፥ አላስወገደም።'),
  ('09d03d53-5192-5df5-a2c8-fb17a240a40d', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 13, 30, 'እግዚአብሔርም ኢዩን፥ “በፊቴ ቅን ነገር አድርገሃልና፥ በልቤም ያለውን ሁሉ በአክአብ ቤት ላይ አድርገሃልና ልጆችህ እስከ አራት ትውልድ ድረስ በእስራኤል ዙፋን ላይ ይቀመጣሉ” አለው።'),
  ('c78136ad-10f8-5c69-ae76-683c0aaf0614', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 14, 31, 'ኢዩ ግን በእስራኤል አምላክ በእግዚአብሔር ሕግ በፍጹም ልቡ ይሄድ ዘንድ አልተጠነቀቀም፤ እስራኤልንም ካሳተው ከኢዮርብዓም ኀጢአት አልራቀም።'),
  ('0e6e93e7-bf05-56b7-a5ec-54ca8e7042c9', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 15, 32, 'በዚያም ወራት እዚአብሔር እስራኤልን ያጠፋ ጀመረ፤ አዛሄልም በእስራኤል ዳርቻ ሁሉ መታቸው።'),
  ('e976a306-f09f-5469-a6f4-06ce888de2f6', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 16, 33, 'በዮርዳኖስ ምሥራቅ ያለውን የገለዓድን ሀገር ሁሉ፥ በአርኖን ወንዝ አጠገብ ካለችው ከአሮዔር ጀምሮ የጋድንና የሮቤልን የምናሴንም ሀገር፥ ገለዓድንና ባሳንን መታ።'),
  ('d8c45d43-c3c2-563e-a623-9e11fbc78380', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 17, 34, 'የቀረውም የኢዩ ነገር፥ የሠራውም ሥራ ሁሉ፥ ኀይሉም ሁሉ፥ የገደለውም ሁሉ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('78af1358-c0f1-5898-acb8-14dc1fad744b', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 18, 35, 'ኢዩም ከአባቶቹ ጋር አንቀላፋ፤ በሰማርያም ቀበሩት። በፋንታውም ልጁ ኢዩአካዝ ነገሠ።'),
  ('e775d0ed-a8a9-5aaa-aaaf-6b0fdfbadd18', 'e4757038-fa9b-582b-aae9-40877cb8505e', 'd059a57d-b137-55e8-a4ed-dcd7e7062035', 19, 36, 'ኢዩም በሰማርያ በእስራኤል ላይ የነገሠበት ዘመን ሃያ ስምንት ዓመት ነበረ።'),
  ('d40c1864-e8fb-511e-adc8-6b0009fe1a9c', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 1, 1, 'የአካዝያስም እናት ጎቶልያ ልጅዋ እንደ ሞተ ባየች ጊዜ ተነሥታ የመንግሥትን ዘር ሁሉ አጠፋች።'),
  ('94c09be7-3ca5-5472-a0eb-db13060c8419', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 2, 2, 'የንጉሡ የኢዮራም ልጅ የአካዝያስ እኅት ኢዮሳቡሄም የአካዝያስን ልጅ ኢዮአስን ከተገደሉት ከንጉሡ ልጆች መካከል ሰርቃ ወሰደችው፤ እርሱንና ሞግዚቱንም ወደ እልፍኝ ወሰደች፤ ከጎቶልያም ሸሸገችው፤ አልገደሉትምም።'),
  ('3f9eeb6f-95e3-5cdc-a8a3-a66e21160672', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 3, 3, 'በእግዚአብሔርም ቤት ስድስት ዓመት ሸሸገችው። ጎቶልያም በሀገሩ ላይ ነገሠች።'),
  ('4b2c094b-855d-5d43-ad92-7f2cf904274f', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 4, 4, 'በሰባተኛውም ዓመት ዮዳሄ ልኮ፥ በኮራውያንና በዘበኞች ላይ ያሉትን የመቶ አለቆች ወሰደ፤ ወደ እግዚአብሔርም ቤት አገባቸው፤ ከእነርሱም ጋር የእግዚአብሔርን ቃል ኪዳን አደረገ፤ በእግዚአብሔርም ቤት አማላቸው፤ የንጉሡንም ልጅ አሳያቸው።'),
  ('5eae4d5e-9801-5238-a135-a61e1781bdb0', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 5, 5, 'እንዲህም ብሎ አዘዛቸው፥ “እንዲህ አድርጉ፤ በሰንበት ቀን ከምትገቡት ከእናንተ ከሦስት አንዱ እጅ በበር ተቀምጣችሁ የንጉሡን ቤት ዘብ ጠብቁ፤'),
  ('67d83f95-d98d-58a1-a3b7-0764a6dda7f4', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 6, 6, 'ሌላውም ከሦስት አንዱ እጅ በሰፊው መንገድ በበሩ በኩል ተቀመጡ፤ ሦስተኛውም እጅ ከዘበኞች ቤት በኋላ ባለው በር ሁኑ፤ ቤቱንም አጽንታችሁ ጠብቁ፤'),
  ('1eda040a-5e48-5b2c-a5be-4ce9020fdb7e', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 7, 7, 'ከእናንተም በሰንበት ቀን የምትወጡት ሁለቱ እጅ ንጉሥ ያለበትን የእግዚአብሔርን ቤት ጠብቁ።'),
  ('e4623a13-a995-521d-a5e2-33fd63c8a366', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 8, 8, 'ንጉሡንም በዙሪያው ክበቡት፤ የጦር ዕቃችሁም በእጃችሁ ይሁን፤ በሰልፋችሁም መካከል የሚገባ ይገደል፤ ንጉሡም በወጣና በገባ ጊዜ ከእርሱ ጋር ሁኑ።”'),
  ('ba6f2cd5-2541-55f3-ac15-954bea51f735', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 9, 9, 'መቶ አለቆችም ብልሁ ዮዳሄ ያዘዛቸውን ሁሉ አደረጉ፤ ከእነርሱም እያንዳንዱ በሰንበት ይገቡ የነበሩትን፥ በሰንበትም ይወጡ የነበሩትን ሰዎች ይዘው ወደ ካህኑ ወደ ዮዳሄ መጡ።'),
  ('1db58f91-c0bb-51bf-a826-47627f6e9176', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 10, 10, 'ዮዳሄም በእግዚአብሔር ቤት የነበረውን የንጉሡን የዳዊትን ሰይፍና ጦር ሁሉ ለመቶ አለቆች ሰጣቸው።'),
  ('e50a263a-c43e-553f-a987-e31e170f4f1f', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 11, 11, 'ዘበኞቹም ሁሉ እያንዳንዳቸው የጦር ዕቃቸውን በእጃቸው ይዘው በንጉሡ ዙሪያ ከቤቱ ቀኝ እስከ ቤቱ ግራ ድረስ በመሠዊያውና በቤቱ አጠገብ ቆሙ።'),
  ('7e6032bf-b483-5186-a687-bca9bfcf057e', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 12, 12, 'የንጉሡንም ልጅ አውጥቶ ዘውዱን ጫነበት፤ ምስክሩንም ሰጠው፤ ቀብቶም አነገሠው፥ “ንጉሡ ሺህ ዓመት ይንገሥ” እያሉ በእጃቸው አጨበጨቡ።'),
  ('f17df058-655f-5c01-ac3d-3bc363579238', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 13, 13, 'ጎቶልያም ሲሮጡ የሕዝቡን ድምፅ በሰማች ጊዜ ወደ ሕዝቡ ወደ እግዚአብሔር ቤት ገባች።'),
  ('68d31554-0742-5106-a197-cf197de3fa74', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 14, 14, 'እነሆም፥ ንጉሡን እንደ ተለመደው በዓምዱ አጠገብ ቆሞ፥ ከንጉሡም ጋር መዘምራንና መለከተኞች ቆመው አየች፤ የሀገሩም ሕዝብ ሁሉ ደስ ብሎአቸው መለከት ይነፉ ነበር። ጎቶልያም ልብስዋን ቀድዳ፥ “ዐመፅ ነው፥ ዐመፅ ነው፥” ብላ ጮኸች።'),
  ('e73e7228-83c3-5533-af60-4c25b39f1cb6', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 15, 15, 'ካህኑም ዮዳሄ በጭፍራው ላይ የተሾሙትን የመቶ አለቆች፥ “ወደ ሰልፉ መካከል አውጡአት፤ የሚከተላትንም በሰይፍ ግደሉት” ብሎ አዘዛቸው፤ ካህኑ፥ “በእግዚአብሔር ቤት አትገደል” ብሎአልና።'),
  ('ea54246d-c8aa-5061-a693-e1d963458336', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', 'd89e2251-dbdf-5865-a936-db1136a4e45b', 16, 16, 'እርስዋንም ይዘው በንጉሡ ቤት አጠገብ ወደ አለ ወደ ፈረሶች መግቢያ መንገድ ወሰዱአት፤ በዚያም ገደሉአት።'),
  ('1afeff1e-7aba-5e99-ad12-d756ba5697c5', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', '79f477a3-e9af-5c58-a75a-01545685e7a2', 1, 17, 'ዮዳሄም የእግዚአብሔር ሕዝብ ይሆኑ ዘንድ በእግዚአብሔርና በንጉሡ፥ በሕዝቡም መካከል ቃል ኪዳን አደረገ፤ ደግሞም በንጉሡና በሕዝቡ መካከል ቃል ኪዳን አደረገ።'),
  ('bbb9ff2a-cc2e-5e48-a8b0-39856a862d6f', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', '79f477a3-e9af-5c58-a75a-01545685e7a2', 2, 18, 'የሀገሩም ሕዝብ ሁሉ ወደ በዓል ቤት ሄደው ሰበሩት፤ መሠዊያዎቹንም አፈረሱ፤ ምስሎቹንም አደቀቁ፥ የበዓልንም ካህን ማታንን በመሠዊያው ፊት ገደሉት። ካህኑ ዮዳሄም ለእግዚአብሔር ቤት ጠባቂዎችን ሾመ።'),
  ('d0f0d958-db18-5522-ad52-220b51138eba', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', '79f477a3-e9af-5c58-a75a-01545685e7a2', 3, 19, 'መቶ አለቆቹንና ኮራውያንን፥ ዘበኞችንና የሀገሩንም ሕዝብ ሁሉ ወሰዳቸው፤ ንጉሡንም ከእግዚአብሔር ቤት አወጣው፤ በዘበኞችም በር መንገድ ወደ ንጉሡ ቤት አመጡት፤ በነገሥታቱም ዙፋን አስቀመጡት።'),
  ('20e3de7f-1494-51fb-a8f3-be7ea8477ab3', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', '79f477a3-e9af-5c58-a75a-01545685e7a2', 4, 20, 'የሀገሩም ሕዝብ ደስ አላቸው፤ ከተማዪቱም ፀጥ አለች። ጎቶልያንም በንጉሡ ቤት አጠገብ በሰይፍ ገደሉአት።'),
  ('291c9be5-800b-5005-a1d1-b8b952a49fe4', 'da16e091-e0d5-5cfa-aaa9-20deefa8f342', '79f477a3-e9af-5c58-a75a-01545685e7a2', 5, 21, 'ኢዮአስም መንገሥ በጀመረ ጊዜ የሰባት ዓመት ልጅ ነበረ።'),
  ('d3f8fb32-ebe3-5935-afeb-b860cbeead18', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 1, 1, 'ኢዩ በነገሠ በሰባተኛው ዓመት ኢዮአስ ነገሠ፤ በኢየሩሳሌምም አርባ ዓመት ነገሠ፤ እናቱም ሳቢያ የተባለች የቤርሳቤህ ሴት ነበረች።'),
  ('575174aa-8dd4-578f-a55f-e210276d45e8', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 2, 2, 'ካህኑ ዮዳሄ ያስተምረው በነበረ ዘመን ሁሉ ኢዮአስ በእግዚአብሔር ፊት ቅን ነገር አደረገ።'),
  ('3270e292-41db-5e1f-a1cf-6b6365f3250a', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 3, 3, 'ነገር ግን በኮረብቶቹ ላይ ያሉ የጣዖት መስገጃዎችን አላስወገደም፤ ሕዝቡም ገና በኮረብቶቹ ላይ ባሉት የጣዖት መስገጃዎች ይሠዋና ያጥን ነበር።'),
  ('616ae78f-e7af-54f9-a11e-2de59a875dc5', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 4, 4, 'ኢዮአስም ካህናቱን፥ “ወደ እግዚአብሔር ቤት የሚገባውን የተቀደሰውን ገንዘብ ሁሉ፥ ስለ ነፍሱም ዋጋ የሚያቀርበውን ገንዘብ፥ በልባቸውም ፈቃድ ወደ እግዚአብሔር ቤት የሚያመጡትን ገንዘብ ሁሉና፥'),
  ('1a30b221-ea9d-539c-a435-c4624f2938d4', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 5, 5, 'እያንዳንዱ ሰው ከሚያመጣው ካህናቱ ለራሳቸው ይውሰዱ፤ በመቅደስም ውስጥ የተናዱትን ይጠግኑበት” አላቸው።'),
  ('bfbc09a2-dc79-5327-a0dc-5fc0cfebec2f', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 6, 6, 'ነገር ግን እስከ ንጉሡ እስከ ኢዮአስ እስከ ሃያ ሦስተኛው ዓመት ድረስ ከመቅደሱ ውስጥ የተናዱትን ካህናቱ አልጠገኑትም ነበር።'),
  ('28de53f1-1c52-5fee-a054-95bb80693db0', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 7, 7, 'ኢዮአስም ካህኑን ዮዳሄንና ካህናቱን ጠርቶ፥ “በመቅደሱ ውስጥ የተናዱትን ስፍራዎች ስለ ምን አልጠገናችሁም? ከእንግዲህ ወዲያ ገንዘቡ ለቤቱ መጠገኛ ይሰጥ እንጂ ከሚያመጡት ሰዎች አትቀበሉ” አላቸው።'),
  ('06f8c0ba-1f60-5b79-a4b0-d93ab2461624', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 8, 8, 'ካህናቱም “ከሕዝቡ ገንዘቡን አንወስድም፤ በቤቱም ውስጥ የተናዱትን አንጠግንም፥” ብለው ተስማሙ።'),
  ('95cb090f-46b8-5a42-ad93-5b4f6de5fa10', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 9, 9, 'ካህኑ ዮዳሄ ግን አንድ ሣጥን ወስዶ መክደኛውን ነደለው፤ በመሠዊያውም አጠገብ ሰው ወደ እግዚአብሔር ቤት በሚገባበት መግቢያ በስተቀኝ አኖረው፤ ደጁንም የሚጠብቁ ካህናት ወደ እግዚአብሔር ቤት የሚመጣውን ገንዘብ ሁሉ በሚዛን አስገቡ።'),
  ('825a8769-6510-5a1f-a556-46877ac06a0d', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 10, 10, 'በሣጥኑም ውስጥ የተገኘው ወርቅ ብዙ እንደ ሆነ ባዩ ጊዜ የንጉሡ ጸሓፊና የካህናቱ አለቃ ይመጡ ነበር፤ በእግዚአብሔርም ቤት የተገኘውን ገንዘብ ሁሉ ቈጥረው በከረጢት ውስጥ ያኖሩት ነበር።'),
  ('d2ba7044-cb03-5937-a47d-e021dab3a8af', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 11, 11, 'የተሰበሰበውንም ገንዘብ ሥራውን በሚሠሩና የእግዚአብሔርን ቤት በሚጠብቁት እጅ ይሰጡ ነበር። እነርሱም የእግዚአብሔርን ቤት ለሚሠሩ ግንበኞችና አናጢዎች ይሰጡ ነበር።'),
  ('034a577f-0997-5aa7-a828-801ce87ebab4', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 12, 12, 'የተናደውን የእግዚአብሔርን ቤት ለመጠገን መክፈል ለሚያሻው ሁሉ ድንጋይንና እንጨትን ይገዙ ዘንድ፥ ለግንበኞችና ለድንጋይ ወቃሪዎች ይሰጡት ነበር።'),
  ('cd33cf76-894b-5c92-a9ed-08096a4e67b1', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 13, 13, 'ነገር ግን ወደ እግዚአብሔር ቤት ከሚመጣው ገንዘብ ለእግዚአብሔር ቤት የሚሆኑ የብር መዝጊያዎች፥ ጽዋዎችና ጕጠቶች፥ ድስቶችም፥ መለከቶችም፥ የወርቅና የብር ዕቃዎችም አልተሠሩም ነበር።'),
  ('b8a6d6bf-8e48-59b9-a439-0994d5fa8240', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 14, 14, 'ነገር ግን ለሚሠሩት ይሰጡት ነበር፤ የእግዚአብሔርንም ቤት ጠገኑበት።'),
  ('5efc1ade-b016-539d-ab77-f06197618297', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 15, 15, 'ለሠራተኞችም ይከፍሉ ዘንድ ገንዘቡን የሚወስዱትን ሰዎች አይቈጣጠሩአቸውም ነበር፤ በታማኝነት ይሠሩ ነበርና።'),
  ('a1d16323-65ca-55c3-ae03-80de5be1180f', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 16, 16, 'ስለ በደልና ስለ ኀጢአት መሥዋዕት ወደ እግዚአብሔር ቤት የሚያመጡት ገንዘብም ለካህናት ነበር።'),
  ('73cb648e-dd0c-5650-ad1f-2cc832c9a254', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 17, 17, 'በዚያም ወራት የሶርያ ንጉሥ አዛሄል ዘመተ፤ ጌትንም ወግቶ ያዛት፤ አዛሄልም ወደ ኢየሩሳሌም ለመውጣት ፊቱን አቀና።'),
  ('ce41f8fa-4523-5c30-af5a-a7047ed9d961', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 18, 18, 'የይሁዳም ንጉሥ ኢዮአስ አባቶቹ የይሁዳ ነገሥታት ኢዮሣፍጥና ኢዮራም፥ አካዝያስም የቀደሱትን ቅዱስ ነገር፥ እርሱም የቀደሰውን፥ በእግዚአብሔርም ቤትና በንጉሡም ቤተ መዛግብት የተገኘውን ወርቅ ሁሉ ወሰደ፤ ወደ ሶርያም ንጉሥ ወደ አዛሄል ላከው። እርሱም ከኢየሩሳሌም ተመለሰ።'),
  ('b86603e6-e985-524c-a9ec-bbd077a82147', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 19, 19, 'የቀረውም የኢዮአስ ነገር፥ የሠራውም ሥራ ሁሉ፥ እነሆ፥ በይሁዳ ነገሥታት ታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('715fea8d-cc1d-503c-a561-d0cc628270a0', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 20, 20, 'አገልጋዮቹም ተነሥተው ዐመፁበት፥ ወደ ሲላ በሚወርደውም መንገድ በመሀሎ ቤት ኢዮአስን ገደሉት።'),
  ('11378f06-bdfd-5697-ab1c-d5ca748b25e5', '95bd18d7-b0b0-54a2-ad67-d78f57199580', 'd12f286b-651f-53d0-a40e-87dcbf5b167e', 21, 21, 'አገልጋዮቹም የኢያሙሃት ልጅ ኢያዜክርና የሳሜር ልጅ ኢያዛብድ መቱት፤ ሞተም፤ በዳዊትም ከተማ ከአባቶቹ ጋር ቀበሩት፤ ልጁም አሜስያስ በፋንታው ነገሠ።'),
  ('f762b4d8-950d-544f-a7c6-27d14383e468', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 1, 1, 'በይሁዳ ንጉሥ በአካዝያስ ልጅ በኢዮአስ በሃያ ሦስተኛው ዓመት የኢዩ ልጅ ኢዮአካዝ በሰማርያ ነገሠ፤ ዐሥራ ሰባት ዓመትም ነገሠ።'),
  ('8824ae28-857e-53a0-ac37-02cf6f91588c', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 2, 2, 'በእግዚአብሔርም ፊት ክፉ ነገር አደረገ፤ እስራኤልንም ያሳተውን የናባጥን ልጅ የኢዮርብዓምን ኀጢአት ተከተለ፤ ከእርስዋም አልራቀም።'),
  ('002c975c-f6d8-5f3c-a56e-0d5d3c8b0457', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 3, 3, 'እግዚአብሔርም በእስራኤል ላይ በጣም ተቈጣ፤ በዘመኑም ሁሉ በሶርያው ንጉሥ በአዛሄል እጅ፥ በአዛሄልም ልጅ በወልደ አዴር እጅ አሳልፎ ሰጣቸው።'),
  ('180bbdf3-a38e-56fb-a18e-7f0a68afbf80', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 4, 4, 'ኢዮአካዝም እግዚአብሔርን ለመነ፤ እግዚአብሔርም የሶርያ ንጉሥ እስራኤልን ያስጨነቀበትን ጭንቀት አይቶአልና ሰማው።'),
  ('a26cd302-f124-541c-a995-241830d57f07', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 5, 5, 'እግዚአብሔርም ለእስራኤል ታዳጊን ሰጠ፤ ከሶርያውያንም እጅ ዳኑ፤ የእስራኤልም ልጆች እንደ ቀድሞው ጊዜ በድንኳናቸው ተቀመጡ።'),
  ('b0c67c52-49ce-5e3c-aaf8-1e0a5c66bcad', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 6, 6, 'ነገር ግን በእርስዋ ሄዱ እንጂ እስራኤልን ካሳተበት ከኢዮርብዓም ቤት ኀጢአት አልራቁም፤ ደግሞም የማምለኪያ ዐፀድ በሰማርያ ቆሞ ነበረ።'),
  ('31f67ce5-9991-5618-ab72-ef314169b5ab', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 7, 7, 'ለኢዮአካዝም ከኀምሳ ፈረሰኞች፥ ከዐሥርም ሰረገሎች፥ ከዐሥር ሺህም እግረኞች በቀር ሕዝብ አልቀረለትም፤ የሶርያ ንጉሥ አጥፍቶአቸዋልና፥ በአውድማም እንዳለ ዕብቅ አድቅቆአቸዋልና።'),
  ('d8416d71-1b23-511d-a62e-f3f9911a1f47', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 8, 8, 'የቀረውም የኢዮአካዝ ነገር፥ ያደረገውም ሁሉ፥ ኀይሉም፥ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('43402705-2cc2-5fd3-a9b8-91e9dcfa2ee6', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 9, 9, 'ኢዮአካዝም ከአባቶቹ ጋር አንቀላፋ፥ በሰማርያም ቀበሩት፥ ልጁም ዮአስ በፋንታው ነገሠ።'),
  ('97dfa550-4792-5151-a6f7-c3bc1e13a7e5', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 10, 10, 'በይሁዳ ንጉሥ በኢዮአስ በሠላሳ ሰባተኛው ዓመት የኢዮአካዝ ልጅ ዮአስ በእስራኤል ላይ በሰማርያ ዐሥራ ስድስት ዓመት ነገሠ።'),
  ('3f57a23d-ab37-5216-a787-7c7c7a0ff223', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 11, 11, 'በእግዚአብሔርም ፊት ክፉ ነገር አደረገ፤ እስራኤልን ካሳተው ከናባጥ ልጅ ከኢዮርብዓም ኀጢአት አልራቀም፤ ነገር ግን በእርስዋ ሄደ።'),
  ('f4e25b31-8e8a-52b8-a069-437589ae671c', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 12, 12, 'የቀረውም የዮአስ ነገር፥ ያደረገውም ሁሉ፥ ከይሁዳም ንጉሥ ከአሜስያስ ጋር የተዋጋበት ኀይሉ፥ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('f2959d4b-45f4-5d0c-aedc-803a55fa92a5', 'e3c30602-5443-5109-a3b2-900fc531f006', '26edb049-6bc5-5bb5-ac33-f77b72e03fbf', 13, 13, 'ዮአስም ከአባቶቹ ጋር አንቀላፋ፤ ኢዮርብዓምም በዙፋኑ ላይ ተቀመጠ፤ ዮአስም በሰማርያ ከእስራኤል ነገሥታት ጋር ተቀበረ።'),
  ('7004d26d-5688-59d1-ae7d-5ce7646f57b0', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 1, 14, 'ኤልሳዕም በሚሞትበት በሽታ ታመመ፤ የእስራኤልም ንጉሥ ዮአስ ወደ እርሱ ወርዶ በፊቱ አለቀሰና፥ “አባቴ ሆይ፥ አባቴ ሆይ፥ የእስራኤል ሰረገላቸውና ፈረሰኛቸው” አለ።'),
  ('af18aab3-8212-54a2-a2d4-35d7c098768e', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 2, 15, 'ኤልሳዕም፥ “ቀስትህንና ፍላጻዎችህን ውሰድ” አለው፤ ቀስቱንና ፍላጻዎቹንም ወሰደ።'),
  ('ecb24fd7-7d37-55f7-a8e4-a271dbc01879', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 3, 16, 'የእስራኤልንም ንጉሥ አለው፥ “እጅህን በቀስቱ ላይ ጫን።” ዮአስም እጁን በቀስቱ ላይ ጫነ፤ ኤልሳዕም እጁን በንጉሡ እጅ ላይ ጫነ፦'),
  ('f3ae88ef-688f-5644-adfe-35091764db9c', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 4, 17, '“የምሥራቁንም መስኮት ክፈት” አለ፤ ከፈተውም። ኤልሳዕም፥ “ወርውር” አለው፤ ወረወረውም እርሱም፥ “የእግዚአብሔር መድኀኒት ፍላጻ ነው፤ ከሶርያ የመዳን ፍላጻ ነው፤ እስክታጠፋቸውም ድረስ ሶርያውያንን በአፌቅ ትመታለህ” አለ።'),
  ('af9f910c-2243-5095-af1b-26c1ab730bf0', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 5, 18, 'ኤልሳዕም ደግሞ፥ “ፍላጻዎችህን ውሰድ” አለው ወሰዳቸውም። የእስራኤልንም ንጉሥ፥ “ምድሩን ምታው” አለው። ንጉሡም ሦስት ጊዜ መትቶ ቆመ።'),
  ('60d96d73-950e-5449-a130-4d1dc0e200ae', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 6, 19, 'የእግዚአብሔርም ሰው አዝኖ፥ “አምስት ወይም ስድስት ጊዜ መትተኸው ቢሆን ኖሮ ሶርያውያንን እስክታጠፋቸው ድረስ በመታኻቸው ነበር፤ አሁን ግን ሦስት ጊዜ ብቻ ሶርያን ትመታለህ” አለ።'),
  ('e1c8d05e-9ace-5568-af58-82aaf20fac71', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 7, 20, 'ኤልሳዕም ሞተ፤ ቀበሩትም። ከሞዓብም አደጋ ጣዮች በየዓመቱ መጀመሪያ ወደ ሀገሩ ይገቡ ነበር።'),
  ('e8ea0b80-f4a7-52a4-aa14-93610a1e7788', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 8, 21, 'ሰዎችም አንድ ሰው ሲቀብሩ አደጋ ጣዮችን አዩ፤ ሬሳውንም በኤልሳዕ መቃብር ላይ ጣሉት፤ የኤልሳዕንም አጥንት በነካ ጊዜ ሰውዬው ድኖ በእግሩ ቆመ።'),
  ('9adf04ba-d6ee-522a-a1d0-946553091af6', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 9, 22, 'አዛሄልም በኢዮአካዝ ዘመን ሁሉ እስራኤልን አስጨነቀ፤'),
  ('a762c4a5-2518-5d33-a234-6ec1a38a8f4b', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 10, 23, 'እግዚአብሔር ግን ራራላቸው፤ ማራቸውም፤ ከአብርሃምና ከይስሐቅ፥ ከያዕቆብም ጋር ስላደረገው ቃል ኪዳን እነርሱን ተመለከተ፤ ሊያጠፋቸውም አልወደደም፤ ፈጽሞም ከፊቱ አልጣላቸውም።'),
  ('d3645f94-2577-5c61-a6ba-43d1fea5daf4', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 11, 24, 'የሶርያም ንጉሥ አዛሄል ሞተ፤ ልጁም ወልደ አዴር በፋንታው ነገሠ።'),
  ('1090f983-d859-5f98-ac3a-543638a2fb8f', 'e3c30602-5443-5109-a3b2-900fc531f006', 'e07335e9-5d7c-546f-afb1-dc330d5cc823', 12, 25, 'አዛሄልም ከአባቱ ከኢዮአካዝ እጅ በሰልፍ የወሰዳቸውን ከተሞች የኢዮአካዝ ልጅ ዮአስ መልሶ ከአዛሄል ልጅ ከወልደ አዴር እጅ ወሰደ። ዮአስም ሦስት ጊዜ መታው፤ የእስራኤልንም ከተሞች መለሰ።'),
  ('d371fdaa-c9cc-52c5-a084-3e00d0b864b8', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 1, 1, 'በእስራኤል ንጉሥ በኢዮአካዝ ልጅ በዮአስ በሁለተኛው ዓመት የይሁዳ ንጉሥ የኢዮአስ ልጅ አሜስያስ ነገሠ።'),
  ('0c80963e-60a1-5757-ae35-a59822f4d546', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 2, 2, 'መንገሥም በጀመረ ጊዜ ዕድሜው ሃያ አምስት ዓመት ነበረ፤ በኢየሩሳሌምም ሃያ ዘጠኝ ዓመት ነገሠ። እናቱም ዮአድም የተባለች የኢየሩሳሌም ሴት ነበረች።'),
  ('6b67b2e5-2170-5a12-ae7a-6b84af8623b8', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 3, 3, 'በእግዚአብሔርም ፊት ቅን ነገር አደረገ፤ ነገር ግን አባቱ ኢዮአስ እንዳደረገ ሁሉ እንጂ እንደ አባቱ እንደ ዳዊት አላደረገም።'),
  ('8c72625d-6525-5083-a9c3-6fc3856fd5c2', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 4, 4, 'ነገር ግን በኮረብቶቹ ላይ ያሉትን መስገጃዎች አላስወገደም፤ ሕዝቡም ገና በኮረብቶቹ ላይ ባሉት መስገጃዎች ይሠዋና ያጥን ነበር።'),
  ('96574c31-1eae-5734-a00f-d9250e2ce233', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 5, 5, 'መንግሥቱም በእጁ በጸናለት ጊዜ አባቱን የገደሉትን አገልጋዮች ገደለ።'),
  ('52bd1fc3-6065-5897-a872-9d768e62ae1f', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 6, 6, 'በሙሴ ሕግ መጽሐፍም እንደ ተጻፈ፥ እግዚአብሔርም፥ “ሁሉ በኀጢአቱ ይሙት እንጂ አባቶች ስለ ልጆች አይሙቱ፤ ልጆችም ስለ አባቶች አይሙቱ” ብሎ እንዳዘዘ የነፍሰ ገዳዮቹን ልጆች አልገደላቸውም።'),
  ('8743e8e5-05aa-5ec7-abcd-0930cb58b734', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 7, 7, 'እርሱም በጨው ሸለቆ ከኤዶምያስ ዐሥር ሺህ ሰው ገደለ፤ ሴላንም በጦርነት ወስዶ ስምዋን እስከ ዛሬ ድረስ “ዮቅትኤል” ብሎ ጠራት።'),
  ('b1e19c35-94c9-50e5-a366-5d4b35e9b692', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 8, 8, 'በዚያን ጊዜም አሜስያስ፥ “ና እርስ በርሳችን ፊት ለፊት እንተያይ” ብሎ ወደ እስራኤል ንጉሥ ወደ ኢዩ ልጅ ወደ ኢዮአካዝ ልጅ ወደ ዮአስ መልእክተኞችን ላከ።'),
  ('0b9a9626-4525-58c6-a43a-530c2221d7e2', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 9, 9, 'የእስራኤልም ንጉሥ ዮአስ፥ “የሊባኖስ ኵርንችት፦ ልጅህን ለልጄ ሚስት አድርገህ ስጠው ብሎ ወደ ሊባኖስ ዝግባ ላከ፤ የሊባኖስም አውሬ አልፎ ኵርንችቱን ረገጠ።'),
  ('52c57305-a560-5b17-acdf-275de7333899', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 10, 10, 'ኤዶምያስን በእውነት መታህ፤ ልብህንም ከፍ ከፍ አደረግህ፤ በዚያ ተመካ፤ በቤትህም ተቀመጥ፤ አንተ፥ ይሁዳም ከአንተ ጋር ትወድቁ ዘንድ ስለ ምን መከራን ትሻለህ?” ብሎ ወደ ይሁዳ ንጉሥ ወደ አሜስያስ ላከ።'),
  ('d509f355-8f30-5380-a6c3-faaeb55d1c6c', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 11, 11, 'አሜስያስ ግን አልሰማም፤ የእስራኤልም ንጉሥ ዮአስ ዘመተ፤ እርሱና የይሁዳ ንጉሥ አሜስያስም በይሁዳ ባለች በቤትሳሚስ ፊት ለፊት ተያዩ።'),
  ('db3c7f74-595e-5434-ad55-f3ff92fd2c20', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 12, 12, 'ይሁዳም በእስራኤል ፊት ተመታ፤ እያንዳንዱም ወደ ድንኳኑ ሸሸ።'),
  ('cd143eff-af0a-554f-aeae-0df428ba5de0', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 13, 13, 'የእስራኤልም ንጉሥ ዮአስ የይሁዳን ንጉሥ የአካዝያስን ልጅ የኢዮአስን ልጅ አሜስያስን በቤትሳሚስ ይዞ ወደ ኢየሩሳሌም መጣ፤ የኢየሩሳሌምንም ቅጥር ከኤፍሬም በር ጀምሮ እስከ ማዕዘኑ በር ድረስ አራት መቶ ክንድ አፈረሰ።'),
  ('450d74be-2455-51fa-ac50-dbc0f6142566', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 14, 14, 'ወርቁንና ብሩን ሁሉ፥ በእግዚአብሔርም ቤትና በንጉሥ ቤተ መዛግብት የነበሩትን ዕቃዎች ሁሉ፤ በመያዣም የተያዙትን ልጆች ወስዶ ወደ ሰማርያ ተመለሰ።'),
  ('a1291109-1e02-595f-a061-cad02833c6b3', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 15, 15, 'የቀረውም ያደረገው የዮአስ ነገር፥ ኀይሉም፥ ከይሁዳም ንጉሥ ከአሜስያስ ጋር እንደ ተዋጋ፥ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('56a4c09c-2b8b-5f2c-a68d-e81ef300a8bf', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 16, 16, 'ዮአስም ከአባቶቹ ጋር አንቀላፋ፤ በሰማርያም ከእስራኤል ነገሥታት ጋር ተቀበረ፤ ልጁም ኢዮርብዓም በፋንታው ነገሠ።'),
  ('c037c394-b9a8-5352-a505-55ed586a568a', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 17, 17, 'የይሁዳ ንጉሥ የኢዮአስ ልጅ አሜስያስ ከእስራኤል ንጉሥ ከኢዮአካዝ ልጅ ከዮአስ ሞት በኋላ ዐሥራ አምስት ዓመት ኖረ።'),
  ('d6d6311b-58bb-5a0d-a526-2697549e9fc1', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 18, 18, 'የቀረውም የአሜስያስ ነገር፥ ያደረገውም ሁሉ፥ እነሆ፥ በይሁዳ ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('418802e1-d0ab-5bdc-adfa-24a6176d6df7', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 19, 19, 'በኢየሩሳሌምም የዐመፅ መሐላ አደረጉበት፤ እርሱም ወደ ለኪሶ ኮበለለ፤ ወደ ለኪሶም ተከተሉት፤ በዚያም ገደሉት።'),
  ('81b4fbfe-d28e-5a64-ae9a-2247991270fa', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 20, 20, 'በድኑንም በፈረስ ጭነው አመጡት፤ በኢየሩሳሌምም በዳዊት ከተማ ከአባቶቹ ጋር ቀበሩት።'),
  ('ee9e84a5-e8b4-5552-a377-9c2660be3f1d', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 21, 21, 'የይሁዳም ሕዝብ ሁሉ የዐሥራ ስድስት ዓመት ልጅ የነበረውን ዓዛርያስን ወስደው በአባቱ በአሜስያስ ፋንታ አነገሡት።'),
  ('6e132daf-eb41-5c99-a827-0788eb3c452f', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'b65f86ae-6507-575f-a7e7-3996d33d2c27', 22, 22, 'ንጉሡም ከአባቶቹ ጋር ከአንቀላፋ በኋላ፥ ኤላትን ሠርቶ ወደ ይሁዳ መለሳት።'),
  ('89b1e68f-e049-5106-a244-1fd19ce8c5e9', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'cd0b0056-8064-54a0-ae3f-72e362f4af85', 1, 23, 'በይሁዳ ንጉሥ በኢዮአስ ልጅ በአሜስያስ በዐሥራ አምስተኛው ዓመተ መንግሥት የእስራኤል ንጉሥ የዮአስ ልጅ ኢዮርብዓም በሰማርያ መንገሥ ጀመረ፤ አርባ አንድ ዓመትም ነገሠ።'),
  ('724af270-3c00-5a75-a973-6b4fecdd49b7', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'cd0b0056-8064-54a0-ae3f-72e362f4af85', 2, 24, 'በእግዚአብሔርም ፊት ክፉ ነገር አደረገ እስራኤልንም ካሳታቸው ከናባጥ ልጅ ከኢዮርብዓም ኀጢአት ሁሉ አልራቀም።'),
  ('86e333c4-e17b-59fd-ad12-9fadeb47dfef', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'cd0b0056-8064-54a0-ae3f-72e362f4af85', 3, 25, 'በጋትሔፌር በነበረው በአማቴ ልጅ በባሪያው በነቢዩ በዮናስ አፍ እንደ ተናገረው እንደ እስራኤል አምላክ እንደ እግዚአብሔር ቃል የእስራኤልን ድንበር ከሔማት መግቢያ ጀምሮ እስከ ዓረባ ባሕር ድረስ መለሰ።'),
  ('ab0703d3-a7e8-50d9-a1ea-86b267d101e8', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'cd0b0056-8064-54a0-ae3f-72e362f4af85', 4, 26, 'በቍጥር እንዳነሱ፥ የታሰረውና የተለቀቀውም እንደ ጠፋ፥ እስራኤልንም የሚረዳ እንዳልነበረ እግዚአብሔር እጅግ የመረረውን የእስራኤልን ጭንቀት አየ።'),
  ('d41c88ae-3fc6-504e-a0aa-56b0a8c424a4', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'cd0b0056-8064-54a0-ae3f-72e362f4af85', 5, 27, 'እግዚአብሔርም የእስራኤልን ዘር ከሰማይ በታች ይደመስስ ዘንድ አልተናገረም፤ ነገር ግን በዮአስ ልጅ በኢዮርብዓም እጅ አዳናቸው።'),
  ('330b855d-cb21-5e9c-aa0e-6d711176db66', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'cd0b0056-8064-54a0-ae3f-72e362f4af85', 6, 28, 'የቀረውም የኢዮርብዓም ነገር፥ ያደረገውም ሁሉ፥ ኀይሉም፥ የይሁዳ የነበረውን ደማስቆንና ሔማትን ለእስራኤል እንደ መለሰ፥ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('e734b209-0419-55e9-a233-b62dabc17e8c', '8079e1a8-2776-5100-a1b7-d90f2e571521', 'cd0b0056-8064-54a0-ae3f-72e362f4af85', 7, 29, 'ኢዮርብዓምም እንደ አባቶቹ እንደ እስራኤል ነገሥታት አንቀላፋ፤ ልጁም ዘካርያስ በፋንታው ነገሠ።'),
  ('3faac0dc-a37a-590d-a8b0-a87ab29016d2', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 1, 1, 'በእስራኤልም ንጉሥ በኢዮርብዓም በሃያ ሰባተኛው ዓመት የይሁዳ ንጉሥ የአሜስያስ ልጅ ዓዛርያስ ነገሠ።'),
  ('4c03dd06-e9ac-51d4-a108-53a6c6c2fe41', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 2, 2, 'ዓዛርያስም መንገሥ በጀመረ ጊዜ የዐሥራ ስድስት ዓመት ልጅ ነበረ፤ በኢየሩሳሌምም አምሳ ሁለት ዓመት ነገሠ፤ እናቱም ኮልያ የተባለች የኢየሩሳሌም ሴት ነበረች።'),
  ('524b48d1-d9ed-5eb7-a03f-81300e8e91d9', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 3, 3, 'አባቱ አሜስያስ እንዳደረገው ሁሉ በእግዚአብሔር ፊት ቅን ነገር አደረገ።'),
  ('ebf9bba9-a376-508e-a6da-e0db29c43d31', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 4, 4, 'ነገር ግን በኮረብቶች ላይ የነበሩትን መስገጃዎች አላስወገደም፤ ሕዝቡም ገና በኮረብቶች ላይ በነበሩት መስገጃዎች ይሠዋና ያጥን ነበር።'),
  ('d1ad693e-f432-58ed-a0d9-4f5d0e85a17b', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 5, 5, 'እግዚአብሔርም ንጉሡን በደዌ ዳሰሰው፤ እስከሚሞትበትም ቀን ለምጻም ሆነ፤ በተለየ ቤትም ይቀመጥ ነበር፤ የንጉሡም ልጅ ኢዮአታም በንጉሡ ቤት ላይ ሠልጥኖ ለሀገሩ ሕዝብ ይፈርድ ነበር።'),
  ('2e31134f-31e6-5bfe-a3a9-f04f18c36ddc', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 6, 6, 'የቀረውም የዓዛርያስ ነገር፥ የሠራውም ሥራ ሁሉ፥ እነሆ፥ በይሁዳ ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('fecccd29-f989-5c78-a47c-43dbdcf4991d', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 7, 7, 'ዓዛርያስም እንደ አባቶቹ አንቀላፋ፥ በዳዊትም ከተማ ከአባቶቹ ጋር ቀበሩት፤ ልጁም ኢዮአታም በእርሱ ፋንታ ነገሠ።'),
  ('aa409ebf-86b4-5781-a496-957bba7285f4', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 8, 8, 'በይሁዳም ንጉሥ በዓዛርያስ በሠላሳ ስምንተኛው ዓመት የኢዮርብዓም ልጅ ዘካርያስ በእስራኤል ላይ በሰማርያ ስድስት ወር ነገሠ።'),
  ('2f8bb4f9-2d34-5d06-af47-c187f2a48f44', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 9, 9, 'አባቶቹም እንዳደረጉት በእግዚአብሔር ፊት ክፉ ነገር አደረገ፤ እስራኤልንም ካሳታቸው ከናባጥ ልጅ ከኢዮርብዓም ኀጢአት አልራቀም።'),
  ('ea5bdbc8-6ff0-5cd0-a6d5-cbb2ab575093', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 10, 10, 'የኢያቢስም ልጅ ሴሎም፤ ሌሎችም ከዱት፤ በይብልዓም መትተው ገደሉት፤ በእርሱም ፋንታ ሴሎም ነገሠ።'),
  ('27779a89-59ad-592a-aa9d-d0c735ac9dbf', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 11, 11, 'የቀረውም የዘካርያስ ነገር፥ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('39ad30ce-5c60-5ff7-a211-3c2ca8988647', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 12, 12, 'ለኢዩ፥ “ልጆችህ እስከ አራት ትውልድ ድረስ በእስራኤል ዙፋን ላይ ይቀመጣሉ” ተብሎ የተነገረው የእግዚአብሔር ቃል ይህ ነበረ፤ እንዲሁም ሆነ።'),
  ('45013ce7-f7de-5d68-a44a-52cf59bac486', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 13, 13, 'በይሁዳም ንጉሥ በዓዛርያስ በሠላሳ ዘጠነኛው ዓመት የኢያቢስ ልጅ ሴሎም ነገሠ፤ በሰማርያም አንድ ወር ነገሠ።'),
  ('e718b039-26e9-5e0d-a2ad-45948d38091f', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 14, 14, 'የጋዲም ልጅ ምናሔም ከቴርሳላቅ ወጥቶ ወደ ሰማርያ ሄደ፤ በሰማርያም የኢያቢስን ልጅ ሴሎምን መታ፤ ገደለውም፤ በእርሱም ፋንታ ነገሠ።'),
  ('f8ac63a2-be47-5eb5-a0d4-6b97cba5a498', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 15, 15, 'የቀረውም የሴሎም ነገር፥ የተማማለውም ዐመፅ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሓፍ የተጻፈ አይደለምን?'),
  ('835695fc-8e64-55e4-a82b-47187c40a409', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 16, 16, 'በዚያ ጊዜም ምናሔም ቴርሳን፥ በእርስዋም ያሉትን ሁሉ፥ ዳርቻዋንም መታ፤ ይከፍቱለትም ዘንድ አልወደዱምና መታት፤ በእርስዋም የነበሩትን እርጉዞች ሁሉ ሰነጠቃቸው።'),
  ('5790e3f9-7fc9-5a32-a852-d89dadf5a045', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 17, 17, 'በይሁዳ ንጉሥ በዓዛርያስ በሠላሳ ዘጠነኛው ዓመት የጋዲ ልጅ ምናሔም በእስራኤል ላይ በሰማርያ ዐሥር ዓመት ነገሠ።'),
  ('c26f87aa-bd96-510a-aab1-7d6ec622d204', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 18, 18, 'በእግዚአብሔርም ፊት ክፉ ነገርን አደረገ፤ እስራኤልን ካሳተው ከናባጥ ልጅ ከኢዮርብዓም ኀጢአትም አልራቀም።'),
  ('02c0d991-3f13-55a1-a765-7b06b6391639', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 19, 19, 'በዘመኑም የአሶር ንጉሥ ፎሐ በምድሪቱ ላይ ወጣ፤ ምናሔምም የፎሐ እጅ ከእርሱ ጋር እንዲሆን አንድ ሺህ መክሊት ብር ሰጠው።'),
  ('22145814-96dc-53c9-a982-23184684a01c', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 20, 20, 'ምናሔምም ብሩን ለአሶር ንጉሥ ይሰጥ ዘንድ በእስራኤል ባለጠጎች ሁሉ ላይ በእያንዳንዱ ላይ አምሳ ሰቅል ብር አስገብሮ አወጣ። የአሶርም ንጉሥ ተመለሰ፤ በሀገሪቱም አልተቀመጠም።'),
  ('562c6a44-d64f-53a0-a96d-fc5ec52bc8f7', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 21, 21, 'የቀረውም የምናሔም ነገር፥ የሠራውም ሥራ ሁሉ፥ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('49b33591-1e5a-5047-a337-6f47945c4ca6', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 22, 22, 'ምናሔምም እንደ አባቶቹ አንቀላፋ፤ ልጁም ፋቂስያስ በእርሱ ፋንታ ነገሠ።'),
  ('2eaff96a-7638-587d-a77c-d9d542050a3e', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 23, 23, 'በይሁዳም ንጉሥ በዓዛርያስ በአምሳኛው ዓመት የምናሔም ልጅ ፋቂስያስ በእስራኤል ላይ በሰማርያ መንገሥ ጀመረ፤ ሁለት ዓመትም ነገሠ።'),
  ('7c18a1d1-7d42-54bc-a4d4-fb2b2592c074', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 24, 24, 'በእግዚአብሔርም ፊት ክፉ ነገር አደረገ፤ እስራኤልን ካሳተው ከናባጥ ልጅ ከኢዮርብዓም ኀጢአትም አልራቀም።'),
  ('0d97dae0-e801-5dcb-a710-5fd412107935', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 25, 25, 'የሠራዊቱም አለቃ የሮሜልዩ ልጅ ፋቁሔ ከዳው፤ በሰማርያም በንጉሡ ቤት ግንብ ውስጥ ከአርጎብና ከአርያ ጋር መታው፤ ከእርሱም ጋር ከገለዓዳውያን አምሳ ሰዎች ነበሩ፤ ገደለውም፤ በእርሱም ፋንታ ነገሠ።'),
  ('aee0b59f-7d5e-57ff-a1d3-91db8f2ebec7', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 26, 26, 'የቀረውም የፋቂስያስ ነገር፥ የሠራውም ሥራ ሁሉ፥ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('113a4165-2d17-5dbd-a758-47edf8c0a652', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 27, 27, 'በይሁዳ ንጉሥ በዓዛርያስ በአምሳ ሁለተኛው ዓመት የሮሜልዩ ልጅ ፋቁሔ በእስራኤል ላይ በሰማርያ መንገሥ ጀመረ፤ ሃያ ዓመትም ነገሠ።'),
  ('796aedcb-49a6-519c-aa61-2491846654fb', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 28, 28, 'በእግዚአብሔርም ፊት ክፉ ነገርን አደረገ፤ እስራኤልን ካሳተው ከናባጥ ልጅ ከኢዮርብዓም ኀጢአትም አልራቀም።'),
  ('89b8b48c-6ac9-55ff-a1bc-ad0d88c55128', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 29, 29, 'በእስራኤልም ንጉሥ በፋቁሔ ዘመን የአሶር ንጉሥ ቴልጌልቴልፌልሶር መጣ፤ ኢዮንና አቤልቤትመዓካን፥ ያኖዋንም፥ ቃዴስንና አሶርንም፥ ገለዓድንና ገሊላንም፥ የንፍታሌምንም ሀገር ሁሉ ወሰደ፤ ወደ አሶርም አፈለሳቸው።'),
  ('975796bb-8dc7-5e2b-af16-41ffafffdfb6', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 30, 30, 'በዖዝያንም ልጅ በኢዮአታም በሃያኛው ዓመት የኤላ ልጅ ሆሴዕ በሮሜልዮ ልጅ በፋቁሔ ላይ ዐመፀበት፤ መትቶም ገደለው፤ በእርሱም ፋንታ ነገሠ።'),
  ('46e66488-d992-5a11-a146-ce1a01a7b190', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 31, 31, 'የቀረውም የፋቁሔ ነገር፥ የሠራውም ሥራ ሁሉ፥ እነሆ፥ በእስራኤል ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('0a2b7255-7d74-5090-a871-5133a51aa764', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 32, 32, 'በእስራኤል ንጉሥ በሮሜልዩ ልጅ በፋቁሔ በሁለተኛው ዓመተ መንግሥት የይሁዳ ንጉሥ የዓዛርያስ ልጅ ኢዮአታም ነገሠ።'),
  ('29c13c07-8b08-5a44-ac96-c31ee71bd49b', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 33, 33, 'መንገሥ በጀመረ ጊዜ ሃያ አምስት ዓመት ሆኖት ነበረ፤ በኢየሩሳሌምም ዐሥራ ስድስት ዓመት ነገሠ፤ እናቱም የሳዶቅ ልጅ ኢየሩሳ ነበረች።'),
  ('f587475b-7c41-5b33-a531-34f83c3f622c', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 34, 34, 'በእግዚአብሔርም ፊት ቅን ነገር አደረገ፤ አባቱ ዓዛርያስ እንዳደረገው ሁሉ እንዲሁ አደረገ።'),
  ('830b4709-8411-5939-ae0d-9e1f84c04c83', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 35, 35, 'ነገር ግን የጣዖታቱን ቤት አላስወገደም፤ ሕዝቡም ገና በኮረብቶች ላይ ይሠዉና ያጥኑ ነበር። እርሱም የላይኛውን የእግዚአብሔርን ቤት በር ሠራ።'),
  ('70a68c5c-30df-5407-a8bd-456666de8cc7', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 36, 36, 'የቀረውም የኢዮአታም ነገር፥ የሠራውም ሥራ ሁሉ፥ እነሆ፥ በይሁዳ ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('5858489c-468d-5478-a548-577566205718', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 37, 37, 'በዚያም ወራት እግዚአብሔር የሶርያን ንጉሥ ረአሶንንና የሮሜልዩን ልጅ ፋቁሔን በይሁዳ ላይ መላክ ጀመረ።'),
  ('62b05791-a36e-5813-a01b-d23ea175cc6d', '43dbea70-a7aa-535f-a763-6f6e4cb3dbda', '5741dc55-19e1-5538-a86a-fb97fc7d44c4', 38, 38, 'ኢዮአታምም እንደ አባቶቹ አንቀላፋ፥ በአባቱም በዳዊት ከተማ ከአባቶቹ ጋር ተቀበረ፤ ልጁም አካዝ በእርሱ ፋንታ ነገሠ።'),
  ('dbb2c764-b828-59a7-ac1a-3237f10c31fd', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 1, 1, 'በሮሜልዩ ልጅ በፋቁሔ በዐሥራ ሰባተኛው ዓመት የይሁዳ ንጉሥ የኢዮአታም ልጅ አካዝ ነገሠ።'),
  ('d2de5cda-ff8a-58f2-a2d8-0626e116b439', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 2, 2, 'አካዝ መንገሥ በጀመረ ጊዜ የሃያ ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ዐሥራ ስድስት ዓመት ነገሠ፤ እንደ አባቱም እንደ ዳዊት በአምላኩ በእግዚአብሔር ፊት በታማኝነት ቅን ነገርን አላደረገም።'),
  ('038f5afc-d142-5f74-acb7-af796035d9d7', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 3, 3, 'ነገር ግን በእስራኤል ነገሥታት መንገድ ሄደ፤ ደግሞም እግዚአብሔር ከእስራኤል ልጆች ፊት እንዳሳደዳቸው እንደ አሕዛብ ርኵሰት ልጁን በእሳት ሠዋው።'),
  ('66289c23-3052-57ad-afa4-bc1a19a78e1c', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 4, 4, 'በመስገጃዎቹና በኮረብቶቹ ላይ በለመለመውም ዛፍ ሁሉ በታች ይሠዋና ያጥን ነበር።'),
  ('78fc57d1-69eb-5e6f-a16b-384132d66da3', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 5, 5, 'ያን ጊዜም የሶርያ ንጉሥ ረአሶንና የእስራኤል ንጉሥ የሮሜልዩ ልጅ ፋቁሔ ሊዋጉ ወደ ኢየሩሳሌም ወጡ፤ አካዝንም ከበቡት፥ ሊያሸንፉት ግን አልቻሉም።'),
  ('128ae4ce-a6a6-5d4d-a335-7d4fe7c2bde8', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 6, 6, 'በዚያም ዘመን የሶርያ ንጉሥ ረአሶን ኤላትን ወደ ሶርያ መለሰላቸው፥ አይሁድንም ከኤላት አሳደደ፤ ኤዶማውያንም ወደ ኤላት መጥተው እስከ ዛሬ ድረስ በዚያ ይኖራሉ።'),
  ('0f8c21aa-2b89-5abc-a3fd-313ec49a4c47', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 7, 7, 'አካዝም፥ “እኔ ባሪያህና ልጅህ ነኝ፤ መጥተህ ከተነሡብኝ ከሶርያ ንጉሥና ከእስራኤል ንጉሥ እጅ አድነኝ” ብሎ ወደ አሦር ንጉሥ ወደ ቴልጌልቴልፌልሶር መልእክተኞችን ላከ።'),
  ('295905dc-b3fb-50d7-a226-998f79dcd327', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 8, 8, 'አካዝም በእግዚአብሔር ቤትና በንጉሡ ቤተ መዛግብት የተገኘውን ብርና ወርቅ ወስዶ ወደ አሦር ንጉሥ ገጸ በረከት አድርጎ ሰደደው።'),
  ('41779d12-f258-50e3-af5a-28448ac445e7', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 9, 9, 'የአሦርም ንጉሥ ሰማው፤ የአሦርም ንጉሥ ወደ ደማስቆ ወጣ፤ ያዛትም፤ ሕዝብዋንም ወደ ቂር አፈለሳቸው፤ ረአሶንንም ገደለው።'),
  ('7caf2d80-af4f-590d-a554-bbea4471fe21', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 10, 10, 'የይሁዳ ንጉሥ አካዝም የአሦርን ንጉሥ ቴልጌልቴልፌልሶርን ሊገናኘው ወደ ደማስቆ ሄደ፤ በደማስቆ የነበረውንም መሠዊያ አየ፤ ንጉሡም አካዝ የመሠዊያውን ምሳሌና የአሠራሩን መልክ ወደ ካህኑ ወደ ኦርያ ላከው።'),
  ('32a70dbd-e73b-5533-a812-7df6cdc6adb8', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 11, 11, 'ካህኑም ኦርያ ንጉሡ አካዝ ከደማስቆ እንደ ላከለት መሠዊያውን ሁሉ ሠራ፤ እንዲሁም ካህኑ ኦርያ ንጉሡ አካዝ ከደማስቆ እስኪመጣ ድረስ ሠራው።'),
  ('b441f2cf-27bc-5835-aad0-c05fbf5f4405', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 12, 12, 'ንጉሡም ከደማስቆ በመጣ ጊዜ መሠዊያውን አየ፤ ንጉሡም ወደ መሠዊያው ወጣ።'),
  ('b7b2d760-d8da-5d17-a1bb-310b73a84b92', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 13, 13, 'የሚቃጠለውን መሥዋዕትና የእህሉንም ቍርባን አሳረገ፤ የመጠጡንም ቍርባን አፈሰሰ፤ የደኅንነቱንም መሥዋዕት ደም በመሠዊያው ላይ ረጨ።'),
  ('9d96d0d1-e39e-56bf-a617-07cb7984a185', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 14, 14, 'በእግዚአብሔርም ፊት የነበረውን የናሱን መሠዊያ ከእግዚአብሔር ቤት ፊት ከመሠዊያውና ከእግዚአብሔር ቤት መካከል ፈቀቅ አድርጎ በመሠዊያው አጠገብ በሰሜን በኩል አኖረው።'),
  ('c6296045-4d13-5d6f-a24e-b3accf8740a2', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 15, 15, 'ንጉሡም አካዝ፥ “የሚቃጠለውን የጥዋት መሥዋዕት፥ የማታውንም የእህሉን ቍርባን፥ የንጉሡንም መሥዋዕትና የእህሉን ቍርባን፥ የሕዝቡንም ሁሉ የሚቃጠለውን መሥዋዕትና የእህሉን፥ የመጠጡንም ቍርባን በታላቁ መሠዊያ ላይ አቅርብ፤ የሚቃጠለውንም መሥዋዕት ደም ሁሉ፥ የሌላውንም መሥዋዕታቸውን ደም ሁሉ በእርሱ ላይ ርጭበት፤ የናሱ መሠዊያ ግን በየጥዋቱ ለእኔ ይሁን” ብሎ ካህኑን ኦርያን አዘዘው።'),
  ('51504d4c-ab47-5d88-ab18-71ff7ecf5b02', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 16, 16, 'ካህኑ ኦርያም ንጉሡ አካዝ እንዳዘዘው ሁሉ እንዲሁ አደረገ።'),
  ('aa7f9d8f-a7ff-586f-ab46-61c25d0f790b', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 17, 17, 'ንጉሡ አካዝም የመቀመጫዎችን ክፈፍ ቈረጠ፤ ከእነርሱም የመታጠቢያውን ሰኖች ወሰደ፤ ኵሬውንም ከበታቹ ከነበሩት ከናሱ በሬዎች አወረደው፤ በጠፍጣፋውም ድንጋይ ላይ አኖረው።'),
  ('1532ad49-f22b-55c2-a48e-68383f4c0d78', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 18, 18, 'በእግዚአብሔርም ቤት የዙፋኑን መሠረት ሠራ፤ ስለ አሦርም ንጉሥ በውጭ ያለውን የንጉሡን መግቢያ ወደ እግዚአብሔር ቤት አዞረው።'),
  ('6710f081-f185-537d-a4d1-eba04814e0f5', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 19, 19, 'የቀረውም አካዝ ያደረገው ነገር እነሆ፥ በይሁዳ ነገሥታት የታሪክ መጽሐፍ የተጻፈ አይደለምን?'),
  ('631ef084-f909-556a-a60b-f0100f1b0b25', '19608ec9-251d-595c-a0e1-2a33a8b14e19', '26f63371-bf75-5cc9-a931-b603d1ba9aa4', 20, 20, 'አካዝም እንደ አባቶቹ አንቀላፋ፥ በዳዊትም ከተማ ተቀበረ፤ ልጁም ሕዝቅያስ በእርሱ ፋንታ ነገሠ።'),
  ('37ab0d8f-c9c5-5e14-af94-33011012ac8e', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2d3bfdfa-5847-58d9-a557-76312bdd6f95', 1, 1, 'የይሁዳ ንጉሥ አካዝ በነገሠ በዐሥራ ሁለተኛው ዓመት የኤላ ልጅ ሆሴዕ በእስራኤል ላይ በሰማርያ ዘጠኝ ዓመት ነገሠ።'),
  ('9dcc2dd5-bce3-580a-a111-8d7eed869ce5', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2d3bfdfa-5847-58d9-a557-76312bdd6f95', 2, 2, 'በእግዚአብሔርም ፊት ክፉ ነገር አደረገ፤ ነገር ግን ከእርሱ አስቀድሞ እንደ ነበሩት እንደ እስራኤል ነገሥታት አልሆነም።'),
  ('fa24bf24-6dca-587d-a437-d0f9261dd58a', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2d3bfdfa-5847-58d9-a557-76312bdd6f95', 3, 3, 'የአሦርም ንጉሥ ስልምናሶር በእርሱ ላይ ዘመተ፤ ሆሴዕም ተገዛለት፤ ግብርም አመጣለት።'),
  ('47953f0e-8275-5251-a2a7-820d5aac8a7f', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2d3bfdfa-5847-58d9-a557-76312bdd6f95', 4, 4, 'የአሦርም ንጉሥ በሆሴዕ ላይ ዐመፅ አገኘ፤ መልእክተኞችን ወደ ግብፅ ንጉሥ ወደ ሴጎር ልኮ ነበርና፤ እንደ ልማዱም በየዓመቱ ለአሦር ንጉሥ ግብር አልሰጠምና፤ ስለዚህ የአሦር ንጉሥ ተዋጋው፤ ይዞም በወህኒ ቤት አሰረው።'),
  ('d7e4f440-0468-535b-a081-4b8222ef5f83', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 1, 5, 'የአሦርም ንጉሥ በምድር ሁሉ ላይ ወጣ፤ ወደ ሰማርያም ወጥቶ ሦስት ዓመት ከበባት።'),
  ('30423f27-6214-5d6e-a8a9-0b9dfd9e59ab', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 2, 6, 'በሆሴዕም በዘጠነኛው ዓመት የአሦር ንጉሥ ሰማርያን ያዘ፤ እስራኤልንም ወደ አሶር አፈለሰ፤ በአላሔና በአቦር፤ በጎዛንም ወንዝ፤ በሜዶንም ከተሞች አኖራቸው።'),
  ('3d6d1462-45a7-5b48-a90b-aba751fcda08', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 3, 7, 'የእስራኤልም ልጆች ከግብፅ ንጉሥ ከፈርዖን እጅ፥ ከግብፅ ምድር ያወጣቸውን አምላካቸውን እግዚአብሔርን በድለው ነበርና፥ ሌሎችንም አማልክት አምልከው ነበርና፤'),
  ('6caa7a39-990b-51e1-a8b4-c5f25b12c275', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 4, 8, 'እግዚአብሔርም ከእስራኤል ልጆች ፊት በአሳደዳቸው በአሕዛብ ሥርዐት፥ የእስራኤልም ነገሥታት ባደረጓት ሥርዐት ሄደው ነበርና እንደዚህ ሆነ።'),
  ('801cc7bb-23d8-5c21-ab49-0b4db60c1dea', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 5, 9, 'የእስራኤልም ልጆች በአምላካቸው በእግዚአብሔር ላይ ቅን ያልሆነን ነገር በስውር አደረጉ፤ በከተሞቻቸውም ሁሉ ከዘበኞች ግንብ ጀምሮ እስከ ተመሸገች ከተማ ድረስ በከፍታዎች ላይ መስገጃዎችን ሠሩ።'),
  ('dcfd6b98-5c41-5bda-a4ee-be0a1e30acf7', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 6, 10, 'በረጃጅሙ ኮረብታ ሁሉ ላይ፥ በለመለመውም ዛፍ ሁሉ በታች ሐውልቶችንና የማምለኪያ ዐምዶችን ተከሉ፤'),
  ('f5809322-97d8-5151-a8a8-ea406e119180', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 7, 11, 'እግዚአብሔርም ከፊታቸው ያወጣቸው አሕዛብ እንዳደረጉት፥ በኮረብቶቹ መስገጃዎች ሁሉ ላይ ያጥኑ ነበር፤ እግዚአብሔርንም ያስቈጡ ዘንድ የማምለኪያ ዐፀዶችንና ሐውልቶችን አደረጉ፤'),
  ('7196ac20-a3a1-5eb7-a989-7f899592f8eb', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 8, 12, 'እግዚአብሔርም፥ “በእግዚአብሔር ላይ ይህን አታድርጉ” ብሎ የከለከላቸውን ጣዖቶች አመለኩ።'),
  ('bfb0b2dd-9e56-58b8-ae3a-adc3bc34ffd8', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 9, 13, 'እግዚአብሔርም፥ “ከክፉ መንገዳችሁ ተመለሱ፤ ለአባቶቻችሁም እንዳዘዝሁት፥ በባሪያዎቼ በነቢያት የላክሁላችሁን ትእዛዜንና ሥርዐቴን፥ ሕጌንም ሁሉ ጠብቁ” ብሎ በነቢዩ ሁሉና በባለ ራእዩ አፍ ሁሉ በእስራኤልና በይሁዳ መሰከረ።'),
  ('c16c8257-66bc-5d00-a8ed-3ae9ef88e605', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 10, 14, 'ነገር ግን አምላካቸውን እግዚአብሔርን እንዳላመኑ ከአባቶቻቸው አንገት ይልቅ አንገታቸውን አደነደኑ እንጂ አልሰሙም።'),
  ('492a1af0-7021-5b17-a475-a88f767d32d7', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 11, 15, 'የገባላቸውንም ቃል ኪዳን ሁሉ አልጠበቁም። ከንቱ ነገርንም ተከተሉ፤ ከንቱም ሆኑ፤ እንደ እነርሱም እንዳይሠሩ ያዘዛቸውን በዙሪያቸው ያሉትን አሕዛብ ተከተሉ።'),
  ('bfcd286f-ce81-5d33-ace9-c1e3c55f26aa', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 12, 16, 'የአምላካቸውንም የእግዚአብሔርን ትእዛዝ ሁሉ ተዉ፤ ቀልጠው የተሠሩትንም የሁለቱን እንቦሶች ምስሎች አደረጉ፤ የማምለኪያ ዐፀድንም ተከሉ፤ ለሰማይም ሠራዊት ሁሉ ሰገዱ፤ በዓልንም አመለኩ።'),
  ('40a7525a-51bb-5f70-af61-a9985b3993fe', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 13, 17, 'ወንዶችና ሴቶች ልጆቻቸውንም በእሳት ሥዉአቸው፤ ምዋርተኞችና አስማተኞችም ሆኑ፤ ያስቈጡትም ዘንድ በእግዚአብሔር ፊት ክፉ ነገር ለማድረግ ራሳቸውን ሸጡ።'),
  ('a90d59e8-c54f-5453-aeeb-748c28b4bec0', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 14, 18, 'ስለዚህም እግዚአብሔር በእስራኤል ላይ እጅግ ተቈጣ፤ ከፊቱም ጣላቸው፤ ከይሁዳም ነገድ ብቻ በቀር ማንም አልቀረም።'),
  ('90589854-dd32-5f28-a3b3-926e23e58bbd', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 15, 19, 'ይሁዳም ደግሞ እስራኤል ባደረጋት ሥርዐት ሄደ እንጂ የአምላኩን የእግዚአብሔርን ትእዛዝ አልጠበቀም፤ እግዚአብሔርንም ተዉት።'),
  ('98c72c53-6edd-5e75-aaa6-ef73fe318af7', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 16, 20, 'እግዚአብሔርም በእስራኤል ዘር ሁሉ ተቈጣ፤ አስጨነቃቸውም፤ ከፊቱም እስኪጥላቸው ድረስ በበዝባዦች እጅ አሳልፎ ሰጣቸው።'),
  ('9f257809-9c45-5777-ad2e-ea5c8ad5e1c1', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 17, 21, 'እስራኤልም ከዳዊት ቤት ተለዩ፤ የናባጥንም ልጅ ኢዮርብዓምን አነገሡ፤ ኢዮርብዓምም እግዚአብሔርን ከመከተል እስራኤልን መለሰ፤ ታላቅም ኀጢአት አሠራቸው።'),
  ('df8acdfa-156c-5c5b-ad50-381cda966f19', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 18, 22, 'የእስራኤልም ልጆች ኢዮርብዓም ባደረገው ኀጢአት ሁሉ ሄዱ፤'),
  ('bc67dc2b-7d0d-56c1-aa9d-196cbcf23fc9', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 19, 23, 'እግዚአብሔርም በባሪያዎቹ በነቢያት ሁሉ አፍ እንደ ተናገረው እስራኤልን ከፊቱ እስኪያወጣ ድረስ ከእርስዋ አልራቁም። እስራኤልም እስከ ዛሬ ድረስ ከምድሩ ወደ አሦር ፈለሰ።'),
  ('c6b2d630-a3e7-57c2-a0f8-2237fa92fd8b', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 20, 24, 'የአሦርም ንጉሥ ከባቢሎንና ከኩታ፥ ከአዋና ከሐማት፥ ከሴፌርዋይም ሰዎችን አመጣ፤ በእስራኤልም ልጆች ፋንታ በሰማርያ ከተሞች አኖራቸው፤ ሰማርያንም ወረሱአት፤ በከተሞችዋም ተቀመጡ።'),
  ('ceeb3a86-6800-506e-a8d6-a5badeafda64', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 21, 25, 'በዚያም መቀመጥ በጀመሩ ጊዜ እግዚአብሔርን አይፈሩትም ነበር፤ እግዚአብሔርም አንበሶችን ሰደደባቸው፤ ይገድሉአቸውም ነበር።'),
  ('7de75326-7e69-5011-a7da-922d7f5d321f', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 22, 26, 'ስለዚህም ለአሦር ንጉሥ፥ “ያፈለስኻቸው፥ በሰማርያም ከተሞች ያኖርኻቸው ሕዝቦች የሀገሩን አምላክ ሕግ አላወቁም፤ የሀገሩን አምላክ ሕግ አላወቁምና አንበሶችን ሰድዶባቸዋል፤ እነሆም፥ እየገደሉአቸው ነው” ብለው ተናገሩት።'),
  ('cd40e187-a74e-5d88-a367-039ebeedfc49', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 23, 27, 'የአሦርም ንጉሥ፥ “ከዚያ ካመጣኋቸው ካህናት አንዱን ውሰዱ፤ ሄዶም በዚያ ይቀመጥ፤ የሀገሩንም አምላክ ሕግ ያስተምራቸው” ብሎ አዘዘ።'),
  ('0536fe8e-aeb1-5aa5-a9ae-3fa84a03c546', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 24, 28, 'ከሰማርያም ካፈለሱአቸው ካህናት አንዱን ወስደው በቤቴል አኖሩት፤ ያም ካህን እግዚአብሔርን እንዴት እንደሚፈሩት ያስተምራቸው ነበር።'),
  ('a851962c-a16b-5070-ac07-138f25aa1bc6', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 25, 29, 'በየሕዝባቸውም አምላኮቻቸውን አደረጉ፤ ሳምራውያንም በሠሯቸው በኮረብታው መስገጃዎች ሕዝቡ ሁሉ በሚኖሩባቸው ከተሞቻቸው አኖሩአቸው።'),
  ('aea15baf-fc85-59de-a85f-de829070e763', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 26, 30, 'የባቢሎንም ሰዎች ሴኬቤቴናሆምን ሠሩ፤ የኩታም ሰዎች ኤርጌትን ሠሩ፤'),
  ('c8e8cac1-c0b2-57fa-a44e-c80569d8b13c', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 27, 31, 'የሐማትም ሰዎች አሲማትን ሠሩ፤ አዋውያንም ኤልባዝርንና ተርታቅን ሠሩ፤ የሴፌርዋይም ሰዎች ለሴፌርዋይም አማልክት ለአድራሜሌክና ለአኔሜሌክ ልጆቻቸውን በእሳት ይሠዉ ነበር።'),
  ('0acf1da4-acc4-51c1-a876-d73456d6b02b', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 28, 32, 'እግዚአብሔርንም ይፈሩ ነበር፤ ሕዝቡም ሁሉ በሚኖሩበት ከተማ በሰማርያ በሠሩት በከፍታው ቦታ ጣዖቶቻቸውን አኖሩ። እግዚአብሔርንም ይፈሩ ነበር፤ ከመካከላቸውም ለኮረብታው መስገጃዎች ካህናትን አደረጉ፤ በኮረብታውም መስገጃዎች ይሠዉ ነበር።'),
  ('5c21471b-d896-5b1b-a01e-09cc5788b2ea', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 29, 33, 'እግዚአብሔርንም ሲፈሩ ከመካከላቸው እንደ ፈለሱት እንደ አሕዛብ ልማድ አምላካቸውን ያመልኩ ነበር።'),
  ('deb655e4-e9b9-58d1-a740-e1ac83c21ceb', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 30, 34, 'እስከ ዛሬም ድረስ እንደ ልማዳቸው ያደርጋሉ፤ እግዚአብሔርንም ይፈራሉ፤ እግዚአብሔርም እስራኤል ብሎ የጠራውን የያዕቆብን ልጆች እንዳዘዛቸው ሥርዐትና ፍርድ፥ ሕግና ትእዛዝም ያደርጋሉ።'),
  ('d835568b-3023-5f57-a868-946fec4c4c0f', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 31, 35, 'እግዚአብሔርም ከእነርሱ ጋር ቃል ኪዳን አደረገ፤ እንዲህም ብሎ አዘዛቸው፥ “ሌሎችን አማልክት አትፍሩአቸው፤ አትስገዱላቸውም፤ አታምልኩአቸውም፤ አትሠዉላቸውም።'),
  ('46138820-15ae-5ab7-a9fe-18bbe0a15fad', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 32, 36, 'ነገር ግን በታላቅ ኀይል በተዘረጋችም ክንድ ከግብፅ ምድር ያወጣችሁን እግዚአብሔርን እርሱን ፍሩ፤ ለእርሱም ስገዱ፤ ለእርሱም ሠዉ።'),
  ('0ee5f8dd-eb09-5a0d-a5f1-07e75ad1484c', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 33, 37, 'የጻፈላችሁንም ሥርዐትና ፍርድ፥ ሕግና ትእዛዝም ለዘለዓለም ታደርጉ ዘንድ ጠብቁ፤ ሌሎችንም አማልክት አትፍሩ።'),
  ('78c8826b-ee5b-543d-a484-cacb5498a936', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 34, 38, 'ከእናንተም ጋር ያደረገውን ቃል ኪዳን አትርሱ፤ ሌሎችንም አማልክት አትፍሩ።'),
  ('0cdf82cc-72fd-5653-a76d-07284485ee5e', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 35, 39, 'ነገር ግን አምላካችሁን እግዚአብሔርን ፍሩ፤ እርሱም ከጠላቶቻቸሁ ሁሉ እጅ ያድናችኋል።'),
  ('9cc9f016-04c5-5766-ab3d-ac694620d5e5', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 36, 40, 'ነገር ግን እነርሱ እንደሚያደርጉት ልማዳቸውን አትስሙ።'),
  ('b1f96cbd-944a-5f21-ae26-e249f4bb0780', 'f2ded0e2-2bfe-5faa-a4c1-1709d762a998', '2bcd1f69-ba2f-5eb7-a3a8-d03d9d961e0b', 37, 41, 'እነዚህም አሕዛብ እግዚአብሔርን ይፈሩ ነበር፤ ደግሞም የተቀረጹ ምስሎቻቸውን ያመልኩ ነበር፤ ልጆቻቸውም፥ የልጅ ልጆቻቸውም አባቶቻቸው እንዳደረጉ እስከ ዛሬ ድረስ እንዲሁ ያደርጋሉ።”'),
  ('5f493b7a-fc3b-51eb-a845-e5259f2df020', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 1, 1, 'እንዲህም ሆነ፤ የእስራኤል ንጉሥ የኤላ ልጅ ሆሴዕ በነገሠ በሦስተኛው ዓመት የይሁዳ ንጉሥ የአካዝ ልጅ ሕዝቅያስ ነገሠ።'),
  ('43582b68-1737-5682-aaa7-99cd19341b14', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 2, 2, 'መንገሥ በጀመረ ጊዜም የሃያ አምስት ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ሃያ ዘጠኝ ዓመት ነገሠ፤ እናቱም የዘካርያስ ልጅ አቡ ትባል ነበር።'),
  ('e498c300-b697-5a73-ac5b-859638d2070e', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 3, 3, 'እርሱም አባቱ ዳዊት እንዳደረገው ሁሉ በእግዚአብሔር ፊት ቅን ነገርን አደረገ።'),
  ('187581e9-e247-5a26-a7f2-e17cec8debc6', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 4, 4, 'በኮረብታም ያሉትን መስገጃዎች አስወገደ፤ ሐውልቶችንም ሰባበረ፤ የማምለኪያ ዐፀዶችንም ነቃቀለ፤ የእስራኤል ልጆች እስከዚህ ዘመን ድረስ ያጥኑለት ነበርና ሙሴ የሠራውን የናሱን እባብ አጠፋ፤ ስሙንም “ነሑስታን” ብሎ ጠራው።'),
  ('ad9b35eb-4171-5de6-a0a6-c2810db13073', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 5, 5, 'በእስራኤልም አምላክ በእግዚአብሔር ታመነ፤ ከእርሱ በፊት ከነበሩት ከይሁዳ ነገሥታት ሁሉ እርሱን የሚመስል አልነበረም።'),
  ('1f5bbc17-57e6-539a-a43d-f00b8d5f68b6', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 6, 6, 'እግዚአብሔርንም ተከተለ፤ እርሱንም ከመከተል አልራቀም፤ እግዚአብሔርም ለሙሴ ያዘዘውን ትእዛዛቱን ጠበቀ።'),
  ('e7aefb7c-a30b-507b-a5eb-80a54bbb05da', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 7, 7, 'በሚሠራውም ሥራ ሁሉ እግዚአብሔር ከእርሱ ጋር ነበረ፤ በአሦርም ንጉሥ ላይ ዐመፀ፤ አልተገዛለትምም።'),
  ('6b1a6bf1-aaa1-5c3b-ab2f-308c565cbd62', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 8, 8, 'ፍልስጥኤማውያንንም እስከ ጋዛና እስከ ዳርቻዋ ድረስ፥ ከዘበኞች ግንብ ጀምሮ እስከ ምሽጉ ከተማ ድረስ አጠፋ።'),
  ('86e0612a-1ddf-5192-acb9-7fbbc6c22463', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 9, 9, 'ሕዝቅያስ በነገሠ በአራተኛው ዓመት፥ የእስራኤል ንጉሥ የኤላ ልጅ ሆሴዕ በነገሠ በሰባተኛው ዓመት፥ የአሦር ንጉሥ ስልምናሶር ወደ ሰማርያ ወጣ፤ ከበባትም።'),
  ('332a1b02-1aa3-547e-a41c-ff89a61afd62', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 10, 10, 'በሦስተኛውም ዓመት ያዛት፤ በሕዝቅያስ በስድስተኛው ዓመተ መንግሥት፥ በእስራኤል ንጉሥ በሆሴዕ በዘጠነኛው ዓመተ መንገሥት፥ ሰማርያ ተያዘች።'),
  ('472aca29-f2af-5dcd-a576-99b0f7b1a66c', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 11, 11, 'የአሦርም ንጉሥ እስራኤልን ወደ አሦር አፈለሰ፤ በአላሔና በአቦር በጎዛንም ወንዝ፥ በሜዶንም አውራጃዎች አኖራቸው፤'),
  ('1151ba89-ea27-53a3-abbf-f705d3e75129', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 12, 12, 'የአምላካቸውን የእግዚአብሔርን ቃል አልሰሙምና፥ ቃል ኪዳኑንም አፍርሰዋልና፥ የእግዚአብሔርም ባሪያ ሙሴ ያዘዘውን ሁሉ አልሰሙምና፤ አላደረጉምምና።'),
  ('a61a27ac-fa3e-57e9-a390-650eb831b3f4', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 13, 13, 'ሕዝቅያስም በነገሠ በዐሥራ አራተኛው ዓመት የአሦር ንጉሥ ሰናክሬም ወደ ይሁዳ ወደ ተመሸጉት ከተሞች ሁሉ ወጣ፤ ወሰዳቸውም።'),
  ('1c46cfc1-39d3-5916-ac08-23151be9dcd3', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 14, 14, 'የይሁዳም ንጉሥ ሕዝቅያስ፥ “በድያለሁ፥ ከእኔ ተመለስ፤ የምትጭንብኝንም ሁሉ እሸከማለሁ” ብሎ ወደ አሦር ንጉሥ ወደ ለኪሶ መልእክተኞችን ላከ። የአሦርም ንጉሥ በይሁዳ ንጉሥ በሕዝቅያስ ላይ ሦስት መቶ መክሊት ብርና ሠላሳ መክሊት ወርቅ ጫነበት።'),
  ('ac3b74f1-1db3-5400-a2db-9b652b516d62', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 15, 15, 'ሕዝቅያስም በእግዚአብሔር ቤትና በንጉሡ ቤተ መዛግብት የተገኘውን ብር ሁሉ ሰጠው።'),
  ('d7881e8a-c1ef-51b7-a58e-d424225856f6', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 16, 16, 'በዚያን ጊዜም ሕዝቅያስ ከእግዚአብሔር መቅደስ ደጆችና የይሁዳ ንጉሥ ሕዝቅያስ ከለበጣቸው መቃኖች ወርቁን ቈረጠ፤ ለአሦርም ንጉሥ ሰጠው።'),
  ('ae55ac3d-9d21-5389-a486-9a78b195cded', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 17, 17, 'የአሦርም ንጉሥ ተርታንንና ራፌስን ራፋስቂስንም ከብዙ ሠራዊት ጋር ከለኪሶ ወደ ንጉሡ ወደ ሕዝቅያስ ወደ ኢየሩሳሌም ላካቸው። ወጥተውም ወደ ኢየሩሳሌም ደረሱ፤ በአጣቢውም እርሻ መንገድ ባለችው በላዪኛዪቱ ኩሬ መስኖ አጠገብ ቆሙ።'),
  ('c767c706-bfa4-5922-acfd-b0a18bec6dba', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 18, 18, 'ሕዝቅያስንም ጠሩ፤ የቤቱም አዛዥ የኬልቅዩ ልጅ ኤልያቄም ጸሓፊውም ሳምናስ ታሪክ ጸሓፊውም የአሳፍ ልጅ ዮአስ ወደ እነርሱ ወጡ።'),
  ('ce799449-2386-5d49-ae5b-67d41ace3ca7', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 19, 19, 'ራፋስቂስም አላቸው፥ “ለሕዝቅያስ እንዲህ ብላችሁ ንገሩት፦ ታላቁ ንጉሥ የአሦር ንጉሥ እንዲህ ይላል፦ ይህ የምትተማመንበት መተማመኛ ምንድን ነው?'),
  ('8bba50ae-e44a-54a1-a235-2c3e36b103a4', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 20, 20, 'የከንፈር ቃል ለሰልፍ ምክርና ኀይል እንደሚሆን ትናገራለህ፤ አሁንም በእኔ ላይ ያመፅኸው በማን ተማምነህ ነው?'),
  ('ecbe88af-41ea-5a1d-ab22-1345d434501d', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 21, 21, 'እነሆ፥ በዚህ በተቀጠቀጠ በሸምበቆ በትር በግብፅ ትታመናለህ፤ ሰው ቢመረኰዘው ተሰብሮ በእጁ ይገባል፥ ያቈስለውማል፤ የግብፅ ንጉሥ ፈርዖን ለሚታመኑበት ሁሉ እንዲሁ ነው።'),
  ('7c287f0a-3640-589a-a2b5-ab352f4b1ed9', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 22, 22, 'እናንተም፦ በአምላካችን በእግዚአብሔር እንታመናለን ብትሉኝ፥ ሕዝቅያስ ይሁዳንና ኢየሩሳሌምን፦ በኢየሩሳሌም ባለው በዚህ መሠዊያ ፊት ስገዱ ብሎ የኮረብታ መስገጃዎቹንና መሠዊያዎቹን ያስፈረሰ ይህ አይደለምን?'),
  ('eb82ebea-b0a1-5aa1-a3d2-1a9025f766b9', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 23, 23, 'አሁንም እንግዲህ ከጌታዬ ከአሦር ንጉሥ ጋር ተወራረድ፤ የሚቀመጡባቸውንም ሰዎች ማግኘት ቢቻልህ እኔ ሁለት ሺህ ፈረሶች እሰጥሃለሁ።'),
  ('042d896f-8d1a-5e86-ad85-324cbc26003a', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 24, 24, 'ስለ ሰረገሎችና ስለ ፈረሶች በግብፅ ስትታመን፥ ከጌታዬ አገልጋዮች የሚያንሰውን የአንዱን አለቃ ፊት ትመልስ ዘንድ እንዴት ይቻልሃል?'),
  ('364d2691-aaf8-5555-a637-03228aed9880', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 25, 25, 'አሁን በውኑ ያለ እግዚአብሔር ትእዛዝ ይህን ስፍራ እናጠፋ ዘንድ ወጥተናልን? እግዚአብሔር፦ ወደዚች ሀገር ወጥታችሁ አጥፉአት አለን።”'),
  ('f875a029-1247-5f64-ac0f-56d4c830bbbd', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 26, 26, 'የኬልቅዩም ልጅ ኤልያቄም ሳምናስም ዮአስም ራፋስቂስን፥ “እኛ እንሰማለንና በሱርስት ቋንቋ ለአገልጋዮችህ ተናገር፤ በዕብራይስጥም ቋንቋ አትናገረን፤ በቅጥርም ላይ ያለው ሕዝብ በሚሰማው ቋንቋ ለምን ትናገራለህ?” አሉት።'),
  ('f4188481-4882-5177-a0b7-bfeddda3879b', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 27, 27, 'ራፋስቂስ ግን፥ “በውኑ ጌታዬ ይህን ቃል እናገር ዘንድ ወደ እናንተና ወደ ጌታችሁ ልኮኛልን? ከእናንተ ጋር ኵሳቸውን ይበሉ ዘንድ ሽንታቸውንም ይጠጡ ዘንድ በቅጥር ላይ ወደ ተቀመጡት ሰዎች አይደለምን?” አላቸው።'),
  ('b5be51c0-b33e-546e-ac00-0d30e9ca2f78', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 28, 28, 'ራፋስቂስም ቆሞ በታላቅ ድምፅ በዕብራይስጥ ቋንቋ እንዲህ ብሎ ጮኸ፥ “የታላቁን የአሦር ንጉሥ ቃል ስሙ፤'),
  ('784eed6f-8dae-54c6-a88e-77604ba8a19c', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 29, 29, 'ንጉሥ እንዲህ ይላል፦ ከእጄ ያድናችሁ ዘንድ አይችልምና ሕዝቅያስ አያታልላችሁ፤'),
  ('1335ebab-d3d0-5bde-a3d3-6fcaed28e6f4', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 30, 30, 'ሕዝቅያስም፦ እግዚአብሔር በእርግጥ ያድነናል፤ ይህችንም ከተማ የአሦር ንጉሥ ሊይዛት አይችልም እያለ በእግዚአብሔር እንድትታመኑ አያድርጋችሁ።'),
  ('aeafdd91-f64f-563d-ae44-d88c13214dc6', '82c8e66d-761d-55d9-a9a0-babc2e30ff95', 'c8f0b56f-9a7d-59d7-a229-8e6951bdd281', 31, 31, 'ሕዝቅያስንም አትስሙ፤ የአሶር ንጉሥ እንዲህ ይላል፦ ከእኔ ጋር ታረቁ፤ ወደ እኔም ውጡ፤ እያንዳንዳችሁም ከወይናችሁና ከበለሳችሁ ብሉ፤ ከጕድጓዳችሁም ውኃ ጠጡ፤')
